window.__LEX={"G5300":"<h1>hus</h1>\n<p>Strong n° 5300 <i>Prononciation [hoos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cochon, truie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὗς, ὑΐ, ὗν</b>, <i>pl</i>. <b>ὗες, ὑῶν, ὑσί, ὗς (ὁ, ἡ)</b> <span>[ῡ <i>aux cas monosyll., ῠ aux cas dissyll</i>.]</span><br><b>      1</b> <i>masc</i>. porc <i>ou</i> sanglier, <i>fém</i>. truie <i>ou</i> laie, IL. <i>10, 264, etc. ;</i> OD. <i>15, 307, 556, etc. ;</i> ὗς ἄγριος, HDT. <i>4, 192 ;</i> XÉN. <i>Cyr. 1, 6, 82, etc</i>. sanglier ; <i>au fém</i>. ὗς ἀγρία, ARSTT. <i>H.A. 6, 28, 1,</i> laie ; ὗς Βοιωτία, PD. <i>O. 6, 153,</i> porc de Béotie, <i>en parl. d’un homme grossier ;</i> ὗς ποτ' Ἀθηναίαν ἔριν ἤρισε, THCR. <i>Idyl. 5, 23 ; ou simpl</i>. ἡ ὗς τὴν Ἀθηνᾶν, PLUT. <i>Dem. 11,</i> un porc a cherché querelle à Athèna, <i>càd</i>. un ignorant veut faire la leçon à un homme instruit ; λύσω τὴν ἐμὴν ὗν, AR. <i>Lys. 684,</i> je délierai ma laie, <i>càd</i>. je donnerai libre cours à ma colère ;<br><b>      2</b> <i>c</i>. ὕαινα, EPICH. <i>et</i> ARCHESTR. (ATH. <i>326 e et f</i>) ;<br><b>      3</b> sorte de plante d’où l’on tire la teinture ὕσγινον, PAUS. <i>10, 36, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. seul</i>. ὗς, <i>non</i> σῦς, <i>v. Meisterh. p. 109, § 53, 6</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *suH-s, porc ; <i>cf</i>. σῦς.</span></span><br><br>\n➁ <b>ὗς</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υς - ὗς</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5301":"<h1>hussopos</h1>\n<p>Strong n° 5301 <i>Prononciation [hoos'-so-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>hysope</li>\n<li>une plante utilisée par les Hébreux dans leurs aspersions rituelles</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕσσωπος, ου (ἡ)</b> hysope, <i>plante aromatique,</i> NIC. <i>Th. 872 ;</i> ATH. <i>156</i> e ; DIOSC. <i>3, 30, etc</i>.<br><span><b><span class=\"arrow\"></span></b> ὁ ὕσσ. HIPPIATR. <i>p. 272, 287</i>.<br><span><b>Étym</b>. <i>hébr</i>. êzôb.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υσσωπος - ὕσσωπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5302":"<h1>hustereo</h1>\n<p>Strong n° 5302 <i>Prononciation [hoos-ter-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>derrière\n<ol type=\"a\">\n<li>venir en retard ou trop tardivement\n<ol>\n<li>être laissé derrière dans la course et ainsi ne pas pouvoir atteindre le but, tomber près du but</li>\n<li>métaph. manquer de devenir un participant</li>\n</ol>\n</li>\n<li>être inférieur en pouvoir, influence et rang\n<ol>\n<li>d'une personne : être inférieur à</li>\n</ol>\n</li>\n<li>manquer, être dans le besoin</li>\n</ol>\n</li>\n<li>souffrir d'un besoin, être dépourvu de, manquer (être inférieur) en excellence, en valeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑστερέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ὑστέρησα, <i>pf</i>. ὑστέρηκα ; <i>pass. seul. ao</i>. ὑστερήθην)</span><br><b>A <i>intr</i>.<br>   I</b> (<i>avec un suj. de pers</i>.) être en arrière, <i>d’où :</i><br><b>      1</b> venir trop tard, être en retard, HDT. <i>1, 70 ;</i> XÉN. <i>Hell. 5, 1, 3 ;</i> PLAT. <i>Gorg. 447</i> c, <i>etc. ;</i> ὑστερεῖν τινος εἰς τόπον, XÉN. <i>Hell. 3, 5, 25,</i> arriver après qqn dans un lieu ; ὑ. μάχης, XÉN. <i>An. 1, 7, 12,</i> n’arriver qu’après le combat ; τῆς πατρίδος, XÉN. <i>Ages. 2, 1,</i> venir trop tard au secours de sa patrie ; τῶν καιρῶν, ARSTT. <i>Soph. el. 16, 5,</i> manquer les occasions ; τῆς βοηθείας, DS. <i>13, 110 ; ou avec le dat. :</i> τῇ βοηθείᾳ, DÉM. <i>1346, 9,</i> apporter du secours trop tard ;<br><b>      2</b> <i>fig</i>. être en arrière de : τινος, DÉM. <i>447, 25, etc</i>. être inférieur à qqn ; ἔν τινι, PLAT. <i>Rsp. 484</i> d, en qqe ch. ; τινί τινος, PLAT. <i>Rsp. 539</i> e, à qqn en qqe ch. ;<br><b>      3</b> être en arrière de, manquer de : πολλῶν, DÉM. <i>447, 28,</i> être dépourvu de beaucoup de choses ; <i>abs</i>. être dans le besoin, NT. <i>Luc. 15, 14 ; 1Cor. 8, 8 ;</i><br><b>   II</b> (<i>avec un suj. de ch</i>.) être en arrière, être insuffisant, faire défaut, DIOSC. <i>5, 86 ;</i> ὑστερήσαντος οἴνου, NT. <i>Joh. 2, 3,</i> le vin ayant manqué ;<br><b>B <i>tr.</i></b> laisser en arrière, <i>d’où</i> priver de : οἴνου ὑστερηθῆναι, JOS. <i>A.J. 15, 6, 7,</i> manquer (<i>litt</i>. être privé) de vin ;<br><b><i>Moy.</i></b> manquer de, <i>gén</i>. DS. <i>18, 71 ;</i> NT. <i>Rom. 3, 23</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy</i>. ὑστερήσομαι <i>au sens pass</i>. EUR. <i>I.A. 1203</i>.<br><span><b>Étym</b>. ὕστερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υστερεω - ὑστερέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G5303":"<h1>husterema</h1>\n<p>Strong n° 5303 <i>Prononciation [hoos-ter'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>insuffisance, ce qui est manquant</li>\n<li>en référence à la propriété et aux ressources, la pauvreté, le besoin, la destitution</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑστέρημα, ατος (τὸ)</b> manque, pénurie, indigence, SPT. <i>Ps. 33, 101 ;</i> NT. <i>Luc. 21, 4, etc</i>.<br><span><b>Étym</b>. ὑστερέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υστερημα - ὑστέρημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (4)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5304":"<h1>husteresis</h1>\n<p>Strong n° 5304 <i>Prononciation [hoos-ter'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>besoin, pauvreté, manque, indigence, privation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑστέρησις, εως (ἡ)</b> <i>c</i>.  NT. <i>Marc. 12, 44 ; Phil. 4, 11</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υστερησις - ὑστέρησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5305":"<h1>husteron</h1>\n<p>Strong n° 5305 <i>Prononciation [hoos'-ter-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dernier, plus tard, venant après, le second</li>\n<li>ensuite, après ceci, enfin, dernièrement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕστερον</b>, <i>neutre adv. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υστερον - ὕστερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5306":"<h1>husteros</h1>\n<p>Strong n° 5306 <i>Prononciation [hoos'-ter-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dernier, plus tard, venant après, le second</li>\n<li>ensuite, après ceci, enfin, dernièrement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕστερος, α, ον :<br>A<br>      1</b> (<i>avec idée de lieu</i>) qui est <i>ou</i> vient derrière, ATT. ; ὕ. τινος, THC. <i>3, 103, etc</i>. qui se trouve derrière qqn ; οἱ δ' ἄλλοι ὕστεροι ἡμῶν ᾔεσαν, PLAT. <i>Lys. 206</i> e, les autres venaient derrière nous ; τὰ ὕστερα, HPC. <i>104</i> f, <i>1255</i> a ; ARSTT. <i>H.A. 7, 9, 10,</i> le train de derrière, l’arrière-faix ;<br><b>      2</b> (<i>avec idée de temps</i>) qui a lieu <i>ou</i> se fait après : σεῦ ὕστερον εἶμ' ὑπὸ γαῖαν, IL. <i>18, 333,</i> je descendrai sous terre après toi ; ὑστέρῃ ὀλυμπιάδι, HDT. <i>6, 103,</i> à l’olympiade suivante ; ὑστέρῳ χρόνῳ, HDT. <i>1, 130 ; 3, 149 ;</i> ESCHL. <i>Ag. 702 ;</i> SOPH. <i>Tr. 18, etc. ;</i> ἐν ὑστέροις χρόνοις, PLAT. <i>Leg. 865</i> a, dans les temps postérieurs ; ἡ ὑστέρα (<i>s.-e</i>. ἡμέρα) PLUT. <i>M. 320</i> e, le lendemain ; ἐξ ὑστέρης, HDT. <i>1, 108 ; 5, 106 ; 6, 85,</i> plus tard ; ἐς τὴν ὑστέραν, EL. <i>N.A. 7, 7,</i> dans la suite ; <i>avec un gén. :</i> ὑστέρῳ χρόνῳ τούτων, HDT. <i>4, 166 ; 5, 32,</i> dans le temps qui suivit ces événements ; <i>particul</i>. qui a lieu <i>ou</i> vient trop tard, THC. <i>4, 90 ;</i> AR. <i>Vesp. 691 ; avec le gén. :</i> ὕστεροι ἀφίκοντο τῆς μάχης, PLAT. <i>Leg. 698</i> e, ils arrivèrent après le combat ; <i>abs</i>. ὕστερος, SOPH. <i>O.R. 222, Tr. 92,</i> qui arrive postérieurement, ensuite <i>ou</i> trop tard : γένει ὕστερος, IL. <i>3, 215,</i> plus jeune ; <i>subst</i>. οἱ ὕστεροι, EUR. <i>Suppl. 1225, etc</i>. les descendants, la postérité ; <i>pour marquer la succession :</i> Διονύσιος ὁ ὕ. ARSTT. <i>Pol. 5, 10, 23,</i> Denys le jeune ;<br><b>      3</b> qui vient après, qui le cède à, inférieur à : τινος, ESCHL. <i>Eum. 251,</i> à qqe ch. γυναικός, SOPH. <i>Ant. 746,</i> qui le cède à une femme ; οὐδενὸς ὕστερος, THC. <i>1, 91 ;</i> SOPH. <i>Ph. 181, etc</i>. qui ne le cède à personne ; ὕστερος τινός τινι, THC. <i>1, 91 ;</i> PLAT. <i>Tim. 20</i> a ; <i>ou</i> τινός τι, PAUS. <i>9, 3, 1,</i> inférieur en qqe ch. à qqn ; σῶμα ὕστερον ψυχῆς, PLAT. <i>Leg. 896</i> c, le corps inférieur à l’âme ; νομίσας πάντα ὕστερα εἶναι πρός τι, THC. <i>8, 41,</i> ayant pensé que tout était secondaire comparé à qqe ch. ; <i>abs</i>. μὴ ἔμπροσθεν τῶν νόμων, ἀλλ' ὕστερος πολιτεύου, ESCHN. <i>57, 11,</i> gouverne l’État non en te mettant au-dessus des lois, mais en te subordonnant à elles ; ἐν ὑστέρῳ τίθεσθαί τινος, PLUT. <i>Arist. 6,</i> mettre une ch. au-dessous d’une autre ; ὕστερον αὑτὸν τοῦ νόμου τιθέναι, PLUT. <i>Fab. 24,</i> se soumettre à la loi ;<br><b>B</b> <i>adv</i>., ὕστερον :<br><b>   I</b> (<i>avec idée de lieu</i>) derrière, ESCHL. <i>fr. 269, 3 ;</i> ὕ. τῶν ἱππέων, XÉN. <i>Cyr. 5, 3, 42,</i> derrière les cavaliers ;<br><b>   II</b> (<i>avec idée de temps</i>) plus tard, HDT. <i>6, 90 ;</i> THC. <i>5, 76 ;</i> SOPH. <i>Aj. 858, etc. ;</i> τὸ ὕστερον, LYCURG. <i>155, 32, m. sign. p. opp. à</i> τὸ παλαιόν ; ὕστερα, OD. <i>16, 319, m. sign. ; avec une particule :</i> ὕστερον αὖτις, IL. <i>1, 27 ;</i> αὖθις ὕστερον, SOPH. <i>Aj. 858, etc</i>. plus tard, ensuite ; <i>avec un mot marquant une idée de temps :</i> χρόνῳ ὕστερον, THC. <i>1, 64 ;</i> ὕ. χρόνῳ, THC. <i>1, 8 ;</i> PLAT. <i>Leg. 867</i> a, <i>etc. ;</i> χρόνοις ὕ. LYS. <i>99, 40,</i> plus tard ; χρόνῳ ὕστερον πολλῷ, HDT. <i>1, 171, ou simpl</i>. πολλῷ ὕστερον, PLAT. <i>Phæd. 58</i> a, longtemps après ; βραχεῖ χρόνῳ ὕστερον, XÉN. <i>Cyr. 5, 3, 52,</i> peu de temps après ; ὀλίγῳ ὕ. PLAT. <i>Rsp. 327</i> b ; ὀλίγον ὕ. PLAT. <i>Gorg. 471</i> b, <i>m. sign. ;</i> οὐ πολλαῖς ἡμέραις ὕ. XÉN. <i>Hell. 1, 1, 1,</i> peu de jours après ; <i>avec un gén</i>. ὕστερον τούτων, HDT. <i>1, 113, etc</i>. à la suite de ces événements ; τῆς γνώμης ὕ. HDT. <i>2, 18,</i> postérieurement à l’opinion que je m’étais formée ; τοῦ δέοντος ὕ. AR. <i>Lys. 57,</i> plus tard qu’il ne faudrait ; <i>avec un dat. et suivi d’un rég. au gén. :</i> ἔτεσι πολλοῖσι ὕστερον τούτων, HDT. <i>6, 140,</i> bien des années après ces événements ; πολλῷ ὕ. τῶν Τρωϊκῶν, THC. <i>1, 3,</i> longtemps après les événements de Troie ; <i>cf</i>. PLAT. <i>Leg. 698</i> e ; <i>avec un dat. et suivi de</i> ἤ : τεσσαρακοστῇ ἡμέρᾳ ὕστερον ἢ Ποτείδαια ἀπέστη, THC. <i>1, 60,</i> le quarantième jour après la défection de Potidée ; <i>avec des prép. :</i> ἐς ὕστερον, OD. <i>12, 126 ;</i> HDT. <i>5, 41, etc</i>. plus tard, dans la suite ; ἐν ὑστέρῳ, THC. <i>3, 13 ; 8, 27, m. sign. ;</i> ἐξ ὑστέρου, DS. <i>14, 109 ;</i> DH. <i>4, 73, m. sign. ;</i> μεθ' ὕστερον, EL. <i>N.A. 15, 9, m. sign. ; avec l’art. :</i> οἱ ὕστεροι, PLAT. <i>Rsp. 415</i> d, les descendants, la postérité ; τὰ ὕστερον γράμματα, PLAT. <i>Charm. 165</i> a, les lettres d’après.<br><span><b>Étym</b>. <i>indo-europ</i>. *ud-tero-, plus haut, extérieur, <i>de la</i> R. *ud-, en haut, dehors ; <i>cf. sscr</i>. úttara- ; <i>cf</i>. ὕστατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υστερος - ὕστερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5307":"<h1>huphantos</h1>\n<p>Strong n° 5307 <i>Prononciation [hoo-fan-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tissé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑφαντός, ή, όν</b> <span>[ῠ]</span> tissé, OD. <i>13, 136, 218 ; 16, 231 ;</i> ESCHL. <i>Ag. 1580 ;</i> SOPH. <i>Tr. 1052 ;</i> EUR. <i>Ion 1146 ;</i> LUC. <i>V.H. 1, 25 ;</i> τὰ ὑφαντά, THC. <i>2, 97,</i> les étoffes brodées.<br><span><b>Étym</b>. <i>vb. de</i> ὑφαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υφαντος - ὑφαντός</font>\n<br><br>vient de huphaino (tisser)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5308":"<h1>hupselos</h1>\n<p>Strong n° 5308 <i>Prononciation [hoop-say-los']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>haut, élevé\n<ol type=\"a\">\n<li>élevé en hauteur</li>\n<li>avec un bras levé, c.à.d. donnant un signal</li>\n</ol>\n</li>\n<li>métaph. éminent, exalté, élevé\n<ol type=\"a\">\n<li>en influence et honneur</li>\n<li>élever son esprit, rechercher les grandes choses (honneurs et richesses), aspirer à</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑψηλός, ή, όν</b>, haut, élevé : πύργος, IL. <i>3, 384,</i> haute tour ; τεῖχος, THC. <i>7, 4,</i> mur élevé ; χώρη ὑψηλή, HDT. <i>1, 110,</i> région élevée ; ὑψηλὰ χωρία, THC. <i>3, 97, ou abs</i>. ὑψηλά, PLAT. <i>Leg. 732</i> c, hauteurs ; ἐν ὑψηλῷ εἶναι, PLUT. <i>Eum. 17,</i> être sur une hauteur ; ἀφ' ὑψηλοῦ, PLAT. <i>Theæt. 175</i> d, d’une hauteur, d’en haut ; <i>fig. :</i><br><b>      1</b> <i>en parl. du caractère,</i> PLUT. <i>Dio. 4 ;</i> LUC. <i>Nigr. 25 ; en parl. des pensées, du style,</i> LGN <i>40, 2 ; 43, 3 ;</i> DH. <i>Lys. 13 ;</i> PLUT. <i>Per. 5 ; en parl. de la prospérité, de la gloire, etc</i>. PD. <i>O. 2, 38 ; 5, 1, etc. ;</i> EUR. <i>Hel. 418, etc. ;</i> τὰ ὑψηλά, EUR. <i>Her. 613,</i> les sommets ;<br><b>      2</b> <i>en mauv. part,</i> hautain, fier, orgueilleux, SOPH. <i>Aj. 1230 ;</i> EUR. <i>Hipp. 730 ;</i> PLAT. <i>Rsp. 494</i> d.<br><span>•<i> Cp</i>. -ότερος, THC. <i>7, 4 ;</i> XÉN. <i>Hell. 6, 2, 29 ;</i> LUC. <i>Nigr. 25 ;</i> LGN <i>43, 3, etc. ;</i> <i>• Sup</i>. -ότατος, ATT. ; <i>irrég</i>. -έστατος, PAUS. <i>5, 13, 9</i>.<br><span><b>Étym</b>. ὕψος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υψηλος - ὑψηλός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5309":"<h1>hupselophroneo</h1>\n<p>Strong n° 5309 <i>Prononciation [hoop-say-lo-fron-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avoir un esprit hautain, être orgueilleux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑψηλοφρονέω-ῶ</b>, être hautain, orgueilleux, NT. <i>Rom. 11, 20 ; 1Tim. 6, 17</i>.<br><span><b>Étym</b>. ὑψηλόφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υψηλοφρονεω - ὑψηλοφρονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5310":"<h1>hupsistos</h1>\n<p>Strong n° 5310 <i>Prononciation [hoop'-sis-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>très haut, le plus haut\n<ol type=\"a\">\n<li>d'un endroit : les lieux très hauts</li>\n<li>d'un rang : le Dieu Très-Haut</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕψιστος, η, ον</b>, très haut, très élevé, <i>au pr</i>. ESCHL. <i>Pr. 720 ;</i> SOPH. <i>Tr. 1191, etc. ;</i> ἐν τοῖς ὑψίστοις, NT. <i>Matth. 21, 9 ; Luc. 2, 24,</i> au plus haut des cieux ; <i>fig</i>. ὕ. Ζεύς, PD. <i>N. 1, 90 ; 11, 2 ;</i> ESCHL. <i>Eum. 28 ; cf</i>. SOPH. <i>Ph. 1289,</i> Zeus, le dieu suprême ; κακῶν ὕψιστα, ESCHL. <i>Pers. 331, 807,</i> les plus grands des maux.<br><span><b>Étym</b>. sup. <i>de</i> ὕψι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υψιστος - ὕψιστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (7)</li>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5311":"<h1>hupsos</h1>\n<p>Strong n° 5311 <i>Prononciation [hoop'-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>hauteur\n<ol type=\"a\">\n<li>d'une mensuration</li>\n<li>d'un lieu : le ciel</li>\n<li>métaph. le rang, une position élevée</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕψος, εος-ους (τὸ) :<br>      1</b> hauteur, élévation, ESCHL. <i>Ag. 1376 ;</i> THC. <i>1, 91 ; 2, 75 ; 4, 13 ;</i> EUR. <i>Ph. 404, etc. ;</i> ἐς ὕψος, HDT. <i>5, 13, 155 ; ou abs</i>. ὕψος, HDT. <i>1, 50, 178 ;</i> XÉN. <i>An. 3, 4, 7,</i> en hauteur ; <i>fig. en parl. de l’élévation du style,</i> LGN <i>1, 1, etc. ; au plur</i>. LGN <i>3, 4 ; 7, 4 ;</i><br><b>      2</b> <i>particul</i>. cime, sommet, EUR. <i>Bacch. 1101 ; au plur</i>. PLAT. <i>Leg. 625</i> b ; <i>fig</i>. ὑ. ἀμαθίας, PLAT. <i>Ep. 351</i> e, le comble de l’ignorance ; <i>cf</i>. ARSTT. <i>Mund. 6, 8 ; au plur</i>. PLAT. <i>Tim. 46</i> c.<br><span><b>Étym</b>. <i>indo-europ</i>. *up-s-, en haut ; <i>élargissement de</i> *up(-), <i>v</i>. ὑπό, ὕπατος ; <i>cf</i>. ὕψι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υψος - ὕψος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Ephésiens (2)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5312":"<h1>hupsoo</h1>\n<p>Strong n° 5312 <i>Prononciation [hoop-so'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>élever vers les hauteurs, exalter</li>\n<li>métaph.\n<ol type=\"a\">\n<li>élever vers le sommet de l'opulence et de la prospérité</li>\n<li>exalter, élever à la dignité, aux honneurs et au bonheur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑψόω-ῶ</b>, élever, dresser, <i>acc</i>. BATR. <i>81 ;</i> A. PL. <i>41 ; fig. :</i><br><b>      1</b> relever, améliorer, MÉN. (CLÉM. <i>721</i>) ;<br><b>      2</b> exalter, glorifier, PLUT. <i>M. 103</i> e ; NT. <i>Matth. 23, 12 ; Luc. 14, 11 ; p. opp. à</i> ταπεινοῦν, POL. <i>5, 26, 12 ; au pass</i>. se glorifier, se vanter de, <i>dat</i>. ANTH. <i>5, 92</i> ;<br><i><b>Moy</b>. :</i><br><b>      1 <i>intr.</i></b> se lever, HPC. <i>27, 11 ;</i><br><b>      2 <i>tr.</i></b> élever, ériger, ANTH. <i>7, 55</i>.<br><span><b>Étym</b>. ὕψος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υψοω - ὑψόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 16 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (6)</li>\n<li>Jean (5)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5313":"<h1>hupsoma</h1>\n<p>Strong n° 5313 <i>Prononciation [hoop'-so-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chose élevée, hauteur\n<ol type=\"a\">\n<li>d'un espace</li>\n<li>d'une structure élevée c.à.d. barrière, rempart, muraille</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕψωμα, ατος (τὸ)</b> position élevée, PHIL. <i>2, 408 ; au plur</i>. PHOCYL. <i>68 ;</i> SIB. <i>8, 234 ; particul. en parl. de l’ascension d’un astre,</i> SEXT. <i>M. 5, 33 ;</i> ὕ. μέγιστον, PLUT. <i>M. 149</i> a, <i>782</i> d, point culminant.<br><span><b>Étym</b>. ὑψόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υψωμα - ὕψωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5314":"<h1>phagos</h1>\n<p>Strong n° 5314 <i>Prononciation [fag'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un homme vorace, un gourmand, un glouton</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>φάγος, ου (ὁ)</b> <span>[ᾰ]</span> grand mangeur, glouton, NT. <i>Matth. 11, 19 ; Luc. 7, 34</i>.<br><span><b>Étym</b>. φαγεῖν.</span><br><br>\n➁ <b>φαγός</b>, <i>v</i>. φηγός.<br>\n<b>φηγός, οῦ (ἡ) :<br>      1</b> chêne à glands comestibles (<i>quercus esculus</i> L.) IL. <i>5, 693 ; 7, 60 ;</i> HÉS. <i>fr. 18 ; fr. 39, 7 Gaisford ;</i> TH. <i>H.P. 3, 8, 2 ;</i> ἡ παλαιὰ φ. SOPH. <i>Tr. 171,</i> le chêne antique, <i>en parl. du chêne de Dodone ;</i><br><b>      2</b> gland, <i>fruit de cet arbre,</i> PLAT. <i>Rsp. 372</i> c ; <i>p. anal</i>. gland, AR. <i>Pax 1137</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>eh₂ǵ-, hêtre ; <i>cf. lat</i>. fāgus ; <i>glissement sémantique du fait que le hêtre ne pousse pas en Grèce</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαγος - φάγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5315":"<h1>phago</h1>\n<p>Strong n° 5315 <i>Prononciation [fag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manger</li>\n<li>consommer une chose\n<ol type=\"a\">\n<li>prendre de la nourriture, préparer un repas</li>\n<li>métaph. dévorer, avaler</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φάγομαι</b> (<i>prés. et fut</i>.) manger, <i>au prés</i>. SPT. <i>Sir. 36, 23 ; au fut</i>. SPT. <i>Ruth 2, 14 ;</i> NT. <i>Luc. 14, 15 ; 2 sg</i>. φάγεσαι, NT. <i>Luc. 17, 8</i>.<br><span><b>Étym</b>. <i>formé d’après</i> φαγεῖν.</span><br><br>\nVoir aussi .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαγω - φάγω</font>\n<br><br>un verbe primaire (utilisé en variante de  à certains temps)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n96 fois dans 89 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (18)</li>\n<li>Luc (21)</li>\n<li>Jean (15)</li>\n<li>Actes (6)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (10)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G5316":"<h1>phaino</h1>\n<p>Strong n° 5316 <i>Prononciation [fah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter à la lumière, faire briller, remplir de clarté</li>\n<li>briller\n<ol type=\"a\">\n<li>briller, être brillant ou resplendissant</li>\n<li>devenir évident, être amené à la lumière, porté à la vue, apparaître\n<ol>\n<li>de la végétation qui pousse, qui sort à la lumière</li>\n<li>apparaître, être vu</li>\n<li>exposé à la vue</li>\n</ol>\n</li>\n<li>rencontrer les yeux, frapper le regard, devenir clair ou manifeste</li>\n<li>apparaître à l'esprit, sembler à son jugement ou à son opinion</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φαίνω</b> <span>(<i>f</i>. φανῶ <span>[ᾰ]</span> <i>ao</i>. ἔφηνα, <i>pf</i>. πέφαγκα, <i>pf.2 intr</i>. πέφηνα ; <i>pass. f</i>. φανήσομαι, <i>ao.1</i> ἐφάνθην, <i>ao.2</i> ἐφάνην, <i>pf</i>. πέφασμαι, ασαι, ανται <i>ou</i> αται, <i>etc</i>.)</span><br><b>A <i>tr</i>.<br>   I</b> faire briller : φῶς, SOPH. <i>Ph. 297,</i> une lumière ; ἡμέραν, PLAT. <i>Epin. 978</i> d, le jour ; <i>abs</i>. δμῳὰς αἵ κεν ἔφαινον, OD. <i>19, 25,</i> des servantes qui auraient éclairé (<i>litt</i>. fait briller de la lumière) ;<br><b>   II</b> faire paraître, faire voir, rendre visible : σήματα, IL. <i>2, 353,</i> des signes de la volonté céleste ; τέρας τινί, IL. <i>2, 324 ;</i> OD. <i>3, 173,</i> faire voir un présage à qqn ; μηρούς, OD. <i>18, 67,</i> laisser voir ses cuisses ; ἐς τὸ φῶς τι, SOPH. <i>O.R. 1229,</i> produire qqe ch. à la lumière du jour ; τινὶ παράκοιτιν, OD. <i>15, 26,</i> faire voir, <i>càd</i>. donner une épouse à qqn <i>ou</i> la lui montrer dans l’avenir ; <i>au pass</i>. ἐφάνη μέγα σῆμα, IL. <i>2, 308,</i> un grand signe de la volonté céleste se manifesta ; <i>cf</i>. OD. <i>21, 413 ; p. anal. en parl. du son :</i> φ. ἀοιδήν, OD. <i>8, 499,</i> faire entendre un chant ; γήρυμα στρατῷ, ESCHL. <i>Eum. 569,</i> faire entendre un ordre au peuple, <i>en parl. de la trompette ; cf</i>. THCR. <i>Idyl. 9, 28 ;</i> A. RH. <i>4, 784, etc. ; au pass</i>. φανεῖσα φάμα, SOPH. <i>O.R. 474,</i> bruit qui s’est répandu ; <i>p. ext. en parl. de choses abstraites :</i> φ. νοήματα, IL. <i>18, 295,</i> mettre au jour des sentiments, des pensées ; ἀρετήν, OD. <i>8, 237,</i> montrer son habileté, ce qu’on est capable de faire ; βίην, HÉS. <i>Th. 650 ;</i> A. RH. <i>2, 23,</i> montrer sa force ; ὀργάς, ESCHL. <i>Ch. 326,</i> manifester sa colère ; εὔνοιαν, HDT. <i>3, 36,</i> montrer de la bienveillance ;<br><b>   III</b> faire connaître, indiquer : ὁδόν τινι, OD. <i>12, 334,</i> à qqn son chemin ; <i>particul</i>. faire connaître par la parole, <i>càd. :</i><br><b>      1</b> révéler : γένος, SOPH. <i>O.R. 1059,</i> sa naissance ;<br><b>      2</b> annoncer, présager : μαντεῖα, PLUT. <i>Agis 9,</i> des oracles ; ἐπιϐουλήν τινά, XÉN. <i>Hell. 3, 3, 4,</i> qqe conjuration ;<br><b>      3</b> dénoncer : τινα, SOPH. <i>Ant. 325 ;</i> XÉN. <i>Cyr. 1, 2, 14 ;</i> PLAT. <i>Leg. 745</i> a, qqn ; τινὰ τοῖς πρυτάνεσι, AR. <i>Eq. 300,</i> qqn aux prytanes ; πλοῖον, DÉM. <i>1324, 19,</i> un bâtiment (comme étant en contravention) ; <i>au pass</i>. τὰ φανθέντα, DÉM. <i>1325, 29,</i> les biens dénoncés pour être saisis <i>ou</i> confisqués ;<br><b>      4</b> expliquer : λόγον, HDT. <i>1, 116, 118,</i> un discours, une parole ;<br><b>   IV</b> <i>t. milit. à Lacédémone :</i> φαίνειν φρουράν, XÉN. <i>Hell. 3, 2, 23 ; 3, 5, 6 ; 4, 2, 5 ; 6, 4, 17, etc. litt</i>. faire paraître une garnison, <i>càd</i>. la faire avancer, la faire sortir, envoyer une expédition (<i>cf. franç</i>. faire une démonstration) : ἐπί τινα, XÉN. <i>Hell. 4, 7, 1 ; 5, 1, 29,</i> contre qqn ; εἰς Ἄργος, XÉN. <i>Hell. 4, 7, 2,</i> à Argos ;<br><b>B <i>intr. :</i><br>      1</b> briller, <i>en parl. du soleil, des corps célestes,</i> PLAT. <i>Tim. 39</i> b ; AR. <i>Nub. 586 ;</i> THCR. <i>Idyl. 2, 11 ; abs</i>. ὁ φαίνων (<i>s.-e</i>. ἀστήρ) ARSTT. <i>Mund. 2, 9,</i> la planète brillante, <i>càd</i>. Saturne ; <i>en parl. du feu ou de la lumière, en gén</i>. TH. <i>Ign. § 11 ;</i><br><b>      2</b> porter une lumière, <i>en parl. de statues qui portent des torches,</i> OD. <i>7, 102 ; p. suite,</i> porter une lumière pour <i>ou</i> devant : τινί, OD. <i>19, 25,</i> devant qqn ;<br><b>      3</b> se montrer, paraître : γαῖα μέλαινα φάνεσκε, OD. <i>11, 587,</i> la terre noire paraissait, <i>en parl. du fond de l’eau ;</i> τίνες δόμων ὕπερ φαίνουσι ; EUR. <i>El. 1234,</i> quelles personnes se montrent au-dessus de la maison ? ;<br><b><i>Moy</i>. φαίνομαι</b> <span>(<i>f</i>. φανοῦμαι, <i>ao.1</i> ἐφηνάμην)</span><br><b>      1</b> briller, luire : δεινὼ δέ οἱ ὄσσε φάανθεν, IL. <i>1, 200,</i> ses yeux brillèrent d’un éclat terrible ; ὅτ' ἂν ἐκ πόντοιο σέλας ναύτῃσι φανήῃ πυρός, IL. <i>19, 375,</i> lorsque du sein de la mer brille aux yeux des matelots l’éclat d’un feu ; διὰ τοῦ ὀρόφου ἐφαίνετο πῦρ, XÉN. <i>An. 7, 4, 16,</i> le feu brillait à travers le toit ;<br><b>      2</b> paraître au jour, se montrer : οἴῳ φαινομένη, IL. <i>1, 198,</i> visible pour lui seul ; ἐφάνη λῖς εἰς ὁδόν, IL. <i>15, 275,</i> un lion se montre sur la route ; πόθεν φαίνει ; XÉN. <i>Mem. 2, 8, 4, etc</i>. d’où te montres-tu, <i>càd</i>. d’où viens-tu ? μνηστῆρσι φαίνεται, OD. <i>15, 517,</i> elle se montre aux prétendants ; Ἕκτωρ μετὰ πρώτοισι φάνεσκεν, IL. <i>11, 64,</i> Hector se montrait parmi les premiers ; <i>en parl. du soleil, des astres :</i> ἦμος φάνη ῥοδοδάκτυλος ἠώς, IL. <i>1, 477 ; 24, 13 ;</i> OD. <i>2, 1, etc</i>. lorsque parut l’aurore aux doigts de rose ; ἅμ' ἠοῖ φαινομένηφιν, IL. <i>9, 618 ;</i> OD. <i>4, 407 ; 6, 31,</i> au lever de l’aurore, à l’aube ; <i>p. anal. en parl. d’une vapeur qui sort des nuages,</i> IL. <i>5, 864 ;</i> d’un vent qui s’élève, OD. <i>4, 361 ;</i> τὰ φαινόμενα, POL. <i>9, 15, 7,</i> les constellations visibles ; <i>ou en gén</i>. les phénomènes célestes, <i>titre d’un poème d’Aratos ; particul</i>. paraître en se découvrant, devenir visible : φάνεν δέ οἱ εὐρέες ὦμοι, OD. <i>18, 68,</i> ses larges épaules apparurent ; <i>cf</i>. IL. <i>22, 324 ; avec un déterm</i>. se montrer comme, apparaître comme : φάνητε ἄριστοι, XÉN. <i>An. 3, 1, 24,</i> montrez-vous les plus capables ; εὖ ποιεῦντες φαίνεσθε, HDT. <i>9, 89,</i> montrez-vous serviables ; <i>avec un inf. :</i> ἥτις ἀρίστη φαίνεται εἶναι, OD. <i>15, 25,</i> celle qui se montre la meilleure ;<br><b>      3</b> être ostensible, manifeste, évident : ἐστὶν ἀληθῆ καὶ φαίνεται, DÉM. cela est vrai et manifeste ; ἀδύνατος ἂν φαινοίμην, XÉN. <i>Cyr. 3, 1, 34,</i> je serais évidemment hors d’état de faire la chose ; τῶν ἡλίκων διαφέρων ἐφαίνετο, XÉN. <i>Cyr. 1, 3, 1,</i> il se montrait visiblement supérieur à ceux de son âge ; ἐὰν φαίνωμαι ἀδικεῖν, XÉN. <i>An. 5, 7, 5,</i> si je parais avoir tort ;<br><b>      4</b> paraître (<i>p. opp. à</i> être) EUR. (AR. <i>Ach. 441</i>) ; XÉN. <i>Hell. 6, 5, 28 ;</i> PLAT. <i>Rsp. 596</i> e ; <i>p. opp. à</i> γίγνεσθαι, POL. <i>11, 29, 11 ;</i> εἰ βούλοιτο στρατηγὸς ἀγαθὸς μὴ ὢν φαίνεσθαι, XÉN. <i>Mem. 1, 7, 3,</i> si qqn voulait, n’étant pas bon général, le paraître ; <i>abs</i>. paraître qqe chose : οὐδαμοῦ φανῆναι, PLAT. <i>Gorg. 456</i> c, <i>etc. ;</i> DÉM. <i>328, 25, etc</i>. ne paraître nulle part quelque chose, <i>càd</i>. être regardé comme rien ; <i>d’où</i> paraître, sembler, <i>abs. :</i> πῶς ὔμμιν ἀνὴρ ὅδε φαίνεται εἶναι ; OD. <i>11, 336,</i> comment cet homme vous paraît-il être ? οὗ ἀρίστη φαίνετο βουλή, IL. <i>9, 94,</i> dont l’avis lui paraissait le meilleur : οὕτως ἔμοιγε καὶ αὐτῷ φαίνεται, PLAT. <i>Rsp. 383</i> a, c’est ainsi qu’il me semble aussi ; τὸ φαινόμενον εἰπεῖν, PLUT. <i>M. 158</i> c, dire ce que l’on pense ; ὥς γ' ἐμοὶ φαίνεται, PLAT. <i>Prot. 324</i> d, à ce qu’il me semble ; <i>intercalé dans la phrase :</i> φαίνεται, ANTH. <i>11, 331,</i> ce semble ; <i>dans une réponse :</i> φαίνεται, PLAT. <i>Rsp. 333</i> d, <i>etc</i>. cela semble ainsi, oui en effet ; τὰ φαινόμενα, PLAT. <i>Rsp. 517</i> b, la manière de voir ; <i>cf</i>. POL. <i>5, 51, 5 ; 9, 36, 6 ;</i> φαίνεταί μοι <i>avec l’inf</i>. DH. <i>2, 14, etc</i>. il me semble bon de, <i>etc. ; joint à</i> δοκεῖν : εἰ δὴ κακός τε φαίνομαι δοκῶ τέ σοι, EUR. <i>Hipp. 1071,</i> si les apparences m’accusent et si tu le crois ; δοκοῖμεν ἂν τῶν πατέρων χείρους φαίνεσθαι, THC. <i>1, 122,</i> nous paraîtrions nous montrer inférieurs à nos pères ; <i>cf</i>. XÉN. <i>Mem. 2, 1, 22 ;</i> PLAT. <i>Eryx. 399</i> c, <i>Phædr. 269</i> d, <i>etc. ;</i><br><b>      5</b> <i>à l’ao. moy</i>. φήνασθαι, montrer comme sien, comme chose que l’on possède : τινί τι, SOPH. <i>Ph. 944,</i> qqe ch. à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. épq</i>. φαινέμεν, OD. <i>8, 237 ;</i> PD. <i>P. 4, 171 ; part. fém. dor</i>. φαίνοισα, PD. <i>N. 5, 17. Fut. réc</i>. φανήσω, ARCHIM. <i>Aren. p. 331. Ao. dor</i>. ἔφανα <span>[φᾱ]</span> PD. <i>I. 4, 2. Ao. itér. 3 sg</i>. φάνεσκε, OD. <i>11, 587 ; 12, 241, 242. Pf</i>. πέφαγκα, Ps.-CALLISTH. <i>2, 10 dout. Pass. impf. itér. 3 sg</i>. φαινέσκετο, OD. <i>13, 194 ; ao. épq</i>. ἐφαάνθην <i>ou</i> φαάνθην, IL. <i>17, 650 ; 3 pl</i>. φάανθεν, IL. <i>1, 200 ; 17, 650. Ao.2, 3 pl. épq</i>. φάνεν, OD. <i>18, 68 ;</i> PD. <i>O. 10, 85 ; impér</i>. φάνηθι, IL. <i>18, 198 ; sbj. 3 sg. épq</i>. φανήῃ, IL. <i>19, 375, ou</i> φανείῃ, HÉS. <i>O. 680 ; inf. épq</i>. φανήμεναι, IL. <i>9, 240. Pf. 3 sg</i>. πέφανται, IL. <i>2, 122 ; 16, 207 ;</i> PD. <i>N. 6, 14. Fut. antér. 3 sg</i>. πεφήσεται, IL. <i>17, 155. Dans les inscr. att. seul. ao</i>. ἐφάνθην, CIA. <i>2, add. 203 b, 6 (envir. 300 av. J.C.) ; v. Meisterh. p. 150, 6</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>eh₂-, briller, <i>d’où</i> φαν-, <i>cf. sscr</i>. bhā́ti.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαινω - φαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> – se réfère au jugement subjectif, qui peut ou non être conforme aux faits\n<br><br> – se réfère à l'apparence extérieure actuelle, généralement correcte, qui peut être décevante\n<br><br>Comparer : ,  (),  (), \n<br><br> et  implique de juger et de croire en ne s'appuyant pas sur sa sensibilité ou ses sentiments, mais sur une bonne considération des éléments extérieurs, l'estimation et la comparaison des faits.\n<br><br> et  à l'inverse, décrivent un jugement subjectif variant selon l'orientation ou le déroulement des faits dans leur relation entre eux.\n<br><br> dénote un jugement plus attentif et plus délibéré que ;\n<br><br> est un jugement subjectif qui a le sentiment plus que la pensée () comme base.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 31 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G5317":"<h1>Phalek</h1>\n<p>Strong n° 5317 <i>Prononciation [fal'-ek]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Phalek (Peleg) = « division »\n<ol><li>le fils d'Eber</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φαλεκ</font> &lt; פלג - <font face=\"Georgia\">Φάλεκ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5318":"<h1>phaneros</h1>\n<p>Strong n° 5318 <i>Prononciation [fan-er-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apparent, manifeste, évident, connu</li>\n<li>manifesté c.à.d. être clairement reconnu ou connu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φανερός, ά, όν</b> <span>[ᾰ]</span><br><b>      1</b> visible, apparent, qu’on peut voir <i>ou</i> qui se montre : φανεροὶ θεοί, HDT. <i>2, 146,</i> dieux qui se montrent aux hommes, qui vivent avec les hommes, dieux visibles ; φανερὸς ὄμμασιν, EUR. <i>Bacch. 501,</i> que l’on voit de ses yeux ; φανερὸς ἦν, XÉN. <i>Mem. 1, 1, 10,</i> il était visible à tous ; τὴν ψῆφον φανερὰν φέρειν, PLAT. <i>Leg. 767</i> d, <i>ou</i> τιθέναι, PLAT. <i>Leg. 855</i> d, apporter <i>ou</i> déposer un vote apparent (<i>cf. franç</i>. voter à bulletin ouvert) ; φανερὰ οὐσία, AND. <i>15, 38 ;</i> IS. <i>59, 18 ;</i> DÉM. <i>59, 9 ; 986, 25, etc</i>. fortune visible, biens au soleil, immeubles ; φανερὰ ἔχθρα, THC. <i>1, 42,</i> inimitié ouverte, déclarée, <i>p. opp. à</i> inimitié future (μέλλουσα) ; <i>fig</i>. clair, évident, manifeste, ATT. ; <i>avec un part. :</i> ἐπισπεύδων φανερὸς ἦν, HDT. <i>7, 18,</i> il se mettait ouvertement à presser l’expédition ; φανερὸς ἦν ἐπιθυμῶν εἰπεῖν, PLAT. <i>Rsp. 388</i> a, il était visible qu’il désirait parler ; <i>ou avec</i> ὅτι : φανεροὶ γιγνόμενοι ὅτι ποιοῦσιν, XÉN. <i>Cyr. 2, 2, 12,</i> il est évident qu’ils font ; <i>avec</i> ὅπως : ὅσα μὴ φανερὰ ἦν ὅπως ἐγίγνωσκεν, XÉN. <i>Mem. 1, 1, 17,</i> toutes les choses au sujet desquelles on ne savait pas clairement son opinion ; <i>de même au neutre :</i> φανερόν ἐστιν ὅτι, XÉN. <i>Mem. 3, 9, 2,</i> il est évident que, <i>etc. ;</i> εἰ φανερὸν γένοιτο ὅτι, PLAT. <i>Phædr. 70</i> d, s’il devenait évident que, <i>etc. ;</i> φανερὸν δέ <i>suivi d’une propos. avec</i> γάρ, ATT. il est évident que, <i>litt</i>. cela est évident, car, <i>etc. ; locut. adv</i>. ἀπὸ τοῦ φανεροῦ, DH. <i>4,4,</i> sous les yeux de tous ; ὑπ' οὐδενὸς φανεροῦ, PLUT. <i>M. 129</i> b, sans cause évidente ; ἐκ τοῦ φανεροῦ, THC. <i>4, 79 ;</i> XÉN. <i>Hell. 6, 5, 16, etc</i>. ouvertement ; <i>ou</i> en rase campagne, PLUT. <i>M. 238</i> c ; <i>ou</i> de la partie visible de l’espace, <i>càd</i>. à portée de la vue, XÉN. <i>Mem. 3, 11, 8 ;</i> ἐν φανερῷ, THC. <i>4, 73 ;</i> ἐν τῷ φανερῷ, XÉN. <i>Mem. 1, 1, 10 ; Cyr. 7, 5, 55 ; An. 1, 3, 21 ;</i> PLAT. <i>Leg. 745</i> a, <i>etc</i>. au grand jour, en public, publiquement ; ἐς τὸ φανερόν, au grand jour, sous les yeux de tous, <i>avec un verbe de mouv</i>. THC. <i>1, 6 ; 3, 27, etc. ; sans mouv</i>. THC. <i>1, 23, etc. ; ou</i> en plein air, <i>avec un verbe de mouv</i>. XÉN. <i>Hell. 3, 3, 2 ; Lac. 5, 2, etc. ;</i><br><b>      2</b> qui est en vue : εἰς τὸ φανερὸν καταστῆσαί τινα, XÉN. <i>An. 7, 7, 22,</i> placer qqn à un rang où l’on est en vue ; <i>fig</i>. distingué, important, <i>en parl. de pers</i>. THC. <i>4, 11 ; en parl. de choses</i> (ville, XÉN. <i>Cyr. 7, 5, 58 ;</i> chose, THC. <i>1, 17, etc</i>.).<br><span>•<i> Cp</i>. φανερώτερος, ATT. ; <i>sup</i>. φανερώτατος, THC. <i>4, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ός, EUR. <i>Bacch. 991, 1011</i>.<br><span><b>Étym</b>. φαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φανερος - φανερός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 16 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5319":"<h1>phaneroo</h1>\n<p>Strong n° 5319 <i>Prononciation [fan-er-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre manifeste ou visible ou connu ce qui a été caché, manifester, que ce soit par des mots ou des faits ou toute autre manière\n<ol type=\"a\">\n<li>rendre actuel et visible, réalisé</li>\n<li>faire savoir par l'enseignement</li>\n<li>devenir manifeste, être rendu connu</li>\n<li>d'une personne\n<ol>\n<li>exposer à la vue, se montrer, apparaître</li>\n</ol>\n</li>\n<li>devenir connu, être pleinement reconnu, entièrement compris\n<ol>\n<li>qui et quoi est quelqu'un</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φανερόω-ῶ</b> <span>(<i>ao. pass</i>. ἐφανερώθην)</span> <span>[ᾰ]</span><br><b>      1</b> rendre clair, évident, manifeste, montrer clairement, DC. <i>59, 18 ; 77, 15 ;</i> JOS. <i>A.J. 20, 4, 1 ;</i> NT. <i>Joh. 7, 4 ; au pass</i>. NT. <i>2Cor. 5, 10 ;</i><br><b>      2</b> faire connaître, rendre notoire <i>ou</i> célèbre, DH. <i>10, 37 ; au pass</i>. HDT. <i>6, 122</i>.<br><span><b>Étym</b>. φανερός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φανεροω - φανερόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> est sensé décrire une manifestation externe, dont le sens par là même est ouvert à tous, en particulier ou isolé ;\n<br><br> est une révélation interne, et durable, à la pensée du croyant. Le  ou « dévoilement » précède et produit le  ou « manifestation » ; le premier s'attache à l'objet révélé, le second à la personne à qui la révélation est faite.\n<br><br>Comparer : , \n<br><br> – évident, ce qui est connu et compris\n<br><br> – manifeste, en opposition à ce qui est caché et invisible\n<br><br> désigne plutôt une perception intérieure,  s'appuie sur l'apparence externe.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n50 fois dans 43 versets de 14 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Jean (9)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (9)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (4)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (3)</li>\n<li>1 Pierre (2)</li>\n<li>1 Jean (9)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5320":"<h1>phaneros</h1>\n<p>Strong n° 5320 <i>Prononciation [fan-er-oce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manifestement, visiblement\n<ol type=\"a\">\n<li>pleinement, clairement</li>\n<li>ouvertement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φανερῶς</b> <span>[ᾰ]</span> <i>adv. :</i><br><b>      1</b> visiblement, ouvertement, THC. <i>1, 87 ; 6, 91 ;</i> AR. <i>Nub. 291 ; p. opp. à</i> λάθρα, PLAT. <i>Conv. 182</i> d ;<br><b>      2</b> <i>p. suite,</i> sous les yeux de tous, publiquement, HDT. <i>9, 71 ;</i> XÉN. <i>An. 1, 9, 19 ;</i> PLAT. <i>Hipp. ma. 304</i> d ; ESCHL. <i>Pr. 1090 ;</i> SOPH. <i>El. 833 ;</i> PLAT. <i>Tim. 41</i> a ; PLUT. <i>M. 331</i> b.<br><span>•<i> Cp</i>. φανερωτέρως, ARSTT. <i>P.A. 2, 10 ;</i> φανερώτερον, THC. <i>6, 91 ;</i> <i>• Sup</i>. φανερώτατα, ORIG.<br><span><b>Étym</b>. φανερός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φανερως - φανερῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5321":"<h1>phanerosis</h1>\n<p>Strong n° 5321 <i>Prononciation [fan-er'-o-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une manifestation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φανέρωσις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> action de rendre visible, <i>d’où</i> déclaration, CHRYS. ;<br><b>      2</b> action de devenir visible, manifestation, ARSTT. <i>Plant. 2, 1, 2, etc</i>.<br><span><b>Étym</b>. φανερόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φανερωσις - φανέρωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5322":"<h1>phanos</h1>\n<p>Strong n° 5322 <i>Prononciation [fan-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une torche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>φανός, ή, όν</b> <span>[ᾱ]</span> clair, <i>d’où :</i><br><b>      1</b> lumineux, brillant, XÉN. <i>Cyn. 10, 7 ;</i> PLAT. <i>Phil. 16</i> c ; <i>joint à</i> καλός, PLAT. <i>Rsp. 506</i> d ; τὸ φανόν, XÉN. <i>Cyn. 5, 18 ;</i> PLAT. <i>Rsp. 518</i> c, la clarté, l’éclat ; <i>particul</i>. brillant de propreté, propre, AR. <i>Ach. 845, Eccl. 347 ; fig</i>. radieux, joyeux, ESCHL. <i>Pr. 540 ;</i> PLAT. <i>Phædr. 256</i> d, <i>Rsp. 518</i> a ;<br><b>      2</b> qui est en vue, célèbre, <i>joint à</i> ἐλλόγιμος, PLAT. <i>Conv. 197</i> a ;<br><b>      3</b> <i>fig</i>. manifeste, évident, ARR.<br><span>•<i> Cp</i>. φανότερος, PLAT. <i>Rsp. 518</i> a ; PHILSTR. <i>827 ;</i> <i>• Sup</i>. φανότατος, XÉN. <i>Cyn. 10, 7 ;</i> PLAT. <i>Phil. 16</i> c ; PLUT. <i>M. 167</i> b.<br><span><b>Étym</b>. φαίνω.</span></span><br><br>\n➁ <b>φανός, οῦ (ὁ)</b> <span>[ᾱ]</span> lumière, <i>particul. :</i><br><b>      1</b> flambeau <i>ou</i> torche de sarments de vigne, AR. <i>Lys. 308 ;</i> COM. (ATH. <i>700</i> b) ; ANTH. <i>12, 116 ;</i> ὑπὸ φανοῦ, XÉN. <i>Lac. 5, 7,</i> à la lumière des flambeaux ;<br><b>      2</b> lanterne, ATH. <i>700</i> b ;<br><b>      3</b> lampe, MÉN. <i>4, 87 Meineke ;</i> ATH. <i>700</i> b.<br><span><b>Étym</b>. <i>c</i>. φανός¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φανος - φανός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5323":"<h1>Phanouel</h1>\n<p>Strong n° 5323 <i>Prononciation [fan-oo-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Phanuel = « la face de Dieu »\n<ol><li>le père de Anne, la prophétesse de la tribu d'Aser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φανουηλ</font> &lt; פנואל - <font face=\"Georgia\">Φανουήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5324":"<h1>phantazo</h1>\n<p>Strong n° 5324 <i>Prononciation [fan-tad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire apparaître, rendre visible, exposer à la vue, montrer\n<ol type=\"a\">\n<li>l'apparence, le spectacle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φαντάζω</b> <span>(<i>seul. prés. ; pass. f</i>. φαντασθήσομαι, <i>ao</i>. ἐφαντάσθην, <i>pf. inus</i>.)</span><br><b>      1</b> faire voir en apparence, donner l’illusion de, <i>acc</i>. CALLISTR. <i>Stat. 13 ;</i><br><b>      2</b> dénoncer, <i>au pass</i>. être dénoncé : ὑπό τινος, AR. <i>Ach. 823,</i> par qqn ;<br><b><i>Moy.</i></b> (<i>seul. prés. et ao. au sens moy</i>.) ;<br><b>   I <i>intr. :</i><br>      1</b> se montrer, apparaître, EUR. <i>Andr. 876, Ph. 93 ; d’ord. en parl. de formes changeantes et fugitives, de visions ou de phénomènes extraordinaires (météores, comètes, etc</i>.) HDT. <i>4, 124 ; 7, 15 ;</i> PLAT. <i>Conv. 211</i> a, <i>Phil. 51</i> a ; φ. ἄλλοτε ἐν ἄλλαις ἰδέαις, PLAT. <i>Rsp. 380</i> d, se montrer tantôt sous une forme, tantôt sous une autre ; δεξιὰ φαντάζεται τὰ ἀριστερά, PLAT. <i>Hipp. ma. 300</i> c, ce qui est à gauche paraît être à droite ; <i>cf</i>. PLAT. <i>Phil. 51</i> a ; ARSTT. <i>An. 3, 10, 7 ;</i><br><b>      2</b> faire de l’étalage, se glorifier, HDT. <i>7, 10, 5 ;</i><br><b>      3</b> se montrer sous les traits de : γυναικί, ESCHL. <i>Ag. 1500,</i> d’une femme ;<br><b>   II <i>tr. :</i><br>      1</b> se figurer, s’imaginer, LGN <i>15, 2 et 8 ; avec l’inf</i>. GAL. <i>ad Glauc. 11, 67 ;</i> POLÉM. <i>Physiogn. 1, 15 ;</i><br><b>      2</b> reproduire les traits de, jouer le rôle de : τινα, LIB. <i>4, 512,</i> de qqn.<br><span><b>Étym</b>. φαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φανταζω - φαντάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5325":"<h1>phantasia</h1>\n<p>Strong n° 5325 <i>Prononciation [fan-tas-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parade, grande apparence, étalage, (en grande) pompe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φαντασία, ας (ἡ)</b> <span>[τᾰ]</span><br><b>   I</b> action de se montrer, apparition, APP. <i>Civ. 4, 102 ; particul</i>. apparition de choses extraordinaires <i>ou</i> qui font illusion, vision, PLUT. <i>M. 15</i> b ; SEXT. <i>M. 9, 44 ;</i><br><b>   II</b> spectacle, coup d’œil, aspect, <i>particul</i>. de choses extraordinaires et propres à frapper l’imagination, POL. <i>3, 53, 8 ; 5, 48, 9 ; 14, 2, 4 ; 16, 8, 3 ; 17, 10, 7 ; 23, 9, 12 ; 30, 17, 4 ; p. suite,</i> étalage, montre, ostentation, POSIDON. (ATH. <i>212</i> c) ; μετὰ φαντασίας, POL. <i>15, 25, 5 ; 16, 21, 1 ;</i> NT. <i>Ap. 25, 23,</i> avec ostentation ; φαντασίας ἕνεκα, DS. <i>12, 83,</i> par ostentation ;<br><b>   III</b> action de se figurer par l’imagination, <i>d’où :</i><br><b>      1</b> image qui s’offre à l’esprit, idée, PLAT. <i>Theæt. 152</i> c ; ARSTT. <i>Rhet. 1, 11, 6 ; au plur</i>. PLAT. <i>Theæt. 161</i> e ; ARSTT. <i>Metaph. 1, 1, 3, etc. ; particul. chez les Stoïciens,</i> CHRYSIPP. (PLUT. <i>M. 1046</i> f, <i>1055</i> f, <i>etc</i>.) ; SEXT. <i>P. 1, 52 ;</i><br><b>      2</b> faculté de se représenter par l’esprit, imagination, LUC. <i>V. auct. 21 ;</i> SEXT. <i>P. 3, 241 ; particul. chez les Stoïciens,</i> SEXT. <i>M. 8, 123 ;</i><br><b>   IV</b> apparence, dehors, extérieur, HDN <i>4, 3, 4</i>.<br><span><b>Étym</b>. φαντάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαντασια - φαντασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5326":"<h1>phantasma</h1>\n<p>Strong n° 5326 <i>Prononciation [fan'-tas-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une apparence</li>\n<li>une apparition, un spectre</li>\n<li>fantasme, fantôme</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φάντασμα, ατος (τὸ) :<br>      1</b> apparition, vision, songe, PLAT. <i>Rsp. 510</i> a ; THCR. <i>Idyl. 21, 30 ;</i><br><b>      2</b> image offerte à l’esprit par un objet, PLAT. <i>Phæd. 81</i> d, <i>Theæt. 167</i> b ; ARSTT. <i>An. 3, 3, 9, etc. ; d’où</i> image sans consistance, apparence, PLAT. <i>Parm. 166</i> a, <i>Rsp. 598</i> b, <i>etc. ;</i><br><b>      3</b> spectre, fantôme, ESCHL. <i>Sept. 710, fr. 298 ;</i> EUR. <i>Hec. 54, 95, 390 ;</i> PLAT. <i>Phæd. 81</i> d, <i>Tim. 71</i> a ;<br><b>      4</b> phénomène dans le ciel, ARSTT. <i>Mund. 4, 21 ;</i> chose extraordinaire, prodige, DH. <i>4, 62 ;</i> PLUT. <i>Dio. 2</i>.<br><span><b>Étym</b>. φαντάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαντασμα - φάντασμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G5327":"<h1>pharagx</h1>\n<p>Strong n° 5327 <i>Prononciation [far'-anx]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une vallée entourée de falaises et de précipices</li>\n<li>un ravin, gorge</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φάραγξ, αγγος (ἡ)</b> <span>[φᾰ]</span><br><b>   I</b> escarpement abrupt, roche taillée à pic, <i>d’où :</i><br><b>      1</b> ravin, précipice, ALCM. <i>60 ;</i> ESCHL. <i>Pr. 15, 142, 618, 1017 ;</i> EUR. <i>I.T. 277 ;</i> XÉN. <i>Hell. 7, 2, 13, etc. ;</i><br><b>      2</b> <i>particul</i>. rive escarpée, falaise, PLUT. <i>Ant. 7 ;</i><br><b>   II</b> <i>en gén</i>. précipice, gouffre, abîme, THC. <i>2, 67, etc. ;</i> XÉN. <i>Cyn. 5, 16 ;</i> DÉM. <i>793, 6 ; fig</i>. AR. <i>Eq. 248</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαραγξ - φάραγξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5328":"<h1>Pharao</h1>\n<p>Strong n° 5328 <i>Prononciation [far-ah-o']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pharaon (Angl. Pharaoh) = « sa nudité »\n<ol><li>était le titre commun des rois d'Egypte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φαραώ (ὁ)</b> Pharaon, <i>titre des rois d’Égypte,</i> ANTH. <i>1, 59</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φαραω - Φαραώ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5329":"<h1>Phares</h1>\n<p>Strong n° 5329 <i>Prononciation [far-es']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pharès (Pharez) = « une brèche »\n<ol><li>le fils de Juda et Thamar, sa belle-fille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φαρες</font> &lt; פרץ - <font face=\"Georgia\">Φαρές</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5330":"<h1>Pharisaios</h1>\n<p>Strong n° 5330 <i>Prononciation [far-is-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pharisien = « séparé »\n<ol><li>Un des trois partis Juifs, avec les Sadducéens, et les Esséniens. Leur secte apparut semble-t-il par réaction contre l'inclination de certains Juifs pour les coutumes grecques. Ils ont réussi à dominer la vie religieuse des Juifs, défendant la doctrine de la prédestination, croyant à l'immortalité de l'âme, aux récompenses et sanctions de l'au-delà. La religion était ramenée à l'observation de la loi, la conformation aux ordonnances. La piété devint formaliste, l'acte extérieur étant plus important que la disposition de cœur. Jésus déclara que les interprétations rabbiniques traditionnelles n'avaient rien d'obligatoire (<a class=\"ref\" data-r=\"MAT15.2-6\">Matthieu 15.2-6</a>). Les Pharisiens du début se distinguaient par leur droiture et leur courage, puis le niveau moral et intellectuel de leurs successeurs baissa, et Jean-Baptiste les traita de « race de vipères », bien qu'il y eut des hommes sincères (Nicodème, Paul, Gamaliel...)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φαρισαῖος, ου</b> <span>[ᾰῐ]</span> <i>adj. m.</i> pharisien, NT. <i>Matth. 3, 7, etc. ;</i> NONN. <i>Jo. 12, 10</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φαρισαιος</font> &lt; פרושים - <font face=\"Georgia\">Φαρισαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n99 fois dans 94 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (30)</li>\n<li>Marc (12)</li>\n<li>Luc (27)</li>\n<li>Jean (20)</li>\n<li>Actes (9)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5331":"<h1>pharmakeia</h1>\n<p>Strong n° 5331 <i>Prononciation [far-mak-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'usage ou l'administration de drogues, philtre</li>\n<li>empoisonnement</li>\n<li>sorcellerie, arts magiques, souvent trouvés en liaison avec l'idolâtrie et nourrie par celle-ci, sortilèges, enchantements</li>\n<li>métaph. les déceptions et séductions de l'idolâtrie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>φαρμακεία, ας (ἡ)</b> <span>[μᾰ]</span><br><b>      1</b> emploi de médicaments, <i>d’où</i> médicaments, XÉN. <i>Mem. 4, 2, 17 ;</i> PLAT. <i>Leg. 933</i> b ; <i>au plur</i>. PLAT. <i>Prot. 354</i> a, <i>Tim. 89</i> b ; <i>particul</i>. purgatif, HPC. <i>Aph. 1244, 1245 ;</i> ARSTT. <i>Probl. 33, 5 ; en gén</i>. remède, ARSTT. <i>Pol. 8, 3, 4 ;</i><br><b>      2</b> emploi de poisons, empoisonnement (du corps humain, d’une source, <i>etc</i>.) DÉM. <i>1025, 11 ;</i> POL. <i>6, 13, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. φαρμακείη, HPC. <i>ll. cc</i>.<br><span><b>Étym</b>. φαρμακεύω.</span></span><br><br>\n➁ <b>φαρμάκεια, ας (ἡ)</b> <span>[μᾰ]</span> <i>c</i>. φαρμακίς, ARSTT. <i>H.A. 9, 17, 1 ;</i> EL. <i>N.A. 14, 25</i>.<br><br>\n<b>φαρμακίς, ίδος</b> <span>[μᾰ]</span> <i>adj. f. :</i><br><b>      1</b> qui manie du poison, <i>d’où subst</i>. magicienne, sorcière, AR. <i>Nub. 749 ;</i> DÉM. <i>793, 27 ;</i> ARSTT. <i>H.A. 6, 22, 8 ;</i> LUC. <i>D. deor. 20, 10 ; Bis acc. 21 ; D. mer. 1, 2 ; 4, 4, etc. ;</i><br><b>      2</b> venimeuse, NIC. <i>Al. 551</i>.<br><span><b>Étym</b>. φάρμακον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαρμακεια - φαρμακεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Galates (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5332":"<h1>pharmakeus</h1>\n<p>Strong n° 5332 <i>Prononciation [far-mak-yoos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>quelqu'un qui prépare ou utilise des remèdes magiques, empoisonneur</li>\n<li>un sorcier, enchanteur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φαρμακεύς, έως (ὁ)</b> <span>[μᾰ]</span><br><b>   I</b> celui qui prépare <i>ou</i> administre des médicaments, ARÉT. <i>Cur. m. diut. 2, 12 ;</i><br><b>   II</b> celui qui compose des préparations magiques, <i>d’où :</i><br><b>      1</b> empoisonneur, SOPH. <i>Tr. 1140 ;</i><br><b>      2</b> magicien, sorcier, PLAT. <i>Conv. 203</i> d ; PLUT. <i>Artax. 19 ;</i> LUC. <i>D. deor. 13, 1 ; M. cond. 40 ; Cal. 13, etc. ; p. opp. à</i> ἰατρός, THÉM. <i>72</i> b.<br><span><b>Étym</b>. φάρμακον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαρμακευς - φαρμακεύς</font>\n<br><br>vient de pharmakon (une drogue, une potion)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5333":"<h1>pharmakos</h1>\n<p>Strong n° 5333 <i>Prononciation [far-mak-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>appartenant aux arts de la magie, empoisonneur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φαρμακός, οῦ (ὁ)</b> <span>[μᾰ]</span><br><b>      1</b> empoisonneur, magicien, sorcier, SPT. ;<br><b>      2</b> celui qui sert de remède <i>ou</i> de préservatif, <i>càd</i>. qu’on immole en expiation des fautes d’un autre, <i>particul</i>. des fautes d’une ville, HIPPON. <i>fr. 5 ;</i> AR. <i>Ran. 733 ;</i> LYS. <i>108, 5 ; p. suite,</i> scélérat, misérable (<i>cf</i>. κάθαρμα) AR. <i>Eq. 1405 ;</i> DÉM. <i>794, 4</i>.<br><span>•<i> Sup. irrég</i>. φαρμακίστατος, SUID. <i>v°</i> Μηδεία ; JOS. <i>A.J. 17, 4, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[μᾱ]</span> HIPPON. <i>l.c</i>.<br><span><b>Étym</b>. φάρμακον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαρμακος - φάρμακος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5334":"<h1>phasis</h1>\n<p>Strong n° 5334 <i>Prononciation [fas'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pour les orateurs Athéniens, l'exposé d'information contre ceux qui avaient détourné la propriété de l'état, ou violé les lois sur l'importation ou l'exportation de marchandises, ou volé les pupilles dont ils avaient la charge</li>\n<li>la révélation d'un crime secret</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>φάσις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> accusation, information judiciaire, AND. <i>12, 9 ; particul</i>. accusation, dénonciation, délation, ATT. DÉM. <i>793, 16 ; 941, 14, etc. ;</i><br><b>      2</b> apparition d’une étoile qui se lève, T. LOCR. <i>97</i> b ; ARSTT. <i>Meteor. 1, 6, 2 ;</i> NIC. <i>Th. 122 ;</i> MAN. <i>1, 4, etc</i>.<br><span><b>Étym</b>. φαίνω.</span><br><br>\n➁ <b>φάσις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> parole, ARSTT. <i>Interpr. 4, 1 ; 5, 3 ;</i><br><b>      2</b> déclaration, <i>en gén. comprenant</i> κατάφασις (affirmation) <i>et</i> ἀπόφασις (négation) ARSTT. <i>Interpr. 12, 10 ; Metaph. 3, 6, 10, etc. ; particul</i>. affirmation, <i>p. opp. à</i> ἀπόφασις, PLAT. <i>Soph. 263</i> e ; ARSTT. <i>An. pr. 1, 46, 5, etc. ; Metaph. 3, 4, 32, etc. ;</i><br><b>      3</b> bruit, rumeur, NT. <i>Ap. 21, 31 ;</i><br><b>      4</b> décision, RHÉT. <i>7, 2 W</i>.<br><span><b>Étym</b>. φημί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φασις - φάσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5335":"<h1>phasko</h1>\n<p>Strong n° 5335 <i>Prononciation [fas'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>affirmer, alléguer, présager ou professer, prétendre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φάσκω</b> (<i>act. seul. prés. et impf. ; pass. seul. impf</i>.) :<br><b>      1</b> dire, déclarer : τι, ESCHL. <i>Ch. 93 ;</i> EUR. <i>H.f. 1382, etc. ;</i> PLAT. <i>1 Alc. 111</i> c ; PLUT. <i>M. 228</i> f, qqe ch. ; ὅτι, PLUT. <i>M. 215</i> e, <i>ou</i> ὡς, MOSCH. <i>2, 12,</i> dire que, <i>etc. ; avec un inf</i>. HDT. <i>3, 58 ;</i> ATT. ; <i>particul. avec l’inf. fut</i>. promettre de, OD. <i>5, 135 ;</i> THC. <i>2, 85 ;</i> PLAT. <i>Ion 541</i> e ;<br><b>      2</b> dire oui, dire affirmativement, affirmer, PLAT. <i>Theæt. 190</i> a ; οὐ φάσκειν <i>avec un inf</i>. THC. <i>8, 52,</i> nier que, <i>etc. ;</i><br><b>      3</b> <i>p. ext</i>. être d’avis, penser, croire, <i>avec un inf. fut</i>. IL. <i>13, 100 ; ao</i>. OD. <i>22, 35 ; ou prés</i>. SOPH. <i>El. 9</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. φάσκων, <i>us. comme part. de</i> φημί, CIA. <i>1, 38, e, 6 (424/420 av. J.C.) ; v. Meisterh. p. 141, 16</i>.<br><span><b>Étym</b>. φημί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φασκω - φάσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5336":"<h1>phatne</h1>\n<p>Strong n° 5336 <i>Prononciation [fat'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une mangeoire, une crèche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φάτνη, ης (ἡ) :<br>   I</b> crèche, mangeoire, râtelier pour les chevaux, IL. <i>6, 506 ; 10, 568 ; 15, 263, 274 ; 24, 280 ;</i> HDT. <i>9, 70 ;</i> étable pour les bœufs, OD. <i>4, 535 ; 11, 411, etc. ;</i> PD. <i>O. 13, 131 ;</i> ATT. (XÉN. <i>Cyr. 3, 3, 27), etc. ; prov</i>. <span>βοῦς ἐπὶ φάτνῃ</span>, PHILSTR. <i>828,</i> bœuf à l’étable, <i>en parl. d’une pers. qui vit dans l’abondance ; cf</i>. EUR. <i>fr. 379, etc. ;</i> STR. <i>151 ;</i> LUC. <i>Tim. 14, Ind. 30 ;</i> ES. <i>228 Halm. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> <i>au pl</i>. lambris d’un plafond disposé par compartiments, DS. <i>1, 66 ;</i><br><b>      2</b> <i>au pl</i>. alvéoles des dents, râtelier, MÉD. ;<br><b>      3</b> nébuleuse dans la constellation du Cancer (<i>vraiss. Messier 44, l’amas de la Crèche</i>) TH. <i>Sign. 1, 23 ; 3, 6 ; 4, 2 ;</i> THCR. <i>Idyl. 22, 22 ;</i> ARAT. <i>892, 898, 996</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att</i>. φάτνη, <i>non</i> πάτνη, CIA. <i>2, 733, a, 2, 12 (envir. 306 av. J.C.) ; v. Meisterh. p. 80, 5</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φατνη - φάτνη</font>\n<br><br>vient de pateomai (manger)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (4)</li>\n</ul>\n</td></tr>\n</table>","G5337":"<h1>phaulos</h1>\n<p>Strong n° 5337 <i>Prononciation [fow'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>facile, léger, mince, ordinaire, un moyen indigne, sans valeur</li>\n<li>moralement : mauvais, bas, méchant, vil, mal</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φαῦλος, η, ον</b>, de qualité inférieure :<br><b>A</b> <i>avec idée de blâme :</i><br><b>   I</b> laid, AR. <i>Eccl. 617 ;</i><br><b>   II</b> méchant, malveillant, <i>en parl. de la divinité,</i> THGN. <i>163 ; en parl. de pers</i>. PLAT. <i>Prot. 326</i> e ; φ. περί τινα, EUR. <i>Epist. 1, 23,</i> méchant <i>ou</i> malveillant à l’égard de qqn ; <i>en parl. de choses</i> (parole, PLAT. <i>Soph. 152</i> d ; EUR. <i>Andr. 871 ;</i> opinion, DÉM. <i>764, 3 ;</i> affaire, AR. <i>Lys. 14, etc</i>.) ; τὸ φαῦλον, EUR. <i>I.T. 390,</i> le mal ; τὰ φαῦλα νικᾶν, SOPH. <i>fr. 30,</i> être vainqueur dans le mal, être un scélérat achevé ;<br><b>   III</b> défectueux : φ. αὐλητής, PLAT. <i>Prot. 327</i> c, mauvais joueur de flûte ; ἵππος, XÉN. <i>Mem. 4, 1, 3,</i> cheval défectueux ; <i>p. opp. à</i> σοφός, EUR. <i>Ph. 496 ;</i> PLAT. <i>Conv. 174</i> c ; <i>à</i> σπουδαῖος, PLAT. <i>Leg. 756</i> a, <i>etc. ; à</i> ξυνετός, THC. <i>3, 37 ;</i> τὸ πλῆθος τὸ φαυλότερον, EUR. <i>Bacch. 430,</i> la foule qui ne se préoccupe pas de penser autrement qu’on ne l’a fait avant elle ; <i>avec un acc. :</i> φ. τὴν γνώμην, THC. <i>3, 83,</i> qui a une intelligence vulgaire ; φ. τὰ γράμματα, PLAT. <i>Phædr. 242</i> c, inhabile à lire <i>ou</i> à écrire, illettré ; <i>avec un inf. :</i> μάχεσθαι, EUR. <i>I.T. 305 ;</i> λέγειν, PLAT. <i>Theæt. 181</i> d, impropre à combattre, à parler ;<br><b>   IV</b> de peu de prix :<br><b>      1</b> vil, commun : φ. σιτία, XÉN. <i>Mem. 1, 6, 2,</i> aliments grossiers ; ἱμάτιον, XÉN. <i>Mem. 1, 6, 2,</i> vêtement commun ; φ. ἀσπίδες, THC. <i>4, 9,</i> mauvais boucliers ;<br><b>      2</b> insignifiant, sans importance, HDT. <i>1, 26 ;</i> THC. <i>6, 21 ;</i> DÉM. <i>150, 29 ; avec une négation en un sens augmentat. :</i> οὐ φαῦλον πρᾶγμα, XÉN. <i>An. 6, 6, 11,</i> affaire non sans importance ;<br><b>      3</b> léger, insouciant, frivole : τὸ φαῦλον, THC. <i>6, 18,</i> la nature frivole <i>ou</i> insouciante de la jeunesse ;<br><b>      4</b> négligent, indolent, paresseux, XÉN. <i>Cyr. 2, 2, 24 ;</i> EUR. <i>Med. 807, Rhes. 285 ;</i><br><b>B</b> <i>sans idée de blâme :</i><br><b>   I</b> d’un rang inférieur : οἱ φαυλότατοι, THC. <i>6, 77,</i> les soldats de dernière classe ;<br><b>   II</b> humble, modeste, <i>p. opp. à</i> μείζονες, XÉN. <i>Hier. 1, 27 ;</i> PLAT. <i>Rsp. 475</i> b ; <i>joint à</i> ταπεινός, DH. <i>7, 45 ;</i><br><b>   III</b> simple :<br><b>      1</b> non compliqué, <i>joint à</i> πρόχειρος, PLAT. <i>Theæt. 147</i> a ; <i>à</i> ἁπλοῦν, PLAT. <i>Theæt. 147</i> c ; <i>à</i> ἄκομψος, EUR. <i>fr. 476 ; cf</i>. PLAT. <i>Gorg. 483</i> c, <i>1 Alc. 129</i> a, <i>etc. ;</i><br><b>      2</b> peu coûteux, PLAT. <i>Eryx. 314</i> d ; <i>particul</i>. frugal, HPC. <i>775</i> g ;<br><b>      3</b> facile, aisé, commode, AR. <i>Eq. 213 ;</i> PLAT. <i>Phil. 19</i> a, <i>etc. ; avec une négat. :</i> οὐ φαῦλον, <i>etc</i>. PLAT. <i>Theæt. 179</i> d, chose non facile.<br><span>•<i> Cp</i>. -ότερος, HPC. <i>753</i> a ; THC. <i>3, 37, 83, etc. ;</i> XÉN. <i>Hier. 1, 27, etc. ; Mem. 3, 11, 13, etc. ;</i> PLAT. <i>Rsp. 475</i> b, <i>Prot. 336</i> c, <i>etc. ;</i> EUR. <i>Epist. 1, 23</i>. <i>• Sup</i>. -ότατος, XÉN. <i>Mem. 1, 6, 2 ; 4, 1, 3 ;</i> AR. <i>Eq. 213</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, EUR. <i>Hipp. 435, etc. ;</i> THC. <i>6, 21</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φαυλος - φαῦλος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Tite (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G5338":"<h1>pheggos</h1>\n<p>Strong n° 5338 <i>Prononciation [feng'-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lumière\n<ol type=\"a\">\n<li>de la lune</li>\n<li>d'une chandelle ou lampe</li>\n</ol>\n</li>\n<li>la lumière brillante du soleil, un rayon de lumière</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φέγγος, εος-ους (τὸ)</b> éclat, lumière :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> <i>en gén</i>. HH. <i>Cer. 279 ;</i> ATT. ;<br><b>      2</b> lumière d’un corps céleste, <i>particul</i>. lumière du soleil, ESCHL. <i>Pers. 377 ;</i> SOPH. <i>Aj. 673, 859 ;</i> EUR. <i>El. 866 ; d’où</i> le soleil : αἱ αὐγαὶ τοῦ φέγγους, SPT. <i>2Macc. 12, 9,</i> les rayons du soleil ; <i>p. suite,</i> le jour, EUR. <i>Hec. 32 ; même avec idée de durée :</i> δεκάτῳ φέγγει τῷδε ἔτους, ESCHL. <i>Ag. 504,</i> voici la dixième année ; <i>d’où :</i> φ. ἰδεῖν, PD. <i>P. 4, 198,</i> voir le jour, venir à la lumière du jour, naître ; λιπεῖν φ. EUR. <i>Or. 954,</i> abandonner la lumière du jour, mourir ; lumière de la lune et des étoiles, XÉN. <i>Cyn. 5, 4 ;</i> PLAT. <i>Rsp. 508</i> c ;<br><b>      3</b> lumière d’un feu, ESCHL. <i>Eum. 1029, Ch. 1037 ;</i> de flambeaux, ESCHL. <i>Eum. 1022 ; d’où</i> lumière, torche, AR. <i>Ran. 445, 455 ;</i> XÉN. <i>Conv. 1, 9 ;</i> DH. <i>5, 42,</i> τὰ φέγγη, PLUT. <i>Cam. 25, etc</i>. les feux de garde ;<br><b>      4</b> éclat des yeux, EUR. <i>Hec. 368, 1035 ;</i> THCR. <i>Idyl. 24, 73 ;</i> τυφλὸν φ. EUR. <i>Hec. 1068,</i> éclat obscurci des yeux, cécité ;<br><b>      5</b> éclat, blancheur, <i>en gén</i>. HH. <i>Cer. 278 ; en parl. du lait,</i> ARSTT. <i>Meteor. 1, 8, 18 ;</i><br><b>   II</b> <i>fig</i>. rayonnement (<i>de la joie, du bonheur, etc</i>.), éclat, gloire, PD. <i>P. 8, 138 ; N. 3, 113 ; 4, 21 ; en parl. de la richesse,</i> PD. <i>O. 2, 102 ; en parl. de pers</i>. PD. <i>N. 9, 109 ;</i> ESCHL. <i>Ag. 602 ;</i> AR. <i>Pl. 640, Eq. 1319, etc</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φεγγος - φέγγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – le terme général pour la lumière : lumière d'un feu\n<br><br> – est un terme plus concret et plus accentué: la brillante lumière du soleil, le rayon de lumière\n<br><br> – est un terme encore plus fort, suggérant la nature ardente de la lumière; la chaleur du jour.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5339":"<h1>pheidomai</h1>\n<p>Strong n° 5339 <i>Prononciation [fi'-dom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>épargner</li>\n<li>s'abstenir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φείδομαι</b> <span>(<i>f</i>. φείσομαι, <i>ao</i>. ἐφεισάμην, <i>pf</i>. πέφεισμαι)</span> épargner, ménager, <i>d’où :</i><br><b>   I</b> traiter avec ménagement : τινος, IL. <i>21, 101 ; 24, 158, 187, etc. ;</i> OD. <i>9, 277 ; 16, 185, etc. ;</i> ESCHL. <i>Sept. 412 ;</i> SOPH. <i>Aj. 844 ;</i> HDT. <i>9, 139 ;</i> XÉN. <i>Cyr. 4, 2, 1,</i> qqn ; φείδεσθαί τινος ὡς μὴ φονεῦσαι, HDN <i>2, 13, 15,</i> épargner qqn de façon à ne pas le tuer ; φ. ἵππων, IL. <i>5, 202 ;</i> XÉN. <i>Cyr. 7, 1, 29,</i> ménager des chevaux ; φ. Ἰλίου, IL. <i>15, 215,</i> épargner Ilion ; φ. οὔτε ἰδίου οὔτε δημοσίου οἰκοδομήματος, THC. <i>1, 90,</i> n’épargner aucun édifice ni privé ni public ; οὐ φ. βίου, SOPH. <i>Ph. 749 ; ou</i> ψυχέων, ζωᾶς, TYRT. <i>10, 14 ; 15, 5 Bgk, ou</i> ψυχῆς, DÉM. <i>1394, 18,</i> ne pas ménager sa vie, la risquer hardiment <i>ou</i> la sacrifier ; <i>p. suite,</i> être modéré, doux, clément, THC. <i>3, 59 ;</i> τὸ φειδόμενον, PLUT. <i>M. 972</i> f, ménagement, <i>p. opp. à</i> τὸ κολάζον ; φ. ἐπί τινι, SPT. <i>Jer. 15, 5 ; 21, 7 ;</i> ἐπί τινα, SPT. <i>Jer. 28, 3 ;</i> περί τινος, SPT. <i>2Reg. 12, 6 ; Sir. 13, 12 ;</i> ὑπέρ τινος, SPT. <i>Jon. 4, 10 ;</i> ἀπό τινος, SPT. <i>1Reg. 15, 3 ; Ezech. 24, 21,</i> être bienveillant envers qqn, user de modération à l’égard de qqe ch. ; φ. τι, SPT. <i>Job 16, 5 ; 30, 10, m. sign. ;</i><br><b>   II</b> employer avec ménagement, user avec ménagement de, être économe <i>ou</i> avare de, ne pas vouloir donner : δέπαος, IL. <i>24, 236,</i> une coupe ; σίτου, HÉS. <i>O. 602,</i> de la nourriture ; <i>cf</i>. HDT. <i>8, 68 ;</i> XÉN. <i>Hipp. 8, 11 ;</i> PLAT. <i>Phæd. 78</i> a, <i>etc. ; abs. :</i><br><b>      1</b> être ménager, économe, THGN. <i>931,</i> DÉM. <i>753, 21 ;</i><br><b>      2</b> être discret, ANTH. <i>5, 269, etc. ;</i><br><b>   III</b> s’abstenir de, <i>d’où :</i><br><b>      1</b> éviter, <i>gén</i>. XÉN. <i>Cyr. 1, 6, 19 ; 5, 5, 18, etc. ; avec un part</i>. EUR. <i>Med. 401 ;</i><br><b>      2</b> <i>p. suite,</i> se dispenser de, omettre de, s’épargner la peine de, <i>inf</i>. EUR. <i>Or. 393 ;</i> PLAT. <i>Rsp. 574</i> b, <i>etc. ;</i><br><b>      3</b> se garder de, <i>avec μή et l’inf</i>. LUC. <i>Anach. 1, etc. ;</i> A. PL. <i>138, 6</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. ion</i>. φείδεο, OD. <i>22, 54 ;</i> HDT. <i>8, 68 ;</i> φείδευ, THCR. <i>Idyl. 8, 63 ; impf. 3 pl. poét</i>. φείδοντο, SOPH. <i>El. 716 ; fut. épq</i>. πεφιδήσομαι <span>[ῐ]</span>, IL. <i>15, 215 ; ao.1, 3 sg. épq</i>. φείσατο, IL. <i>24, 236 ; ao.2 avec redoubl</i>. πεφιδόμην, <i>d’où opt</i>. πεφιδοίμην, IL. <i>20, 464 ; 21, 101, etc. ; part. pf. épq</i>. πεφιδημένος <span>[ῐ]</span> NONN. <i>D. 11, 417, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>eid-, fendre ; <i>cf. sscr</i>. bhinádmi, <i>lat</i>. findō, <i>angl</i>. bite.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φειδομαι - φείδομαι</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (3)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5340":"<h1>pheidomenos</h1>\n<p>Strong n° 5340 <i>Prononciation [fi-dom-en'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>économiquement, chichement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φειδομένως</b>, <i>adv. :</i><br><b>      1</b> avec ménagement, PLUT. <i>Alex. 25 ;</i><br><b>      2</b> avec épargne, avec parcimonie, NT. <i>2Cor. 9, 6 ;</i><br><b>      3</b> avec circonspection, ANON. BYZ. <i>118, 40, 8</i>.<br><span><b>Étym</b>. φείδομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φειδομενως - φειδομένως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G5341":"<h1>phelones</h1>\n<p>Strong n° 5341 <i>Prononciation [fel-on'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un manteau de voyage, utilisé pour se protéger en temps d'orage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>φαινόλης, ου (ὁ)</b> sorte de casaque <i>ou</i> de manteau qui couvrait le haut du corps et les bras, RHINTHON (POLL. <i>7, 61</i>) ; ATH. <i>97</i> e ; ARTÉM. <i>2, 3 ;</i> NT. <i>2Tim. 4, 13</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. φαινόλας <span>[ᾱ]</span> RHINTHON <i>l.c</i>.<br><span><b>Étym</b>. <i>cf. lat</i>. pænula.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φελονης - φαιλόνης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5342":"<h1>phero</h1>\n<p>Strong n° 5342 <i>Prononciation [fer'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter\n<ol type=\"a\">\n<li>porter quelque fardeau\n<ol>\n<li>porter avec soi-même</li>\n</ol>\n</li>\n<li>déplacer par portage ; être transporté, ou porté, avec une suggestion de force ou de vitesse\n<ol>\n<li>de personnes transportées sur un navire sur les mers</li>\n<li>d'une rafale de vent, se précipiter</li>\n<li>de l'esprit, être mû intérieurement, remué</li>\n</ol>\n</li>\n<li>supporter c.à.d. soutenir (se garder de la chute)\n<ol>\n<li>de Christ, le conservateur de l'univers</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>supporter, c.à.d. endurer la rigueur d'une chose, supporter patiemment la conduite de quelqu'un, ou épargner quelqu'un (en s'abstenant de punir ou de détruire)</li>\n<li>apporter, amener, avancer une chose\n<ol type=\"a\">\n<li>aller vers, s'adresser à</li>\n<li>apporter en annonçant, annoncer</li>\n<li>apporter, c.à.d. produire ; amener dans un discours</li>\n<li>mener, conduire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φέρω</b> <span>(<i>f</i>. οἴσω, <i>ao.1</i> ἤνεγκα, <i>ao.2</i> ἤνεγκον, <i>pf</i>. ἐνήνοχα ; <i>pass. f</i>. ἐνεχθήσομαι, <i>ao</i>. ἠνέχθην, <i>pf</i>. ἐνήνεγμαι)</span><br><b>A <i>tr.</i></b> porter :<br><b>   I</b> porter une charge :<br><b>      1</b> porter sur soi <i>ou</i> avec soi : τι, IL. <i>5, 303, etc. ;</i> ATT. porter qqe ch. (une pierre, un vêtement, des armes, <i>etc</i>.) ; τινὰ ἐπ' ὤμοις, SOPH. <i>Tr. 564,</i> porter qqn sur ses épaules ; τὰ ὅπλα ἐπὶ τῆς κεφαλῆς, XÉN. <i>An. 4, 3, 6,</i> porter ses armes sur sa tête ; τινὰ ὑπὸ ζώνην, ESCHL. <i>Ch. 992 ; ou</i> ζώνης ὕπο, EUR. <i>Hec. 762,</i> porter un enfant dans son sein ; κοῦρον γαστέρι, IL. <i>6, 59,</i> porter un garçon dans son sein ; <i>avec ἐν et le dat</i>. IL. <i>18, 178 ; avec un dat. d’instrum. :</i> ὕδωρ κοσκίνῳ, PLAT. <i>Rsp. 363</i> d, porter de l’eau dans un crible ;<br><b>      2</b> <i>p. ext. c</i>. ἔχειν, porter avec soi, avoir, <i>à côté de</i> ἄγω, OD. <i>4, 612 ; p. opp. à</i> κενός, HDT. <i>7, 131 ;</i> XÉN. <i>Mem. 3, 13, 6 ;</i> φ. τινὶ φάος, OD. <i>19, 24,</i> porter la lumière devant qqn ; <i>cf</i>. AR. <i>Nub. 1490 ;</i> πονεῖν τὰ ὅπλα φέροντες ἐμελέτων, XÉN. <i>Cyr. 2, 3, 14,</i> ils s’exerçaient à la fatigue en portant leurs armes ; φέρειν γλῶσσαν κακήν, ESCHL. <i>Suppl. 995,</i> avoir une langue méchante, <i>càd</i>. disposée à médire (contre l’étranger) ; χεῖρας ἁγνὰς αἵματος φ. EUR. <i>Hipp. 316,</i> avoir des mains pures de sang ; <i>avec indication de la direction :</i> πῆ δὴ τόξα φέρεις ; OD. <i>21, 362,</i> où portes-tu donc l’arc ? πρόσω φέρειν, OD. <i>21, 369,</i> porter en avant ; οἴκαδε φ. PLAT. <i>Leg. 914</i> b, porter chez soi, <i>etc. ; fig</i>. τὸ πᾶν ἡμῖν τοῦ πολέμου φέρουσι αἱ νῆες, HDT. <i>8, 62,</i> nos vaisseaux portent en eux tout le sort de la guerre ; ἀγὼν ὁ τὸ πᾶν φέρων, HDT. <i>8, 100,</i> le combat qui décide de tout ; φ. τι διὰ μνήμης, HDN <i>2, 2, 9,</i> porter une chose dans sa mémoire, s’en souvenir ; <i>p. suite, au pass</i>. prendre sa marche, son cours : ὀλιγώρως ἔχειν καὶ ἐᾶν ταῦτα φέρεσθαι, DÉM. <i>106, 12,</i> être indifférent et laisser ces choses aller leur cours ; <i>d’où</i> se comporter, être : <i>au sens act</i>. βίᾳ φέρεσθαι, ESCHL. <i>Ch. 80,</i> se conduire avec violence ; <i>au sens pass</i>. καλῶς φέρεσθαι τὸ καθ' ἑαυτόν, THC. <i>2, 60,</i> se trouver quant à soi (<i>càd</i>. en particulier, <i>p. opp. à l’ensemble du pays</i>) dans une bonne situation ; τὰ πράγματα κακῶς φέρεται, XÉN. <i>Hell. 3, 4, 25,</i> les affaires vont mal ; εὖ φέρεσθαι, XÉN. <i>Œc. 5, 17,</i> être en bonne situation ; εὖ φερόμενοι, THC. <i>5, 15,</i> heureux dans la guerre ; φέρεσθαι ἐν προτιμήσει παρά τινι, DS. <i>Exc. p. 628, 86,</i> être en faveur auprès de qqn ; χεῖρον φέρεσθαι παρά τινι, JOS. <i>A.J. 16, 7, 6,</i> être en très mauvaise situation auprès de qqn ;<br><b>      3</b> porter en soi <i>ou</i> sur soi, produire : καρπόν, HÉS. <i>O. 117, 561,</i> des fruits ; σῖτον, XÉN. <i>Vect. 1, 5,</i> du blé ; ὅσα γῆ φέρει, PLAT. <i>Criti. 118</i> e, tout ce que la terre produit ; ἄμπελοι φέρουσιν οἶνον, OD. <i>9, 110,</i> les vignes produisent du vin ; <i>abs</i>. αἱ ἄμπελοι φέρουσι, XÉN. <i>Œc. 20, 4,</i> les vignes produisent ; ἡ γῆ ἔφερε, HDT. <i>5, 82,</i> la terre produisit, devint fertile ; ἡ ἐνεγκοῦσα, M. ANT. <i>4, 48,</i> celle qui produit, <i>càd</i>. la terre ; <i>p. suite, abs</i>. donner du profit : φ. ἐν γεωργίᾳ, XÉN. <i>Hipp. 9, 2,</i> donner du profit dans l’agriculture ; <i>fig</i>. φ. φρονιμωτάτους ἄνδρας, PLAT. <i>Tim. 24</i> c, produire des hommes très sensés, <i>en parl. d’un lieu ; particul. en parl. du lieu de naissance de qqn,</i> PHILSTR. <i>V. soph. p. 530, 568, 577, 585 ;</i><br><b>      4</b> <i>fig</i>. supporter, <i>càd</i>. trouver supportable : τὰς ἐμὰς διατριϐὰς καὶ τοὺς λόγους, PLAT. <i>Ap. 37</i> c, mes écrits et mes discours ; <i>ou</i> prendre sur soi, se charger de : τὰς οὐ προσήκουσας ἁμαρτίας, ANT. <i>122, 14,</i> des fautes d’autrui ; τὰς αὑτοῦ ἁμαρτίας, ANT. <i>124, 13,</i> de ses propres fautes ; résister à, être capable de porter, avoir la force de supporter : λυγρά, OD. <i>18, 135,</i> des choses pénibles ; δούλιον ζυγόν, ESCHL. <i>Ag. 1226,</i> le joug de la servitude ; πημονάς, ESCHL. <i>Pers. 293,</i> des douleurs ; κακόν <i>ou</i> κακά, ATT. du mal, des maux ; τὰ τῆς τύχης, THC. <i>2, 69,</i> les vicissitudes de la fortune ; τὰ παρόντα, PLAT. <i>Criti. 121</i> b, les circonstances présentes ; <i>avec un détermin. :</i> σιγῇ κακά, EUR. <i>Hec. 738,</i> supporter des maux en silence ; ὀργῇ τὸν πόλεμον, THC. <i>1, 31,</i> supporter la guerre avec colère ; <i>avec un adv</i>. φ. ῥᾳδίως τι, ATT. ; ῥηϊδίως, HÉS. <i>O. 213 ;</i> ῥᾷστα, SOPH. <i>O.R. 983,</i> supporter qqe ch. facilement, très facilement ; κουφότατα, HDT. <i>1, 35,</i> supporter très légèrement ; εὐπόρως, SOPH. <i>Ph. 872,</i> supporter facilement ; ἀνδρείως, PLAT. <i>Menex. 247</i> d, supporter virilement ; φ. τι βαρέως, XÉN. <i>Hell. 7, 1, 44 ;</i> δυσπετῶς, ESCHL. <i>Pr. 752 ;</i> πικρῶς, EUR. <i>Ion 610 ;</i> χαλεπῶς, PLAT. <i>Rsp. 330</i> a, <i>etc</i>. supporter avec peine, difficilement ; <i>avec un part</i>. βαρέως ἤνεικε ἰδὼν ἄνδρα λελωϐημένον, HDT. <i>3, 155,</i> il supporta avec peine de voir l’homme mutilé ; <i>qqf. en ce sens avec le dat. pour marquer l’idée d’un sentiment moins passif :</i> ἀλγεινῶς φ. οἷς ἐγὼ ἔπαθον, SOPH. <i>Ph. 1011,</i> supporter avec peine ce que je souffris, <i>càd</i>. m’irriter de ce que, <i>etc. ;</i> χαλεπῶς φ. τοῖς παροῦσι, XÉN. <i>An. 1, 3, 3,</i> s’irriter <i>ou</i> s’indigner de l’état présent des affaires ; τῷ πολέμῳ, XÉN. <i>Hell. 5, 1, 29,</i> de la guerre ; βαρέως φ. τῇ ἀτιμίᾳ, XÉN. <i>Hell. 3, 4, 9,</i> du déshonneur ; <i>avec ἐπί et le dat. :</i> χαλεπῶς φ. ἐπὶ τῇ πολιορκίᾳ, XÉN. <i>Hell. 7, 4, 21,</i> supporter avec peine que (des citoyens Spartiates) fussent assiégés ; <i>cf</i>. ISOCR. <i>281</i> a ; DH. <i>3, 50 ;</i> DS. <i>14, 61, 99 ;</i> PLUT. <i>Cim. 6, etc. ; de même avec</i> βαρέως, DS. <i>3, 59 ;</i> EL. <i>V.H. 2, 4 ;</i> PLUT. <i>Rom. 17, etc. ; avec</i> πρᾴως : πρᾴως φ. ἐπὶ τοῖς γιγνομένοις, DÉM. <i>1339, 20,</i> supporter avec calme ce qui arrive ; <i>postér. avec πρός et l’acc. :</i> χαλεπῶς φ. πρός τι, JUL. <i>Or. 1, 17</i> c ; <i>ou avec διά et l’acc. ;</i> χαλεπῶς φ. διά τι, LIB. <i>4, 755,</i> supporter qqe ch. péniblement ;<br><b>   II</b> porter d’un lieu à un autre :<br><b>      1</b> porter, transporter : πόδες φέρον, IL. <i>6, 514,</i> ses pieds le portaient ; <i>cf</i>. IL. <i>24, 341 ;</i> OD. <i>1, 97, etc. ;</i> ἵππω φέρουσιν ἅρμα, IL. <i>5, 232 ; 11, 533, etc</i>. les deux chevaux emportent le char ; ἵππους οἵ σε πόλινδ' οἴσουσι, IL. <i>13, 820,</i> des chevaux qui te porteront à la ville ; <i>au pass</i>. φερόμενοι ἐν ὀχήμασι, PLAT. <i>Epin. 986</i> b, transportés dans des voitures ; <i>en parl. de navires :</i> φ. τινά, IL. <i>9, 306, etc. ;</i> OD. <i>16, 323,</i> emporter qqn ; φ. ἐπὶ πόντον, OD. <i>5, 164,</i> emporter sur la mer ; <i>particul. en parl. du vent favorable ou contraire :</i> ἄνεμος φέρει νῆας, OD. <i>10, 26,</i> le vent porte les vaisseaux ; ὁ βορέας εἰς τὴν Ἑλλάδα φέρει, XÉN. <i>An. 5, 7, 7,</i> le vent du Nord pousse les vaisseaux vers la Grèce, <i>càd</i>. souffle vers la Grèce ; ἄνεμος φέρων, OD. <i>3, 300 ; 5, 111 ; 7, 277, etc</i>. vent favorable ; πῦρ ἄνεμος φέρει, IL. <i>11, 156,</i> le vent propage le feu ; <i>fig</i>. ὅπῃ ἂν ὁ λόγος ὥσπερ πνεῦμα φέρῃ, ταύτῃ ἰτέον, PLAT. <i>Rsp. 394</i> d, par où porte la parole comme un souffle, c’est par là qu’il faut aller ; <i>avec idée de violence :</i> φ. τι, IL. <i>1, 301,</i> emporter qqe. ch. ; <i>cf</i>. PLUT. <i>M. 95</i> b ; <i>en parl. de tempête :</i> τοὺς δὲ ἄελλαι φέρουσιν ἐπὶ πόντον, IL. <i>19, 378,</i> la tempête les emporte sur la mer ; <i>cf</i>. OD. <i>4, 516 ; 5, 420, etc. ;</i> φ. πόντονδε, OD. <i>10, 48,</i> emporter sur la mer ; σχεδίην ἂμ πέλαγος ἄνεμοι φέρον ἔνθα καὶ ἔνθα, OD. <i>5, 330,</i> les vents emportaient le radeau çà et là à travers la mer ; <i>au pass</i>. φερόμενοι ἢ καλινδούμενοι λίθοι, XÉN. <i>An. 4, 7, 6,</i> pierres lancées <i>ou</i> roulées (du haut des collines) ; θυέλλῃ φέρεσθαι, OD. <i>10, 54 ; ou</i> ἀνέμοις φέρεσθαι, OD. <i>9, 82,</i> être emporté par la tempête <i>ou</i> par les vents ; <i>abs</i>. πᾶν δ' ἦμαρ φερόμην, IL. <i>1, 592,</i> je fus emporté tout le jour, <i>en parl. d’Hèphæstos précipité de l’Olympe ;</i> ἧκε φέρεσθαι, IL. <i>21, 120,</i> il le lança de façon qu’il fût emporté ; <i>d’où</i> se porter, se transporter : φέρεσθαι εἴς τινα, XÉN. <i>Hell. 3, 2, 3 ;</i> ἐπί τινα, XÉN. <i>Cyn. 3, 10 ;</i> πρός τινα, XÉN. <i>Cyr. 1, 4, 21,</i> se porter <i>ou</i> se diriger vers qqn, se précipiter sur qqn ; ἰθὺς φ. IL. <i>20, 172 ;</i> φ. ὁμόσε τινί, XÉN. <i>Cyr. 1, 4, 11,</i> se porter droit à la rencontre de qqn ; φ. εἰς τὸν Τάρταρον, PLAT. <i>Phæd. 114</i> b, descendre dans le Tartare ; φ. κατὰ τῶν πετρῶν, XÉN. <i>An. 4, 7, 14,</i> tomber du haut des rochers ; <i>au part. joint à un verbe à un mode personn. :</i> φερόμενοι ἐσέπιπτον ἐς τοὺς Αἰγινήτας, HDT. <i>8, 91,</i> les vaisseaux (qui avaient échappé aux Athéniens) tombaient sur les Éginètes (qui les détruisaient) ; <i>fig</i>. ἀπὸ τῆς ἐλπίδος ᾠχόμην φερόμενος, PLAT. <i>Phæd. 98</i> b, j’étais tombé brusquement du haut de cette espérance ; <i>cf</i>. XÉN. <i>Cyr. 2, 3, 3, etc. ;</i> PLAT. <i>Phæd. 98</i> b, <i>etc. ;</i><br><b>      2</b> porter, conduire : ὁδὸς φέρει ἐς, <i>acc</i>. HDT. <i>2, 122, 138, etc</i>. la route conduit à, <i>etc. ; ou en s.-e</i>. ὁδός : ἡ δὲ πρὸς ἕω ἐπὶ Σοῦσα φέρει, XÉN. <i>An. 3, 5, 15,</i> la route conduit dans la direction de l’orient vers Suse ; εἰς τὴν πόλιν φέρουσαι πύλαι, XÉN. <i>Hell. 7, 2, 7,</i> les portes qui conduisent à la ville ; <i>particul. en parl. de pays,</i> porter dans une direction, <i>d’où</i> s’étendre dans une direction : ἡ ἐπὶ θάλασσαν φέρουσα χώρη, HDT. <i>4, 99,</i> le pays qui se dirige vers la mer ; τὰ ἐς τὴν μεσόγαιαν φέροντα, HDT. <i>4, 100,</i> la région qui s’étend dans l’intérieur des terres ; τὰ πρὸς νότον φέροντα, HDT. <i>7, 201,</i> le pays qui s’étend vers le midi ; <i>fig</i>. τὰ πρὸς τὸ ὑγιαίνειν φέροντα, XÉN. <i>Mem. 4, 2, 31,</i> ce qui contribue à entretenir la santé ; φ. ἐς αἰσχύνην, HDT. <i>1, 10,</i> conduire à la honte, causer de la honte ; φ. πρὸς εὐδαιμονίαν, PLAT. <i>Menex. 247</i> e, conduire au bonheur ; φ. εἰς ὠφέλειαν, PLAT. <i>2 Alc. 142</i> b, mener au bien de, <i>etc. ; d’où abs</i>. tendre à : ἐς τί ὑμῖν ταῦτα φαίνεται φέρειν ; HDT. <i>1, 120,</i> à quoi cela vous semble-t-il mener ? <i>càd</i>. à votre avis que doit-il résulter de cela ? τῶν πλειόνων ἐπὶ τὸ αὐτὸ αἱ γνώμαι ἔφερον, THC. <i>1, 79,</i> les avis du plus grand nombre tendaient à la même conclusion ; <i>avec</i> ὡς : ἡ τοῦ δήμου φέρει γνώμη ὡς, HDT. <i>4, 11,</i> l’opinion du peuple tend à ce que ; <i>avec l’inf. :</i> τῶν ἡ γνώμη ἔφερε συμϐάλλειν, HDT. <i>5, 118 ; 6, 110,</i> ceux dont l’avis tendait à combattre ; πλέον ἔφερέ οἱ ἡ γνώμη <i>avec l’inf</i>. HDT. <i>8, 100,</i> son avis tendait davantage à, <i>etc. ; particul</i>. diriger : αἰτίαν ἐπί τινα, POL. <i>33, 5, 2,</i> une accusation contre qqn ; τὰ πράγματα φ. ἐπί τινι, POL. <i>2, 85, 6,</i> reporter la direction des affaires sur qqn, charger qqn de diriger les affaires ; <i>fig</i>. φ. τὴν δόξαν ἐπί τι, PLAT. <i>Rsp. 478</i> b, rapporter la gloire à qqe ch. ; τοὔνομα ἐπί τι, PLAT. <i>Charm. 163</i> d, <i>Soph. 250</i> d, attribuer un nom à qqe ch. ; <i>abs</i>. φ. τὴν πόλιν, PLUT. <i>Luc. 6,</i> diriger la ville ; τὸ φέρον ἐκ θεοῦ, SOPH. <i>O.C. 1693,</i> ce qui vient des dieux (le sort, la fortune) ;<br><b>      3</b> porter çà et là, faire mouvoir, déplacer (des pions sur un échiquier) <i>acc</i>. PLAT. <i>Rsp. 487</i> d ;<br><b>      4</b> porter, lancer, asséner : πληγήν, POL. <i>2, 33, 6,</i> un coup ;<br><b>      5</b> apporter : τι, HOM. ATT. qqe ch. (τόξα, OD. <i>21, 359,</i> des flèches ; κρητῆρα, IL. <i>3, 246,</i> un cratère ; γῆν τε καὶ ὕδωρ, HDT. <i>7, 132,</i> la terre et l’eau, <i>en signe de soumission, etc.) ; particul</i>. offrir : δῶρα, OD. <i>8, 428,</i> des présents ; δῶρα πρός τινα, XÉN. <i>An. 7, 3, 31,</i> des présents à qqn ; τινί τι, SOPH. <i>Tr. 602 ;</i> ἄποινα, IL. <i>24, 502,</i> remettre qqe ch. à qqn, apporter une rançon ; transmettre : ἀγγελίην τινί, IL. <i>10, 288 ;</i> μῦθόν τινι, IL. <i>15, 202, etc</i>. apporter une nouvelle, une parole à qqn ; <i>d’où abs</i>. annoncer, mander : τι, ESCHL. <i>Pers. 248 ;</i> σαφῆ ἐκ στρατοῦ, ESCHL. <i>Sept. 40,</i> des nouvelles certaines rapportées de l’armée ; ἐπιστολήν, XÉN. <i>Ages. 8, 3 ;</i> ἐπιστολάς τινι, SOPH. <i>Aj. 781,</i> apporter une lettre, des lettres à qqn ; λόγους τινὶ παρά τινος, SOPH. <i>El. 666,</i> apporter à qqn des paroles de la part de qqn ; ὑποσχέσεις, DÉM. <i>77, 22,</i> transmettre des promesses ; <i>d’où</i> produire : φ. καὶ ἄγειν ὅ τι ἕκαστος εἶχε, XÉN. <i>Cyr. 3, 3, 2,</i> emporter et emmener ce que chacun possédait ; <i>cf</i>. XÉN. <i>Cyr. 5, 4, 28 ;</i> PLAT. <i>Phædr. 279</i> c, <i>Leg. 817</i> a, <i>etc. (mais v. ci-dessous la même loc. en mauv. part</i>) ; μάρτυρα, DÉM. <i>1273, 19,</i> produire un témoin ; παραδείγματα, POL. <i>17, 13, 7,</i> apporter des exemples ; τινὶ ἀπολογισμούς, POL. <i>1, 32, 4,</i> fournir des justifications à qqn ; πάσας αἰτίας, DÉM. <i>1328, 22,</i> apporter toutes les raisons possibles ; ψῆφον, ESCHL. <i>Eum. 680, etc. ;</i> PLAT. <i>Leg. 766</i> b, <i>etc</i>. apporter son suffrage ; <i>d’où abs</i>. φέρειν, choisir par un vote, élire <i>ou</i> désigner par un vote : φέρειν τινὰ χορηγόν, DÉM. <i>496, 19,</i> élire <i>ou</i> désigner qqn comme chorège ; φέρειν ὃν ἂν ἕκαστος βούληται, PLAT. <i>Leg. 753</i> d, choisir celui que chacun voudrait ; <i>cf</i>. PLAT. <i>Leg. 946</i> a ; DÉM. <i>496, 20 ; 996, 21, etc. ; particul</i>. apporter ce qu’on doit, <i>d’où</i> payer, acquitter : φόρον, THC. <i>4, 57,</i> une contribution ; φόρους παρά τινα, PLAT. <i>Pol. 298</i> a, payer des contributions à qqn ; μισθόν, THC. <i>3, 17, etc. ;</i> XÉN. <i>Cyr. 1, 6, 12,</i> payer un salaire ; τίμημα χρημάτων, DÉM. <i>197, 28,</i> payer une amende ; <i>fig</i>. χάριν τινί, accorder sa faveur à qqn, IL. <i>5, 211, 874 ; 21, 458 ;</i> OD. <i>5, 307 ;</i> EUR. <i>Med. 508, etc. ;</i> PLAT. <i>Tim. 21</i> c, <i>etc. ; ou</i> apporter ses remerciements à qqn, PD. <i>O. 10, 21 ; ou au contr</i>. emporter de la reconnaissance, être remercié <i>ou</i> récompensé de qqe ch. SOPH. <i>O.R. 764 ;</i> εὐνοίας τινί, ESCHL. <i>Suppl. 489,</i> montrer de la bienveillance pour qqn ; <i>p. suite,</i> apporter, causer : Σείριος φέρει πυρετὸν βροτοῖσι, IL. <i>22, 31,</i> Sirius apporte aux mortels une chaleur ardente ; φ. τινὶ Ἄρηα, IL. <i>3, 132,</i> apporter la guerre à qqn ; φόνον, IL. <i>2, 352 ; 3, 6, etc</i>. apporter la mort par le meurtre ; κακόν, IL. <i>8, 541, etc. ;</i> κακά, OD. <i>4, 273 ;</i> ἄλγεα, OD. <i>12, 427, etc</i>. causer du mal, des maux, des douleurs ; αἰσχύνην, SOPH. <i>Tr. 66 ;</i> EUR. <i>Hec. 1241, etc</i>. apporter de la honte ; βλάϐην, XÉN. <i>Œc. 3, 5,</i> causer un tort ; κλέος τινί, OD. <i>1, 283,</i> procurer de la gloire à qqn ; νίκην, SOPH. <i>El. 84,</i> procurer une victoire ; σωτηρίαν, EUR. <i>Tr. 748,</i> procurer le salut ; σωτηρίαν ἢ κίνδυνόν τινι, XÉN. <i>Ath. 1, 3,</i> procurer le salut à qqn <i>ou</i> l’exposer à un danger ; χάρμα τινί, EUR. <i>Her. 637,</i> procurer de la joie à qqn ; τῇ πόλει κέρδος ἢ ζημίαν, PLAT. <i>Leg. 835</i> b, procurer un gain à la cité <i>ou</i> lui causer un dommage ; <i>avec un inf</i>. τέχναι θεσπιῳδὸν φόϐον φέρουσιν μαθεῖν, ESCHL. <i>Ag. 1134,</i> l’art des devins apporte des réponses qui font éprouver la terreur de, <i>etc. ; p. suite,</i> amener avec soi, avoir pour conséquence : ὥσπερ τὸ δίκαιον ἔφερε, HDT. <i>5, 58,</i> comme la justice l’apportait avec elle, <i>càd</i>. comme cela était juste ; <i>p. suite,</i> contribuer à : ταῦτα φέρει τι εἴς τι, XÉN. <i>Cyr. 8, 1, 42,</i> cela contribue pour une part à qqe ch. ; <i>cf</i>. PLAT. <i>Rsp. 449</i> d ;<br><b>      6</b> emporter, emmener : τινά, IL. <i>2, 302 ;</i> OD. <i>14, 207,</i> qqn, <i>en parl. des Génies de la mort ;</i> λέων φέρει αἶγα, IL. <i>13, 199,</i> un lion emporte une chèvre ; <i>cf</i>. OD. <i>12, 99, etc. ; d’où</i> dépouiller, piller : θεῶν ἱερά, EUR. <i>Hec. 803,</i> les temples des dieux ; ἀλλήλους, THC. <i>1, 6,</i> se piller les uns les autres ; <i>au pass</i>. EUR. <i>Bacch. 758 ; d’ord</i>. ἄγειν καὶ φέρειν <i>ou</i> φέρειν καὶ ἄγειν, IL. <i>5, 484 ;</i> HDT. <i>1, 88, litt</i>. emmener et emporter <i>ou</i> emporter et emmener, <i>càd</i>. piller ; ἄγειν καὶ φ. ἀλλήλους, HDT. <i>6, 42,</i> se piller les uns les autres ; ἄγειν καὶ φ. τὴν Βιθυνίδα, XÉN. <i>Hell. 3, 2, 2,</i> piller la Bithynie ; <i>au pass</i>. Χερρόνησος φέρεται καὶ ἄγεται ὑπὸ τῶν Θρᾳκῶν, XÉN. <i>Hell. 3, 2, 8,</i> la Chersonèse est pillée par les Thraces ; ἄγομαι φέρομαι, AR. <i>Nub. 241,</i> on m’emmène, on m’emporte, <i>càd</i>. on me dépouille ; <i>de même,</i> λαμϐάνειν τε καὶ φ. PLAT. <i>Leg. 762</i> a. ; <i>p. suite,</i> remporter, obtenir : μέγα κράτος, IL. <i>18, 308,</i> une grande victoire ; τρίποδα, HÉS. <i>O. 655,</i> remporter un trépied comme prix de la victoire ; τἀπινίκια, SOPH. <i>El. 692 ;</i> τὰ νικητήρια, PLAT. <i>Leg. 657</i> e, le prix de la victoire ; τὰ ἀριστεῖα, PLAT. <i>Rsp. 468</i> c, remporter le prix de la bravoure ; μισθὸν δύο δραχμάς, AR. <i>Ach. 66,</i> recevoir pour salaire deux drachmes ; φ. κέρδος, SOPH. <i>Ant. 464, etc</i>. retirer un gain de qqe ch. ; πλέον φ. SOPH. <i>O.C. 651,</i> avoir plus d’avantage ;<br><b>      7</b> porter ça et là, faire circuler de main en main, de bouche en bouche, <i>d’où</i> célébrer : τινά, PHILSTR. <i>V. Ap. 2, 21,</i> qqn ; πολύν τινα, ESCHN. <i>Ctes. § 223,</i> vanter beaucoup qqn ; <i>au pass</i>. μέγα τοι φέρεται πὰρ σέθεν, PD. <i>P. 1, 170,</i> on rapporte de toi de grandes choses ; εὖ φέρεσθαι παρά τινι, XÉN. <i>Hell. 2, 1, 6,</i> avoir bon renom auprès de qqn ; πονήρως φέρεσθαι ἐν τῇ στρατιᾷ, XÉN. <i>Hell. 1, 5, 17,</i> être en mauvaise situation dans l’armée ; φιλοσοφία ἀτίμως φέρεται ὑπὸ τῶν ἀνθρώπων, PLAT. <i>Ep. 328</i> e, la philosophie est discréditée par les hommes ; <i>p. suite, simpl</i>. rapporter, nommer ; ὧν τὰ ὀνόματα φέρεται, PTOL. <i>7, 4, 11,</i> dont on rapporte les noms ; πόλεις φέρονται αἵδε, PTOL. <i>6, 20, 4,</i> on mentionne les villes suivantes ; <i>avec un inf</i>. τοιόνδε φέρεται πρῆγμα γίγνεσθαι, HDT. <i>8, 104,</i> on assure qu’il arrive ceci ;<br><b>   III</b> <i>emplois particuliers :</i><br><b>      1</b> <i>l’impér. prés. φέρε entre dans certaines loc. au sens de :</i> « eh bien ! voyons ! » <i>devant γάρ ou δή suivi d’un impér. :</i> φέρ' εἰπὲ δή μοι, SOPH. <i>Ant. 534 ;</i> φέρε δή μοι τόδε εἰπέ, PLAT. <i>Crat. 385</i> b, voyons, dis-moi ceci ; <i>devant un sbj. 1 sg</i>. τοισδὶ φέρε δῶ, AR. <i>Pax 969,</i> allons ! laisse-moi le leur donner ; φέρε ἀκούσω, HDT. <i>1, 11,</i> allons ! laisse-moi entendre, <i>càd</i>. fais-moi savoir ; <i>au plur. :</i> φέρε δὴ ἴδωμεν, PLAT. <i>Gorg. 455</i> a ; ἀλλὰ φέρε δὴ σκεψώμεθα, PLAT. <i>Prot. 330</i> b, voyons ! examinons ; <i>devant une propos. interrog. :</i> φέρε τίς γὰρ οὗτος ἀνήρ ; AR. <i>Nub. 219,</i> eh ! quelle espèce d’homme est-ce donc ? <i>dans une propos. interrog. dev. δή :</i> φέρε δὴ τί γαμεῖθ' ἡμᾶς ; AR. <i>Th. 789,</i> eh bien, voyons ! pourquoi nous épousez-vous ? <i>dev. γάρ :</i> φέρε γὰρ πρὸς Διὸς τί ἐροῦμεν ; DÉM. <i>98, 16,</i> car voyons, par Zeus, que dirons-nous ? <i>ou au sens de</i> « suppose », « supposez », <i>avec un inf. :</i> φέρε λέγειν τινά, PLUT. <i>M. 98</i> b, supposons que qqn dise, <i>etc. ;</i> φέρε εἰπεῖν, D. CHR. <i>Or. 31, § 163 ;</i> PTOL. <i>1, 2, 3 ;</i> οἷον φέρε εἰπεῖν, PORPH. <i>Abst. 3, 3,</i> par exemple ;<br><b>      2</b> <i>le part. φέρων est souv. explétif ou signifie simpl. que l’action marquée par le verbe est spontanée :</i> δὸς τῷ ξείνῳ φέρων, OD. <i>17, 345,</i> donne cela à notre hôte, porte-le lui ; μάλα δ' ὦκα φέρων ἔδωκε, OD. <i>22, 146,</i> il se hâta de les apporter et de les donner (aux prétendants) ; ἔγχος ἔστησε φέρων, OD. <i>1, 127,</i> il apporta la lance et la posa ; <i>cf</i>. OD. <i>1, 139 ;</i> SOPH. <i>Tr. 622 ;</i> PLAT. <i>Rsp. 345</i> b, <i>etc. ;</i><br><b>B</b> <i>intr. (s.-e</i>. ἑαυτόν) se porter : φέρουσα (<i>s.-e</i>. ἑαυτήν) ἐνέϐαλε νηῒ φίλῃ, HDT. <i>8, 87,</i> elle se précipita avec violence sur un navire ami ; <i>cf</i>. PLUT. <i>Arist. c. Cat. ma. 1 ;</i><br><b><i>Moy</i>. φέρομαι</b> <span>(<i>f</i>. οἴσομαι, <i>ao.1</i> ἠνεγκάμην, <i>etc</i>.)</span><br><b>      1</b> porter sur soi <i>ou</i> avec soi : τι, HDT. <i>7, 50 ;</i> XÉN. <i>Cyr. 6, 2, 33, etc. ;</i> SOPH. <i>El. 476 ;</i> EUR. <i>Andr. 1282,</i> qqe ch. ;<br><b>      2</b> emporter pour soi : τι ἐκ δόμων, OD. <i>15, 19,</i> qqe ch. de la maison ; οἴκοθεν σῖτον, XÉN. <i>Cyr. 1, 2, 8,</i> emporter de la nourriture de la maison ; ἔναρα, IL. <i>22, 245,</i> des armes comme butin ; πελέκεας οἶκόνδε, IL. <i>23, 856,</i> emporter pour soi (comme prix d’adresse) des haches ; πυρούς, οἶνον, σῦκα, XÉN. <i>An. 6, 6, 1,</i> emporter du blé, du vin, des figues ;<br><b>      3</b> porter pour soi d’un lieu à un autre, déplacer pour soi : πεττοὺς φ. PLAT. <i>Eryx. 395</i> b, pousser ses pions (sur l’échiquier) ;<br><b>      4</b> apporter avec soi : χοὰς ἐκ κρήνης, SOPH. <i>O.C. 470,</i> de l’eau d’une fontaine ; <i>cf</i>. ESCHL. <i>Eum. 266 ; p. suite, en gén</i>. se procurer : ὕδωρ ἐπὶ δεῖπνον, XÉN. <i>An. 7, 4, 3,</i> de l’eau pour le souper ; βιοτάν, EUR. <i>Andr. 786,</i> choisir une règle de conduite ;<br><b>      5</b> se faire apporter, <i>d’où</i> recevoir : ἀγγελίας ἔπος, EUR. <i>Ph. 1540,</i> un message ; μαντεύματα, HÉS. <i>fr. 39, 8 Gaisford,</i> des prédictions ;<br><b>      6</b> remporter, obtenir pour soi : δῶρα παρά τινος, IL. <i>4, 97,</i> recevoir des présents de qqn ; τι παρά τινος, HDT. <i>5, 47,</i> recevoir en présent qqe ch. de qqn ; μισθόν, XÉN. <i>Œc. 1, 4,</i> recevoir un salaire ; <i>particul</i>. remporter comme un prix : ἀέθλιον, IL. <i>9, 127 ;</i> ἄεθλον, IL. <i>23, 441 ;</i> τὰ ἆθλα, PLAT. <i>Rsp. 613</i> c, remporter le prix, les récompenses ; τὰ πρῶτα, IL. <i>23, 275 ;</i> τὰ δευτέρα, IL. <i>23, 538,</i> obtenir le premier, le second rang ; φ. τὰ δεύτερα παρὰ τῷ βασιλέϊ, HDT. <i>8, 104,</i> occuper le second rang auprès du roi ; φ. νικητήρια, PLAT. <i>Phædr. 245</i> b, remporter le prix de la victoire ; τῶν νομίμων φ. ἄριστα, SOPH. <i>El. 1095,</i> obtenir le premier rang pour le respect des lois ; φ. μέγιστα ἀγαθά, PLAT. <i>Phæd. 64</i> a, obtenir les plus grands biens ; φ. εὐσέϐειαν ἔκ τινος, SOPH. <i>El. 969,</i> recevoir de qqn des louanges pour la piété qu’on a témoignée ; δάκρυ πρὸς τῶν κλυόντων, ESCHL. <i>Pr. 639,</i> obtenir une larme des auditeurs ; ταῦτα ἐπὶ σμικρόν τι ἐφέροντο τοῦ πολέμου, HDT. <i>4, 129,</i> cela ne fut que de peu de conséquence dans la guerre ; πλέον <i>ou</i> πλεῖον φέρεσθαί τινος, arriver à un meilleur résultat qu’un autre, HDT. <i>7, 211 ; ou</i> obtenir plus qu’un autre, <i>càd</i>. être mieux partagé, EUR. <i>Hec. 308 ; en mauv. part :</i> φ. ὀνείδη, PLAT. <i>Leg. 762</i> a, remporter de l’ignominie ; ἀπέχθειαν, ANT. <i>124,</i> assumer l’odieux de qqe ch., la haine qui s’attache à une chose.<br><span> <i>Act. prés. ind. 3 pl. dor</i>. φέροντι, PD. <i>P. 10, 70, et</i> φέροισι, PD. <i>fr. 205 ; sbj. 3 sg</i>. φέρῃσι, OD. <i>10, 507 ; part. fém. dor</i>. φέροισα, PD. <i>P. 3, 15 ;</i> THCR. <i>Idyl. 2, 148 ; inf. épq</i>. φερέμεν, IL. <i>9, 411 ;</i> HÉS. <i>O. 215. Impf. itér</i>. φέρεσκον, OD. <i>9, 429 ; 10, 108. Fut. dor</i>. οἰσῶ, THCR. <i>Idyl. 3, 11 ; 1 pl</i>. οἰσεῦμες, THCR. <i>Idyl. 15, 134. Ao.1, 3 pl</i>. ἤνεγκαν, THGN. <i>880 ;</i> EUR. <i>I.A. 800 ;</i> IS. <i>11, 18 Baiter-Sauppe ; sans augm</i>. ἔνεγκαν, Q. SM. <i>6, 595. Ao. épq. et ion</i>. ἔνεικα, OD. <i>4, 784, etc. ;</i> PD. <i>P. 9, 6 ;</i> ORPH. <i>Arg. 308 ; ou</i> ἤνεικα, OD. <i>18, 300 ;</i> THCR. <i>Idyl. 23, 16 ;</i> HDT. <i>2, 146 ; 3, 155. Autre ao</i>. *ὦσα, <i>d’où opt</i>. οἴσαιμι, NAZ. <i>Christ. pat. 990 ; impér</i>. οἶσε (<i>p</i>. οἶσον) OD. <i>22, 106 ;</i> AR. <i>Ran. 482 ; 3 sg</i>. οἰσέτω, IL. <i>19, 173 ; 3 pl</i>. οἰσόντων, ANTIM. <i>15 Kinkel ; inf</i>. οἴσειν, PD. <i>P. 4, 102 ; épq</i>. οἰσέμεναι, IL. <i>3, 420 ou</i> οἰσέμεν, OD. <i>3, 429. Ao.2, 1 sg</i>. SOPH. <i>O.C. 521, 964 ;</i> AR. <i>Ran. 1299, Lys. 944 ; opt. ion. 3 sg</i>. ἐνείκοι, OD. <i>21, 196 ; inf. épq</i>. ἐνεικέμεν, IL. <i>19, 194. — Pass. autre fut</i>. οἰσθήσομαι, ARSTT. <i>Mir. 3, 5, 13 ; Probl. 16, 3 ;</i> DÉM. <i>44, 45 Baiter-Sauppe. — Moy. prés. opt. dor</i>. φεροίμαν <span>[ᾱ]</span> ESCHL. <i>Eum. 266 ; f. au sens pass</i>. οἴσομαι, EUR. <i>Or. 440 ;</i> XÉN. <i>Œc. 18, 6. Ao.1 ion</i>. ἠνεικάμην, IL. <i>9, 127 ;</i> HDT. <i>1, 57 ; 2, 180 ; sbj. 3 pl</i>. ἐνείκωνται, HDT. <i>4, 67</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>er-, porter, <i>cf. lat</i>. ferō, <i>sscr</i>. bhárati ; R. *h₃eit-s-, aller chercher, <i>cf</i>. οἴσω, <i>lat</i>. ūtor ; RR. *h₁neḱ-, apporter, <i>cf</i>. ἐνεγκεῖν, ἐνήνοχα <i>et</i> *h₂neḱ-, atteindre, <i>cf</i>. διηνεκής, <i>lat</i>. nancīscor, <i>sscr</i>. náśati.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φερω - φέρω</font>\n<br><br>un verbe primaire (avec l'utilisation d'autres mots à certains temps seulement, comme oio (oy'-o)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n64 fois dans 58 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (13)</li>\n<li>Luc (4)</li>\n<li>Jean (17)</li>\n<li>Actes (10)</li>\n<li>Romains (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (5)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (5)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5343":"<h1>pheugo</h1>\n<p>Strong n° 5343 <i>Prononciation [fyoo'-go]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'enfuir, chercher la sécurité par la fuite</li>\n<li>métaph. s'enfuir (fuir ou éviter par la fuite) quelque chose d'odieux, de répugnant spéc. de vices</li>\n<li>être sauvé par la fuite, échapper et se mettre hors de danger</li>\n<li>poétiquement : partir au loin, s'évanouir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φεύγω</b> <span>(<i>f</i>. φεύξομαι, <i>ao.2</i> ἔφυγον <span>[ῠ]</span> <i>pf</i>. πέφευγα, <i>pass. ao</i>. ἐφεύχθην, <i>pf</i>. πέφυγμαι)</span><br><b>A  I</b> fuir, <i>càd. :</i><br><b>      1 <i>intr.</i></b> prendre la fuite, <i>abs. p. opp. à</i> διώκω, IL. <i>22, 157, etc. ; le lieu d’où l’on fuit avec ἀπό, ἐκ ou ὑπέκ et le gén. ou avec le gén. seul :</i> φ. ἀπό τινος, OD. <i>12, 120,</i> fuir loin de qqn ; ἀπὸ τῶν τειχῶν, XÉN. <i>Cyr. 7, 2, 4,</i> fuir des remparts ; ἐκ πολέμοιο, IL. <i>7, 118 ; 11, 589,</i> s’enfuir du combat ; ἐκ θανάτοιο, IL. <i>20, 350, etc</i>. échapper à la mort ; ἐκ κακῶν, SOPH. <i>Ant. 437 ; ou</i> ὑπὲκ κακοῦ, IL. <i>15, 700,</i> échapper aux maux, au malheur ; τῆς νόσου, SOPH. <i>Ph. 1044,</i> être délivré de la maladie ; <i>le n. du lieu où l’on fuit avec ἐς, πρός, ἐπί, etc. :</i> φ. ἐς πατρίδα, IL. <i>2, 140, etc</i>. fuir dans sa patrie ; ἐς νῆας, IL. <i>10, 366,</i> dans les vaisseaux ; ἐς τὰ τείχη, XÉN. <i>Hell. 4, 2, 23,</i> derrière les murs ; ἐπὶ Σάρδεων, XÉN. <i>Cyr. 7, 2, 1,</i> à Sardes ; πρὸς τὸ ὄρος, XÉN. <i>Hell. 3, 5, 11,</i> vers la montagne ; πρός τινα, PLUT. <i>M. 205</i> c, auprès de qqn ; ἐνθένδε ἐκεῖσε, PLAT. <i>Theæt. 176</i> a, de ce lieu dans cet autre ; πῆ ; IL. <i>8, 94,</i> par où ? πόσε ; IL. <i>16, 422 ;</i> OD. <i>6, 199,</i> dans quelle direction ? ποῖ χθονός ; ESCHL. <i>Suppl. 777, etc</i>. en quel lieu de la terre ? <i>le n. de lieu par où l’on fuit à l’acc. :</i> τὴν παρὰ θάλασσαν ὁδόν, HDT. <i>4, 12,</i> fuir par la route le long de la mer ; παντοῖα χωρία, XÉN. <i>Eq. 8, 10,</i> fuir par des lieux de toute sorte, <i>càd</i>. sans choisir son chemin ; φεύγειν ὑπό τινος, IL. <i>21, 554 ;</i> HDT. <i>4, 125 ; 5, 30,</i> fuir devant qqn (<i>litt</i>. par le fait de qqn) ; <i>pléonast. :</i> φυγῇ φεύγειν, PLAT. <i>Conv. 195</i> b, <i>etc</i>. prendre la fuite ; <i>ou avec l’acc</i>. φ. φυγὰς αἰσχράς, PLAT. <i>Leg. 706</i> c, fuir honteusement ; <i>au prés. et à l’impf. pour marquer l’intention de fuir, p. opp. aux compos. ἀποφεύγω, ἐκφεύγω, καταφεύγω, etc. qui marquent l’action de fuir comme accomplie :</i> βέλτερον ὃς φεύγων προφύγῃ κακὸν ἠὲ ἁλώῃ, IL. <i>14, 81,</i> il est dans une meilleure situation celui qui voulant fuir le malheur échappe que celui qui est pris ; <i>cf</i>. HDT. <i>4, 23 ; 5, 95 ;</i> EUR. <i>Ph. 1216 ;</i> AR. <i>Ach. 177 ;</i> PLAT. <i>Hipp. ma. 292</i> a, <i>p. ext</i>. courir, PD. <i>P. 9, 215, etc. ;</i><br><b>      2 <i>tr.</i></b> fuir, éviter, échapper à : τινά, HOM. ATT. à qqn ; τι, HOM. ATT. à qqe ch. (πόλεμον ἠδὲ θάλασσαν, OD. <i>1, 12,</i> aux périls de la guerre et de la mer ; χεῖράς τινος, IL. <i>21, 93,</i> aux mains de qqn, <i>etc.) ; avec un suj. de chose :</i> ἡνίοχον φύγον ἡνία, IL. <i>23, 465,</i> les rênes échappèrent au conducteur ; <i>cf</i>. IL. <i>8, 37 ; 11, 128 ; avec double acc. :</i> ποῖόν σε ἔπος φύγεν ἕρκος ὀδόντων ; IL. <i>4, 350, etc. ;</i> OD. <i>1, 64, etc</i>. quelle parole s’est échappée de la barrière de tes dents ? <i>abs</i>. τὸ φεῦγον, XÉN. <i>Eq. 10, 9,</i> la partie de la bride qui sort (de la bouche du cheval) ; <i>avec l’inf. :</i> διδάξαι ἔφυγες, PLAT. <i>Ap. 26</i> a, tu as refusé d’enseigner ; <i>cf</i>. HDT. <i>4, 76 ;</i> PLAT. <i>Ep. 316</i> b ;<br><b>   II</b> s’enfuir de sa patrie par suite d’une faute commise, IL. <i>9, 478 ;</i> OD. <i>13, 259 ; 15, 276, etc. ; d’où</i> être exilé, être banni : ὑπὸ τοῦ δήμου, XÉN. <i>Hell. 1, 1, 27,</i> être banni par le peuple ; ἐκ τῆς πατρίδος, XÉN. <i>An. 1, 3, 3 ; ou avec l’acc. :</i> πατρίδα, OD. <i>15, 228 ;</i> XÉN. <i>Cyr. 3, 1, 24 ;</i> τὴν ἑαυτοῦ, THC. <i>5, 26,</i> être banni de sa patrie ; <i>avec un rég. de temps ou de manière :</i> ἀειφυγίαν, PLAT. <i>Leg. 871</i> d, <i>881</i> b ; <i>ou</i> ἐν ἀειφυγίᾳ, PLAT. <i>Leg. 877</i> c, être exilé pour toujours ; <i>abs</i>. οἱ φεύγοντες, THC. <i>1, 24 ;</i> XÉN. <i>Ages. 7, 6, etc</i>. les exilés ; <i>p. suite,</i> vivre en exil, HDT. <i>6, 103 ;</i> ESCHL. <i>Ag. 1668, etc. ;</i><br><b>   III</b> <i>t. de droit,</i> être accusé <i>ou</i> défendeur : γραφήν, PLAT. <i>Euthyphr. 6</i> a, <i>etc., ou</i> δίκην, AR. <i>Nub. 167 ;</i> PLAT. <i>Ap. 19</i> c, <i>Euthyphr. 8</i> c, <i>etc</i>. être accusé <i>ou</i> défendeur dans un procès ; ὑπό τινος γραφὴν φεύγειν, XÉN. <i>Mem. 4, 4, 4 ; ou</i> δίκην φεύγειν, DÉM. <i>1184 fin,</i> être accusé par qqn ; φ. φόνου δίκην, ANT. <i>130, 17 ; ou simpl. avec le gén. du grief ;</i> φ. φόνου, LYS. <i>118, 42, etc</i>. être accusé de meurtre ; φ. ξενίας, AR. <i>Vesp. 718,</i> être accusé d’usurper les droits de citoyen (<i>litt</i>. d’être étranger) ; <i>avec une prép. :</i> φ. περί τινος, ANT. <i>140, 39 ; ou</i> ἐπί τινι, DÉM. <i>548, 29,</i> être accusé de qqe ch. ; <i>avec le gén. du grief et le gén. de la pers. qui accuse :</i> φ. ἀσεϐείας ὑπό τινος, PLAT. <i>Ap. 35</i> d, être accusé d’impiété par qqn ; <i>avec double gén. de cause :</i> τοσούτων χρημάτων φεύγων ἐπιτροπῆς, DÉM. <i>990, 15,</i> poursuivi pour une si grande somme dans la gestion de la tutelle ; <i>abs</i>. φεύγειν, être accusé : ὁ φεύγων, AR. <i>Vesp. 390 ; 889, 893 ;</i> PLAT. <i>Rsp. 405</i> b, l’accusé <i>ou</i> le défendeur, <i>p. opp. à</i> ὁ διώκων ;<br><b>B</b> <i>pass. part. pf</i>. πεφυγμένος, qui a fui, qui a échappé à : μοῖραν, IL. <i>6, 488 ;</i> ὄλεθρον, IL. <i>9, 455,</i> à la mort ; <i>cf</i>. IL. <i>22, 219 ; une seule fois avec le gén. :</i> ἀέθλων, OD. <i>1, 18,</i> qui a échappé aux épreuves, aux luttes.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. 3 pl. dor</i>. φεύγοντι, PD. <i>N. 9, 27 ; inf. épq</i>. φευγέμεναι, IL. <i>21, 13 ;</i> φευγέμεν, IL. <i>10, 147. Impf. itér</i>. φεύγεσκον, IL. <i>17, 461 ;</i> HDT. <i>4, 43. Fut. opt. 3 pl. épq</i>. φευξοίατο, ESCHL. <i>Pers. 369 ; fut. dor</i>. φευξοῦμαι, EUR. <i>Med. 338, 341, etc. ;</i> AR. <i>Pl. 447, etc. ;</i> PLAT. <i>Leg. 635 ; fut. réc</i>. φεύξω, SIB. <i>9, 283. Ao.2 itér. 3 sg</i>. φύγεσκε, OD. <i>17, 316 ; sbj. 3 sg</i>. φύγῃσι, IL. <i>5, 258 ; inf</i>. φυγέειν, IL. <i>14, 80 ;</i> HDT. <i>8, 76. Pf. part. épq. pl</i>. πεφυζότες, IL. <i>21, 6, 532</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>eug-, fuire ; <i>cf. lat</i>. fugiō, fuga.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φευγω - φεύγω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 31 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (5)</li>\n<li>Luc (3)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G5344":"<h1>Phelix</h1>\n<p>Strong n° 5344 <i>Prononciation [fay'-lix]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Félix (Angl. Felix) = « heureux »\n<ol><li>procurateur Romain de Judée nommé par l'empereur Claudius en 53 Ap J.C. Il a gouverné d'une manière cruelle, dans une période de troubles et de sédition. Paul fut présenté à Félix à Césarée. Il fut maintenu en prison pendant deux ans, dans l'espoir d'en extorquer de l'argent (<a class=\"ref\" data-r=\"ACT24.26-27\">Actes 24.26, 27</a>) L'épouse de Félix était Drusille, fille de Hérode Agrippa I.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φῆλιξ, ικος (ὁ)</b> = <i>lat</i>. Felix, <i>n. d’h. rom</i>. PLUT. <i>Syll. 34, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φηλιξ - Φῆλιξ</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (9)</li>\n</ul>\n</td></tr>\n</table>","G5345":"<h1>pheme</h1>\n<p>Strong n° 5345 <i>Prononciation [fay'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>renommée, bruit, rumeur, propos colporté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φήμη, ης (ἡ) :<br>   I</b> <i>propr</i>. ce qui est montré, <i>d’où :</i> divulgation, révélation par la parole <i>ou</i> par signe, <i>càd</i>. avertissement des dieux, augure, présage, <i>joint à</i> σῆμα, OD. <i>20, 100, 111 ; à</i> τέρας, HDT. <i>3, 153 ; à</i> ὀνείρατα, XÉN. <i>Eq. 9, 9 ; à</i> τοῦ ὀνείρατος, ARSTD. <i>t. 1, 332 ; à</i> ὄρνις, EL. <i>N.A. 16, 16 ; cf</i>. AR. <i>Av. 719 ; au plur. joint à</i> οὐρανίοις σημείοις καὶ οἰωνοῖς, XÉN. <i>Cyr. 8, 7, 3, etc. ; à</i> ἐνύπνια, XÉN. <i>Conv. 4, 48 ; particul</i>. oracle : φ. θεῶν, SOPH. <i>O.R. 86, etc</i>. oracle des dieux ; φ. μαντείας, PLAT. <i>Leg. 792</i> d, réponse de l’oracle ; <i>au plur</i>. φ. μαντικαί, SOPH. <i>O.R. 723,</i> avertissements de l’oracle ; <i>joint à</i> χρησμούς, ORPH. <i>H. 33, 9 ;</i><br><b>   II</b> <i>p. suite,</i> ce qui est annoncé par la parole, <i>d’où :</i><br><b>      1</b> bruit, rumeur, ESCHN. <i>1, 127 ; 2, 145 ;</i> PAUS. <i>1, 17, 1 ;</i> φ. ἐσέπτατο ἐς τὸ στρατόπεδον, HDT. <i>9, 100,</i> un bruit se répandit dans le camp ; τίν' ἔχων φήμην ἀγαθὴν ἥκεις ; AR. <i>Eq. 1320,</i> quelle bonne nouvelle viens-tu nous apporter ? <i>cf</i>. THC. <i>1, 11 ;</i> PLAT. <i>Leg. 672</i> b, <i>Ap. 18</i> c ;<br><b>      2</b> réputation, opinion sur le caractère d’une personne, HÉS. <i>O. 758 ;</i> ESCHN. <i>18, 7 ;</i> ISOCR. <i>97</i> e ; <i>particul. en b. part,</i> bonne réputation, HDT. <i>1, 31 ; joint à</i> τὴν εὐδοξίαν καὶ τοὺς ἐπαίνους, PLAT. <i>Leg. 109</i> c ; <i>au plur</i>. PD. <i>O. 7, 18, etc. ; en mauv. part,</i> mauvais renom, <i>p. opp. à</i> καλὴ δόξα, ISOCR. <i>11</i> c ; <i>au plur</i>. ESCHL. <i>Ch. 1045 ;</i><br><b>      3</b> tradition, légende, LYS. <i>190, 30 ; au plur</i>. EUR. <i>El. 701 ;</i> POL. <i>12, 3, 2 ;</i> PLUT. <i>M. 93</i> d, <i>etc. ;</i><br><b>      4</b> dicton, proverbe, ESCHL. <i>Suppl. 760 ;</i><br><b>      5</b> message, ESCHL. <i>Ch. 741 ;</i> SOPH. <i>El. 1155, etc. ;</i><br><b>      6</b> louange, éloge, <i>d’où</i> gloire, renommée, PD. <i>P. 2, 28 ;</i> ESCHL. <i>Suppl. 697, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. φάμα <span>[ᾱᾱ]</span> PD. <i>ll. cc. ;</i> ESCHL. <i>Suppl. 697</i>.<br><span><b>Étym</b>. φημί ; <i>cf. lat</i>. fāma.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φημη - φήμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5346":"<h1>phemi</h1>\n<p>Strong n° 5346 <i>Prononciation [fay-mee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire connaître sa pensée, déclarer</li>\n<li>dire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φημί, φῄς, φησί, φάμεν, φατέ, φασί</b>, (<i>toutes ces formes, à l’exception de φῄς, sont enclitiques ; impér. φαθί ou φάθι, sbj. φῶ, opt. φαίην, inf. φάναι, part</i>. φάς, φᾶσα, φάν ; <i>impf</i>. ἔφην, <i>f</i>. φήσω, <i>ao.1</i> ἔφησα) <span>[ᾰ <i>sauf dans</i> φασί, φάς <i>et</i> φᾶσα ; <i>p. except. φάναι avec</i> ᾱ, EUB. (ATH. <i>8</i> c)]</span><br><b>   I</b> rendre visible, <i>d’où</i> manifester sa pensée par la parole, <i>p. opp. à</i> κεύθειν, OD. <i>21, 194 ; à</i> κεκρυμμένον εἶναι, OD. <i>11, 443 ; d’où abs</i>. dire : τι, HOM. ATT. qqe ch. ; φ. πρός τινα, OD. <i>17, 584 ;</i> τινι, NT. <i>Matth. 13, 28,</i> dire à qqn ; κατά τινος, XÉN. <i>Ap. 25,</i> reprocher à qqn ; <i>avec une prop. inf</i>. IL. <i>3, 220 ; avec</i> ὅτι, PLAT. <i>Gorg. 87</i> d ; <i>ou</i> ὡς, XÉN. <i>Hell. 6, 3, 7, etc. ; avec double acc</i>. Κορινθίους τί φῶμεν ; XÉN. <i>Hell. 3, 5, 12,</i> que dire des Corinthiens ? <i>particul. :</i><br><b>      1</b> <i>en parl. d’un bruit public, d’une tradition, etc. :</i> φασί, IL. <i>5, 638 ;</i> OD. <i>6, 42 ;</i> ATT. ; <i>ou</i> φησί (<i>en s.-e. c. sujet</i> l’adversaire <i>ou</i> l’interlocuteur) DÉM. <i>650, 13 ;</i> PLUT. <i>M. 112</i> c, on dit ; <i>en ce sens souv. parenthét</i>. φασίν, ATT. dit-on, comme on dit ;<br><b>      2</b> <i>pour résumer les paroles de qqn :</i> ὣς ἔφη, ATT. il parla ainsi, <i>ou</i> pour les annoncer, <i>en ce cas φημί se place soit dev. son suj. :</i> ἔφην ἐγώ, ἔφη ὁ Σωκράτης, PLAT. je disais, dit Socrate ; <i>dans ce cas, qqf. séparé de son suj. par une parenthèse :</i> ἔφη, ὦ Σώκρατες, ὁ Λύσις, PLAT. <i>Lys. 213</i> d, Lysis dit : ô Socrate ; <i>cf</i>. XÉN. <i>Œc. 9, 14, etc. ; soit après son suj. :</i> ὁ Σωκράτης ἔφη, XÉN. <i>Conv. 3, 7 ; Hier. 1, 1,</i> Socrate dit ;<br><b>      3</b> <i>pléonast. joint à</i> λέγω : ἔφη λέγων, HDT. <i>3, 156 ;</i> ἔφησε λέγων, HDT. <i>6, 137, etc</i>. il dit ; ἔλεγεν φάς, HDT. <i>5, 36,</i> il disait ; <i>après un verbe signifiant dire :</i> ὁ Ἰσχόμαχος εἶπεν, ἀλλὰ παίζεις μὲν σύ γε, ἔφη, XÉN. <i>Œc. 17, 10,</i> alors Iskhomakhos : mais sans doute, dit-il, tu plaisantes ? <i>cf</i>. PLAT. <i>Charm. 164</i> e ;<br><b>   II</b> dire son avis, <i>d’où</i> avoir une opinion, penser, croire, <i>particul. dans les locut</i>. φημὶ δεῖν, AND. <i>3, 34 Baiter-Sauppe ;</i> φημὶ χρῆναι, ISOCR. <i>3, 48 Baiter-Sauppe,</i> je dis qu’il faut, <i>etc. ; en gén</i>. πῶς φῄς ; SOPH. <i>O.R. 746,</i> qu’en dis-tu ? qu’en penses-tu ? τί φημί ; SOPH. <i>O.R. 1471 ;</i> τί φῄς ; SOPH. <i>O.R. 655, Ph. 803 ;</i> EUR. <i>Hel. 706,</i> que dire ? <i>càd</i>. que croire, que penser ? φαίης κε, IL. <i>3, 220,</i> tu dirais, on dirait ;<br><b>   III</b> dire, prétendre, se vanter de : φῆ γὰρ ὅγ' αἱρήσειν Πριάμου πόλιν, IL. <i>2, 37,</i> car il disait qu’il prendrait la ville de Priam ;<br><b>   IV</b> dire oui, HDT. <i>8, 88 ;</i> PLAT. <i>Gorg. 562</i> c, <i>etc. ;</i> καί φημι κἀπόφημι, SOPH. <i>O.C. 317,</i> je dis oui et je dis non ; φάναι τε καὶ ἀπαρνεῖσθαι, PLAT. <i>Theæt. 165</i> a, dire oui et non ; <i>dans les réponses, φημί équivaut à notre</i> « oui », « oui certes », PLAT. <i>Phædr. 270</i> c, <i>etc. ; p. suite :</i><br><b>      1</b> affirmer, déclarer : φονέα σε φημὶ τἀνδρὸς κυρεῖν, SOPH. <i>O.R. 362,</i> je déclare que c’est toi le meurtrier de l’homme ;<br><b>      2</b> avouer, convenir de : φῂς ἢ καταρνεῖ μὴ δεδρακέναι τόδε ; SOPH. <i>Ant. 442,</i> reconnais-tu oui ou non avoir fait cela ? <i>p. suite, φημί précédé d’une négation signifie</i> dire non, nier : ὁδ' οὐκ ἔφη, PLAT. <i>Phæd. 117</i> e, il dit non ; οὐ φήσ' ἐάσειν, SOPH. <i>Aj. 1326,</i> il nie devoir permettre, il dit qu’il ne permettra pas ; <i>dans les réponses οὔ φημι équivaut à notre</i> « non », AR. <i>Ran. 1165 ; ou à</i> défendre, SOPH. <i>Aj. 1107 ;</i><br><b><i>Moy.</i></b> (<i>seul. aux temps suiv. : prés. impér</i>. φάο, <i>inf</i>. φάσθαι, <i>part</i>. φάμενος ; <i>impf</i>. ἐφάμην, <i>f</i>. φήσομαι, <i>pf. impér. 3 sg</i>. πεφάσθω, <i>part</i>. πεφασμένος) :<br><b>      1</b> dire : μῦθον, OD. <i>1, 142 ;</i> ἔπος, OD. <i>21, 248,</i> une parole ; ἀγγελίην, IL. <i>18, 17,</i> annoncer une nouvelle ; <i>cf</i>. IL. <i>2, 81 ; particul</i>. dire oui, PLUT. <i>M. 229</i> d ;<br><b>      2</b> dire son avis, <i>d’où</i> croire, penser : ἴσον ἐμοὶ φάσθαι, IL. <i>15, 167,</i> se dire, se croire mon égal.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> <i>p. exc. dans</i> φάναι, EUB. (ATH. <i>8</i> c) ; <i>act. prés. ind. dor</i>. φαμί <span>[ᾱ]</span> PD. <i>P. 2, 64 ;</i> ESCHL. <i>Eum. 553 ;</i> SOPH. <i>Tr. 125 ;</i> THCR. <i>Idyl. 8, 7 ; 2 sg</i>. φῇσθα, IL. <i>21, 186 ;</i> OD. <i>14, 149 ; 3 sg</i>. φή, ANACR. <i>40 ; dor</i>. φατί, AR. <i>Ach. 771 ;</i> THCR. <i>Idyl. 1, 51 ; éol</i>. φαῖσι, SAPPH. <i>66 Bgk ; 3 pl. dor</i>. φαντί, PD. <i>P. 1, 52 ;</i> THCR. <i>Idyl. 2, 45. Impér</i>. φάθι <i>ou</i> φαθί <span>[ᾰ]</span> AR. <i>Eq. 23 ;</i> PLAT. <i>Prot. 349, Rsp. 475. Sbj. 3 sg</i>. φήῃ, OD. <i>11, 128 et</i> φῇσιν, OD. <i>1, 168 ; inf. poét</i>. φάμεν, PD. <i>N. 8, 19 ; au part. dans les inscr. att. du 5<sup>e</sup> siècle av. J.C. on trouve au lieu du part. de φημί, le part. de</i> φάσκω (<i>v. ce mot). Impf. 2 sg</i>. ἔφησθα, IL. <i>1, 397 ; 16, 830 ;</i> OD. <i>23, 71 ;</i> AR. <i>Lys. 132 ;</i> XÉN. <i>An. 1, 6, 7 ;</i> PLAT. <i>Rsp. 501</i> c ; ESCHN. <i>3, 164 ;</i> DÉM. <i>18, 70 ;</i> LUC. <i>Gall. 24 ; 3 sg. dor</i>. ἔφα, PD. <i>P. 4, 278 ;</i> ESCHL. <i>Ag. 369 ;</i> THCR. <i>Idyl. 7, 43 ; ou</i> φᾶ, PD. <i>I. 2, 11 ;</i> THCR. <i>Idyl. 24, 100 ; 3 pl</i>. ἔφαν, IL. <i>13, 89 ;</i> OD. <i>18, 75 ; ou</i> φάν, IL. <i>6, 108 ;</i> OD. <i>18, 342 ;</i> PD. <i>fr. 228. Fut. dor</i>. φασῶ <span>[ᾱ]</span> AR. <i>Ach. 739 ;</i> THCR. <i>Idyl. 11, 70 ; 2 sg</i>. φασεῖς, THCR. <i>Idyl. 15, 79, ou</i> φάσω, <i>3 sg</i>. φάσει, PD. <i>N. 7, 102 ; 3 pl</i>. φάσουσι, A. PL. <i>4, 182. Ao. dor</i>. ἔφασα <span>[φᾱ]</span>, <i>3 sg</i>. φᾶσε, PD. <i>N. 1, 66. Pf. pass. 3 sg. épq</i>. πέφαται <span>[ᾰ]</span> A. RH. <i>2, 500 ; impér. 3 sg</i>. πεφάσθω, PLAT. <i>Tim. 72</i> e. <i>Moy. prés. ind. seul. 2 pl</i>. φάσθε, OD. <i>6, 200 ; 10, 562 ; impér. seul. 2 sg</i>. φάο, OD. <i>16, 168 ; 18, 171 ; 3 sg</i>. φάσθω, OD. <i>20, 100 ; inf</i>. φάσθαι, IL. <i>9, 100 ;</i> PD. <i>N. 4, 92 ;</i> ESCHL. <i>Pers. 687 ;</i> XÉNOPHAN. <i>6, 3 Bgk ; part</i>. φάμενος, IL. <i>5, 290 ; 22, 247 ;</i> PD. <i>I. 6, (5), 72 ;</i> HDT. <i>1, 176 ;</i> HPC. <i>6, 342 ;</i> ESCHL. <i>Ch. 314 ;</i> XÉN. <i>Hell. 1, 6, 3 ;</i> PLAT. <i>2 Alc. 142 ;</i> ARSTT. <i>Metaph. 13, 3, 8 ; Impf. dor</i>. ἐφάμαν <span>[μᾱ]</span> THCR. <i>Idyl. 2, 102 ; 3 sg. épq</i>. φάτο, HOM. <i>Fut. dor</i>. φάσομαι <span>[ᾱ]</span> PD. <i>N. 9, 43</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *b<sup>h</sup>eh₂-, dire ; <i>cf. lat</i>. fātur.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φημι - φημί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n58 fois dans 57 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (15)</li>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>Jean (2)</li>\n<li>Actes (27)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5347":"<h1>Phestos</h1>\n<p>Strong n° 5347 <i>Prononciation [face'-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Festus (Porcius) = « en fête, joyeux »\n<ol><li>successeur de Félix comme procurateur de Judée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φηστος - Φῆστος</font>\n<br><br>dérivé du Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (13)</li>\n</ul>\n</td></tr>\n</table>","G5348":"<h1>phthano</h1>\n<p>Strong n° 5348 <i>Prononciation [fthan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir avant, précéder, anticiper</li>\n<li>venir à, arriver à, parvenir à</li>\n<li>atteindre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθάνω</b> <span>(<i>f</i>. φθήσομαι, <i>rar</i>. φθάσω ; <i>ao</i>. ἔφθασα ; <i>ao.2</i> ἔφθην, <i>d’où sbj</i>. φθῶ, <i>opt</i>. φθαίην, <i>inf</i>. φθῆναι, <i>part</i>. φθάς ; <i>pf</i>. ἔφθακα <span>[θᾰ]</span>)</span> <span>[<i>au prés</i>. ᾱ <i>épq.,</i> ᾰ <i>att</i>.]</span><br><b>   I. 1</b> arriver le premier, <i>p. opp. à</i> ὑστερέω, EUR. <i>Ph. 975 ; à</i> ὑστερίζω, XÉN. <i>An. 6, 1, 18 ; joint à</i> πρῶτος, XÉN. <i>An. 3, 4, 20, etc. ; à</i> πρῶτον, ES. <i>218 Halm ;</i> ὁ φθάσας, ESCHL. <i>Pers. 752,</i> le premier arrivé ; τὰ φθάσαντα, DÉM. <i>1128 argum</i>. ce qu’on a dit d’abord <i>ou</i> précédemment ; ὁ φθάνων, ἡ φθάνουσα, DÉM. <i>Phil. 4 argum</i>. le précédent (discours), la précédente (harangue), <i>etc. ;</i> τὸ φθάνον, EL. <i>V.H. 14, 16,</i> le temps passé, <i>etc. ; avec une prép. :</i> φθ. εἰς πόλιν, XÉN. <i>Cyr. 5, 4, 9,</i> arriver le premier dans la ville ; <i>cf</i>. THC. <i>8, 100 ;</i> φθ. ἕως τοῦ οὐρανοῦ, SPT. <i>Dan. 4, 8,</i> arriver le premier jusqu’au ciel ; ἐπί τινα, NT. <i>Matth. 12, 28 ;</i> LUC. <i>11, 20, etc</i>. arriver le premier auprès de qqn ; <i>d’où simpl</i>. φθ. εἰς, arriver jusqu’à, atteindre, NT. <i>Rom. 9, 31 ;</i> PHIL. <i>3, 16 ;</i> PLUT. <i>M. 338</i> a ;<br><b>      2</b> prévenir, devancer : φθ. τινά, IL. <i>11, 451 ; 21, 262 ;</i> HÉS. <i>O. 556, 572 ;</i> HDT. <i>7, 161, etc. ;</i> XÉN. <i>An. 5, 6, 9, etc</i>. devancer qqn ; <i>avec un rég. de chose :</i> φθ. τι, HDT. <i>7, 188 ;</i> DÉM. <i>526, 18, etc</i>. prévenir <i>ou</i> devancer qqe ch. (la mauvaise saison, un raisonnement, <i>etc</i>.) ; φθ. τι, XÉN. <i>An. 6, 1, 18,</i> terminer qqe ch. plus vite que d’ordinaire ; <i>avec un suj. de chose :</i> φθάνει ἡμέρα γενομένη αὐτὸν πορευόμενον, XÉN. <i>An. 3, 4, 49,</i> le jour étant survenu le devance dans sa marche ; <i>au pass</i>. ὑπό τινος φθάνεσθαι, ANTH. <i>9, 278,</i> être devancé par qqn ; <i>rar. et poét. avec le gén. :</i> φθάνειν τινός, IL. <i>11, 51,</i> devancer qqn ; <i>avec double rég</i>. φθ. τινά τι, ATT. devancer qqn en qqe ch. ; <i>avec un part. :</i> ἀλλ' ἄρα μιν φθῆ Τηλέμαχος κατόπισθε βαλών, OD. <i>22, 91,</i> mais Télémaque le prévint l’ayant frappé le premier par derrière ; φθῆναι ἀπικόμενοι, HDT. <i>4, 136,</i> (voulant) arriver avant ; <i>avec un part. fut. :</i> ἡμιλλῶντο ὅπως φθάσειαν βοηθήσοντες, XÉN. <i>Hell. 7, 2, 14,</i> ils s’efforçaient à l’envi d’arriver les premiers pour porter secours ; <i>avec un part. prés. :</i> φθ. εὐεργετῶν, XÉN. <i>Mem. 2, 3, 14,</i> devancer (des amis) pour rendre service ; <i>avec un part. pass. :</i> ἦ κε πολὺ φθαίη πόλις ἁλοῦσα, IL. <i>13, 815,</i> la ville serait prise bien avant ; ἔφθη κατακωλυθείς, XÉN. <i>Hell. 1, 6, 17,</i> il fut empêché d’agir par l’ennemi qui l’avait devancé ; <i>cf</i>. IL. <i>16, 861 ;</i> HDT. <i>6, 108 ;</i> THC. <i>3, 83, etc. ; en ce sens qqf. accompagné de</i> πρότερον ἤ, HDT. <i>6, 91 ;</i> LUC. <i>Pisc. 29 ; de</i> πρίν, IL. <i>16, 322 ;</i> XÉN. <i>Cyr. 3, 2, 4, etc. ; de</i> πρὶν ἤ, HDT. <i>9, 70 ; de ἤ seul,</i> IL. <i>23, 444 ;</i> OD. <i>11, 58 ;</i> HDT. <i>6, 108 ;</i> THCR. <i>Idyl. 2, 114 ; rar. avec un inf. :</i> φθαίης ἔτι εἰς ἐκκλησίαν ἐλθεῖν, AR. <i>Eq. 942,</i> tu te hâtes encore pour arriver à l’assemblée ; <i>cf</i>. THC. <i>1, 33 ;</i> AR. <i>Nub. 1384 ; au part. avec un verbe à un mode personnel :</i> φθάνοντες δῃοῦμεν, XÉN. <i>Cyr. 3, 3, 18,</i> nous ravageons les premiers le territoire ; φθάσας προσπεσοῦμαι, THC. <i>5, 9,</i> je tomberai dessus, <i>càd</i>. je l’attaquerai le premier ; οὐκ ἄλλος φθὰς ἐμεῦ κατήγορος ἔσται, HDT. <i>3, 71,</i> aucun autre ne me devancera pour être son accusateur ; <i>cf</i>. XÉN. <i>Cyr. 1, 5, 3, etc. ;</i> οὐ φθάνω <i>suivi de καί ou εὐθύς équivaut à</i> « n’être pas plutôt… que » : οὐ φθάνει ἐξαγόμενος καὶ εὐθὺς ὅμοιός ἐστι τοῖς ἀκαθάρτοις, XÉN. <i>Eq. 5, 10,</i> le cheval n’est pas plutôt mené dehors, qu’aussitôt il est semblable à ceux qui n’ont pas été nettoyés ; οὐκ ἔφθημεν ἐλθόντες καὶ νόσοις ἐλήφθημεν, ISOCR. <i>588</i> e, nous ne fûmes pas plutôt arrivés que nous fûmes pris par les maladies ; οἱ Λακεδαιμόνιοι οὐκ ἔφθησαν πυθόμενοι τὸν πόλεμον καὶ… ἧκον, ISOCR. <i>58</i> b, les Lacédémoniens n’eurent pas plutôt connaissance de la guerre qu’ils arrivèrent ; <i>cf</i>. ISOCR. <i>92</i> e, <i>179</i> a, <i>199</i> d ; DÉM. <i>1073, 20, etc. ;</i><br><b>      3</b> οὐ φθάνω <i>non suivi de καί ou εὐθύς, et dans une propos. non interrog., équivaut d’ord. à</i> « ne pas manquer de » <i>avec un inf., ou plus souv. avec un part. (prés. chez les Att., ao. chez les écriv. postér</i>.) : οὐκ ἂν φθάνοιμι λέγων, PLAT. <i>Conv. 785</i> f, <i>etc. ; ou abs</i>. οὐκ ἂν φθάνοιμι, PLAT. <i>Conv. 214</i> e, je ne saurais manquer de dire, il faut que je dise ; οὐκ ἂν φθάνοι κατακοπτόμενος, DÉM. <i>782, 17,</i> il ne saurait manquer d’être tué ; <i>cf. les écriv. att. en gén</i>. PLAT. <i>Euthyd. 272</i> d, <i>Phæd. 100</i> c, <i>etc. ; postér. avec un part. ao</i>. LUC. <i>Tox. 2, etc. ;</i><br><b>   II</b> <i>p. ext</i>. se hâter : οὐκ ἂν φθάνοις λέγων ; XÉN. <i>Mem. 2, 3, 11, etc</i>. ne voudrais-tu pas me dire d’abord ? οὐκ ἂν φθάνοιτ' ἀκολουθοῦντες, XÉN. <i>Mem. 3, 11, 1,</i> vous ne vous hâterez pas trop en me suivant, suivez-moi sans retard ; <i>au part. ao. avec un impér. :</i> λέγε φθάσας, ATT. dis vite ; τρέχε φθάσας, ATT. cours vite ; <i>avec un autre part. :</i> φθάσας ἁρπάσας, HDT. <i>6, 65,</i> ayant devancé qqn pour enlever (une femme) ;<br><b><i>Moy.</i></b> (<i>part. ao</i>. φθάμενος) devancer, prévenir : ὅς μ' ἔϐαλε φθάμενος, IL. <i>5, 119,</i> qui m’a frappé le premier.<br><span><b><span class=\"arrow\"></span></b> φθάνω <span>[ᾱ]</span> IL. <i>9, 506 ; 21, 262 ; fut</i>. φθάσω <span>[ᾰ]</span> HPC. <i>491, 28 ;</i> XÉN. <i>Cyr. 5, 4, 38 ; 7, 1, 19 ; ao. dor</i>. ἔφθαξα (<i>var</i>. ἔφθασσα) THCR. <i>Idyl. 2, 115. Ao.2 ind. 3 pl. poét</i>. φθάν, IL. <i>11, 51 ; sbj. 3 sg. épq</i>. φθῇσι, IL. <i>23, 805, ou</i> φθήῃ, IL. <i>16, 861 ; 1 pl</i>. φθέωμεν, OD. <i>16, 383 ; 3 pl</i>. φθέωσι, OD. <i>24, 437 ; part. ion</i>. φθάς, HDT. <i>3, 71 ; 9, 46. Pf. réc</i>. πέφθακα <span>[θᾰ]</span> Ps.-CALLISTH. <i>2, 10 ; ao. pass</i>. ἐφθάσθην, DH. <i>6, 25, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *d<sup>h</sup>g<sup>wh</sup>h₂-, s’approcher.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθανω - φθάνω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G5349":"<h1>phthartos</h1>\n<p>Strong n° 5349 <i>Prononciation [fthar-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>corruptible, périssable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθαρτός, ή, όν</b>, corruptible, ARSTT. <i>An. post. 1, 8, 2 ; 1, 24, 5 ; Metaph. 1, 9, 8 ;</i> PLUT. <i>M. 106</i> d, <i>717</i> e ; SEXT. <i>M. 9, 141</i>.<br><span><b>Étym</b>. <i>vb. de</i> φθείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθαρτος - φθαρτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5350":"<h1>phtheggomai</h1>\n<p>Strong n° 5350 <i>Prononciation [ftheng'-gom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>émettre un son, un bruit ou un cri\n<ol type=\"a\">\n<li>toute sorte de son ou voix, que ce soit humain, animal ou d'une chose telle que le tonnerre, un instrument de musique...</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθέγγομαι</b> <span>(<i>f</i>. φθέγξομαι, <i>ao</i>. ἐφθεγξάμην, <i>pf</i>. ἔφθεγμαι, <i>2 sg</i>. ἔφθεγξαι, <i>3 sg</i>. ἔφθεγκται, <i>etc</i>.)</span> faire entendre un son, <i>particul. :</i><br><b>   I</b> <i>en parl. de la voix humaine (seul. en ce sens dans Hom</i>.) :<br><b>      1</b> parler, <i>abs</i>. IL. <i>21, 341, etc. ;</i> φθ. φωνῇ ἀνθρωπεΐῃ, HDT. <i>2, 57,</i> parler d’une voix humaine ; διὰ στόματος, PLAT. <i>Soph. 238</i> b ; διὰ στόμα, PLAT. <i>Pol. 462</i> c, laisser échapper un son par la bouche ; <i>joint à</i> αὐδάω, OD. <i>9, 497 ; à</i> λέγω, PLAT. <i>Leg. 663</i> c, <i>etc. ; au part. joint à un autre verbe :</i> φθεγξάμενος προσέειπε, OD. <i>21, 192, etc</i>. ayant pris la parole il dit ; <i>avec un acc</i>. φθ. φωνήν, BATR. <i>272 ;</i> PLAT. <i>Ep. 321</i> c, faire entendre un son ; ἔπος, HDT. <i>7, 103,</i> une parole ; ἔπη, PLAT. <i>Phædr. 241</i> c ; λόγους, EUR. <i>Med. 1307,</i> des paroles ; ὀδυρμοὺς καὶ γόους, ESCHL. <i>Pr. 34,</i> des plaintes et des gémissements ; ἀράς, EUR. <i>Ph. 478,</i> des imprécations ; φθ. τἀληθῆ, PLAT. <i>Phil. 49</i> b, dire la vérité ; <i>avec le rég. de la pers. à qui l’on parle :</i> φθ. πρός τινα, PLAT. <i>Ion 534</i> d, <i>etc. ;</i> εἴς τινα, EUR. <i>Ph. 475 ;</i> τινι, PLUT. <i>Crass. 27,</i> parler à qqn ; <i>au pass</i>. τὸ φθεγγόμενον, HDT. <i>8, 65,</i> la voix entendue ;<br><b>      2</b> <i>particul</i>. parler d’une voix faible : ὀλίγῃ ὀπί, OD. <i>14, 492,</i> parler d’une voix faible ; τυτθόν, IL. <i>24, 170,</i> faire entendre un faible son ; μικρὸν καὶ ἰσχνὸν καὶ γυναικῶδες, LUC. <i>Nigr. 11,</i> parler d’une voix petite et grêle comme une femme ; <i>cf</i>. PLAT. <i>Rsp. 368</i> c ; ISOCR. <i>Antid. § 205 ;</i><br><b>      3</b> <i>au contr</i>. parler fort : καλὸν καὶ μέγα, DÉM. <i>408, 19,</i> parler d’une belle et forte voix ; μεῖζον, PLAT. <i>Leg. 817</i> c, parler plus fort, <i>en parl. d’acteurs ;</i> μετὰ βοῆς, PLAT. <i>Leg. 791</i> e, prononcer des sons avec des cris, <i>en parl. des petits enfants ; joint à</i> βοῶντα, PLAT. <i>Euthyd. 300</i> b ; <i>particul. en parl. des cris de</i> « qui vive ? » <i>dans un camp,</i> IL. <i>10, 67 ; d’un cri de guerre,</i> XÉN. <i>An. 1, 8, 18 ; 4, 5, 18, etc. ; de la diction du chœur,</i> XÉN. <i>Œc. 8, 3 ; avec un acc</i>. φθ. βοήν, EUR. <i>I.T. 1385,</i> pousser un cri ;<br><b>      4</b> <i>p. suite,</i> appeler par son nom, nommer, <i>acc</i>. PLAT. <i>Rsp. 527</i> a, <i>Phil. 25</i> c, <i>34</i> a ; τινι τὸ ὄνομα φθ. λόγον, PLAT. <i>Soph. 262</i> c, donner à qqe ch. le nom de λόγος ; φθ. γιγνόμενα, PLAT. <i>Theæt. 157</i> b, parler des choses comme se produisant ; <i>joint à</i> καλεῖν, OD. <i>10, 229, 255 ; 12, 249 ;</i><br><b>      5</b> <i>avec un acc. de pers</i>. chanter, louer, célébrer, PD. <i>O. 1, 59 ;</i><br><b>   II</b> <i>en parl. d’animaux,</i> faire entendre un cri ; <i>en parl. du hennissement des chevaux,</i> HDT. <i>3, 84, 85 ; du cri de l’aigle,</i> XÉN. <i>An. 6, 1, 23 ; du chant du coq,</i> AR. <i>Eccl. 191 ; du croassement du corbeau,</i> TH. <i>Sign. 1, 16 ; en parl. des oiseaux en gén</i>. ARSTT. <i>H.A. 9, 28, 2, etc. ; du pépiement des petits oiseaux,</i> EL. <i>N.A. 6, 19 ; de la crépitation des vers,</i> TH. <i>C.P. 5, 10, 5 ; du claquement des poissons,</i> ARSTT. <i>fr. 284, etc. ;</i><br><b>   III</b> <i>en parl. de choses,</i> faire entendre un son (bruit du tonnerre, XÉN. <i>Cyr. 7, 1, 3 ;</i> son de la trompette, XÉN. <i>An. 4, 2, 7, etc. ;</i> de la flûte, XÉN. <i>Conv. 6, 3 ;</i> de la lyre, ARSTT. <i>Metaph. 4, 12, 7 ;</i> porte qui craque, AR. <i>Pl. 1099 ;</i> bruit d’applaudissements, ANTH. <i>9, 505, etc.) ; en parl. du son d’une voyelle,</i> PLAT. <i>Crat. 394</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. 2 sg. ion</i>. φθέγγεο, IL. <i>10, 67. Fut. dor</i>. φθεγξοῦμαι, THCR. <i>Idyl. 15, 99. Ao. 2 sg. ion</i>. ἐφθέγξαο, HDT. <i>7, 103 ; 1 pl</i>. ἐφθεγξάμεσθα, AR. <i>Ran. 248. Pf. 3 sg</i>. ἐφθέγκται, <i>au sens act</i>. ARSTT. <i>An. post. 1, 10, 8 ; au sens pass</i>. ARSTT. <i>Cæl. 1, 9, 15</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθεγγομαι - φθέγγομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5351":"<h1>phtheiro</h1>\n<p>Strong n° 5351 <i>Prononciation [fthi'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>corrompre, détruire\n<ol type=\"a\">\n<li>dans l'opinion des Juifs, le temple était corrompu ou « détruit » lorsque quelqu'un le souillait, ou, au plus haut degré, lorsque une chose y était endommagée, ou lorsque les gardiens négligeaient leurs devoirs</li>\n<li>écarter une église chrétienne de cet état de connaissance et de sainteté dans lequel il est souhaitable qu'elle demeure</li>\n<li>être détruit, périr</li>\n<li>dans un sens moral : corrompre, dépraver</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθείρω</b> <span>(<i>f</i>. φθερῶ, <i>ao</i>. ἔφθειρα, <i>pf</i>. ἔφθαρκα, <i>pf.2</i> ἔφθορα, <i>d’ord. intr., qqf. trans. chez les poètes att. ; pass. f. 2</i> φθαρήσομαι <span>[ᾰ]</span> <i>ao.2</i> ἐφθάρην <span>[ᾰ]</span> <i>pf</i>. ἔφθαρμαι)</span><br><b>   I</b> faire périr, <i>d’où :</i><br><b>      1</b> détruire : ναύτας, HÉS. <i>Th. 876,</i> des matelots ; στρατόν, ESCHL. <i>Pers. 244,</i> une armée ; <i>au pass</i>. périr (de maladie, <i>etc</i>.) THC. <i>3, 13 ; cf</i>. ESCHL. <i>Pers. 272, 283, etc. ; avec un rég. de chose,</i> dévaster un pays, HDT. <i>1, 76 ;</i> XÉN. <i>Hell. 7, 2, 11 ; An. 4, 7, 20, etc. ;</i> détruire des vaisseaux, THC. <i>2, 91 ;</i> ruiner une ville, PLAT. <i>Leg. 958</i> c, <i>etc. ; fig</i>. ruiner les affaires d’un État, THC. <i>7, 48 ;</i> détruire les lois, SOPH. <i>Aj. 1344 ;</i> PLAT. <i>Leg. 958</i> c, <i>etc. ; au pass. dans des formules de malédiction :</i> φθείρου, AR. <i>Ach. 460, etc</i>. va au diable ! φθείρεσθε, IL. <i>21, 128,</i> allez à la malheure ! <i>de même</i> φθείρεσθαι εἴς τι, PLUT. <i>M. 875</i> b, tomber dans une situation funeste, aller à sa perte ; φθ. πρός τινα, DÉM. <i>560, 10,</i> s’attacher pour sa perte à qqn ; εἴς τι, TÉLÈS (STOB. <i>509, 9</i>) s’attacher pour sa perte à qqe ch. ;<br><b>      2</b> laisser se gâter <i>ou</i> se perdre, amener la perte <i>ou</i> la ruine de : μῆλα, OD. <i>17, 246,</i> de troupeaux (par sa négligence) ;<br><b>   II</b> gâter, <i>d’où :</i><br><b>      1</b> corrompre, séduire (par des présents) <i>acc</i>. DS. <i>4, 73 ; au pass</i>. PLUT. <i>Arat. 40 ;</i> au propre, <i>en parl. d’une jeune fille,</i> EUR. <i>fr. 489 ;</i><br><b>      2</b> altérer par un mélange, <i>en parl. de teinture, de couleurs,</i> ESCHL. <i>Ch. 1013 ;</i> PLUT. <i>M. 393</i> d ;<br><b>      3</b> troubler (les intestins) <i>au pass</i>. HPC. <i>V. med. 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. réc</i>. ἔφθερσα, LYC. <i>1402. Pass. f. dor</i>. φθαρησοῦμαι, T. LOCR. <i>94. Ao.2, 3 pl</i>. ἔφθαρεν (<i>p</i>. -ησαν) PD. <i>P. 3, 36. Pf. 3 pl</i>. ἐφθάραται, THC. <i>3, 13. Moy. fut. au sens pass</i>. φθεροῦμαι, SOPH. <i>O.R. 272 ;</i> EUR. <i>Andr. 708 ;</i> THC. <i>7, 48. Fut. 2</i> φθαροῦμαι, ORIB. <i>8, 23</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *d<sup>h</sup>g<sup>wh</sup>er-, s’écouler, disparaître.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθειρω - φθείρω</font>\n<br><br>probablement renforcement de phthio (languir ou gaspiller)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5352":"<h1>phthinoporinos</h1>\n<p>Strong n° 5352 <i>Prononciation [fthin-op-o-ree-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>arbres d'automne\n<ol type=\"a\">\n<li>des arbres tels qu'ils le sont à la fin de l'automne, secs, sans feuilles, et sans fruits</li>\n<li>métaph. de infructueux, hommes sans valeur, stériles</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθινοπωρινός, ή, όν</b> <span>[ῐῐ]</span> de la fin de l’automne, HPC. <i>Aph. 1245 ;</i> ARSTT. <i>fr. 232 ; H.A. 5, 12, 3, etc</i>.<br><span><b>Étym</b>. φθινόπωρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθινοπωρινος - φθινοπωρινός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G5353":"<h1>phthoggos</h1>\n<p>Strong n° 5353 <i>Prononciation [ftong'-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>son musical, qu'il soit vocal ou instrumental</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθόγγος, ου (ὁ) :<br>      1</b> bruit, son différent de la voix (φωνή) PLAT. <i>Phil. 18</i> b, <i>etc. ; en parl. de sons de musique,</i> EUR. <i>El. 716 ; de la lyre,</i> PLAT. <i>Leg. 812</i> d ; <i>en parl. du bruit du vent,</i> SIM. <i>fr. 44, 11 ;</i><br><b>      2</b> son articulé, <i>au plur. joint à</i> συλλαϐάς, PLAT. <i>Crat. 389</i> b ; <i>d’où</i> voix, parole, IL. <i>5, 234, etc. ;</i> OD. <i>12, 41, 159 ; 18, 199 ; dans les Trag</i>. ESCHL. <i>Sept. 73, etc. ; p. anal. en parl. des cris ou du chant des oiseaux,</i> THGN. <i>864 ;</i> SOPH. <i>Ant. 1001 ;</i> EUR. <i>I.A. 9 ; du cri d’un chien,</i> PLAT. <i>Pol. 397</i> a, <i>etc</i>.<br><span><b>Étym</b>. φθέγγομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθογγος - φθόγγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5354":"<h1>phthoneo</h1>\n<p>Strong n° 5354 <i>Prononciation [fthon-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>envier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθονέω-ῶ</b> <span>(<i>f</i>. -ήσω, <i>ao</i>. ἐφθόνησα, <i>pf</i>. πεφθόνηκα)</span><br><b>      1</b> porter envie, être jaloux, jalouser, <i>abs</i>. IL. <i>4, 55, 56 ;</i> XÉN. <i>Mem. 3, 9, 8 ;</i> PLAT. <i>Phil. 48</i> b, <i>etc. ;</i> τινι, HÉS. <i>O. 25 ;</i> EUR. <i>Ion 1025, etc</i>. porter envie à qqn, être jaloux de qqn, <i>etc. ;</i> τινος, OD. <i>18, 18 ;</i> THC. <i>3, 43 ;</i> PLAT. <i>Menex. 238</i> a, <i>etc</i>. être jaloux de qqe ch., envier qqe ch. ; <i>avec une prép. :</i> φθ. ἐπί τινι, XÉN. <i>Cyr. 2, 4, 10 ;</i> ISOCR. <i>7</i> c ; DÉM. <i>503, 13,</i> être jaloux de qqe ch. ; <i>avec double rég</i>. φθ. τινί τινος, XÉN. <i>Cyr. 8, 4, 16 ;</i> PLAT. <i>Euthyd. 297</i> b, <i>etc</i>. envier qqe ch. à qqn ; <i>avec une conj</i>. ὅτι, XÉN. <i>Cyr. 3, 1, 39 ;</i> LYS. <i>150, 38 ; 168, 21 ;</i> εἰ, HDT. <i>3, 146 ;</i> EUR. <i>Ion 1302 ;</i> ἐάν, PLAT. <i>Rsp. 528</i> a, <i>579</i> d, être jaloux de ce que ; <i>au pass</i>. être envié, jalousé, HDT. <i>3, 52 ;</i> devenir odieux, EUR. <i>El. 30 ;</i> XÉN. <i>Cyr. 8, 2, 19, etc. ;</i> τινος, PLUT. <i>M. 772</i> b ; ἐπί τινι, EUR. <i>Ph. fr. 2, 1,</i> au sujet de qqe ch. ; <i>avec un part</i>. XÉN. <i>Hier. 11, 6 ;</i><br><b>      2</b> <i>p. suite,</i> refuser par jalousie <i>ou</i> malveillance : τινί τινος, OD. <i>6, 68, etc. ;</i> τινί τι, POL. <i>6, 58, 5,</i> qqe ch. à qqn ; τινι <i>avec l’inf</i>. OD. <i>19, 348 ;</i> ESCHL. <i>Sept. 236,</i> à qqn de, <i>etc. ; avec l’inf. seul :</i> οὐκ ἂν φθονέοιμι ἀγορεῦσαι, OD. <i>11, 381,</i> je ne refuse pas de dire, <i>etc. ; cf</i>. EUR. <i>Med. 63 ;</i> AR. <i>Th. 249, etc. ;</i> μὴ φθόνει <i>avec l’inf</i>. PLAT. <i>Gorg. 489</i> a ; μὴ φθονήσῃς <i>avec l’inf</i>. PLAT. <i>Rsp. 338</i> a, <i>etc</i>. ne refuse pas de, <i>etc. ; avec omiss. de l’inf</i>. οὐ φθονήσει, PLAT. <i>Hipp. mi. 363</i> c, il ne refusera pas ; <i>cf</i>. PLAT. <i>Prot. 320</i> c, <i>Conv. 222</i> e ; <i>avec un part. :</i> μηδέ μοι φθόνει λέγων, ESCHL. <i>Sept. 480,</i> et ne refuse pas de me dire ; <i>avec une prop. inf. :</i> οὔτε τινὰ φθονέω δόμεναι, OD. <i>18, 16,</i> et je ne refuse pas que qqn donne ; <i>cf</i>. OD. <i>1, 346 ;</i> HDT. <i>8, 109 ;</i> SOPH. <i>Ant. 553, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. poét. sbj. 2 sg</i>. φθονέσῃς, ANTH. <i>5, 304 ; opt. 3 sg</i>. φθονέσειε, NONN. <i>D. 3, 159 ; part</i>. φθονέσας, ANTH. <i>7, 607. Moy. f. au sens pass</i>. φθονήσομαι, DÉM. <i>1160 fin ;</i> ARSTT. <i>Rhet. Al. 34, 47</i>.<br><span><b>Étym</b>. φθόνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθονεω - φθονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G5355":"<h1>phthonos</h1>\n<p>Strong n° 5355 <i>Prononciation [fthon'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envie</li>\n<li>porter envie, envier c.à.d. poussé à la jalousie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθόνος, ου (ὁ) :<br>      1</b> malveillance, esprit de dénigrement, dépréciation, HDT. <i>9, 71, etc. ; p. opp. à</i> εὔνοια, PLAT. <i>Leg. 635</i> a, <i>etc. ; à</i> ἔπαινος, LYS. <i>168, 16, etc. ; joint à</i> δυσμένεια, PLAT. <i>Rsp. 500</i> c, <i>etc. ; à</i> δυσκόλου ψυχῆς, PLAT. <i>Leg. 844</i> c ; <i>à</i> ὀργή, POL. <i>6, 9, 11, etc. ; au plur</i>. PLUT. <i>Per. 13, etc. ;</i><br><b>      2</b> <i>particul</i>. jalousie, envie, XÉN. <i>Mem. 3, 9, 8 ;</i> PLAT. <i>Def. 416</i> b ; ARSTT. <i>Rhet. 2, 10 ;</i> φθόνον ἔχειν, éprouver de la jalousie (de la part d’autrui), <i>càd</i>. être exposé à l’envie, PD. <i>P. 11, 45 ;</i> ISOCR. <i>95</i> e ; φθόνῳ χρῆσθαι, PLAT. <i>Phædr. 253</i> b, éprouver de l’envie ; φθ. ἐπί τινι, PLUT. <i>M. 39</i> e, <i>etc. ;</i> εἴς τινα, ANTH. <i>6, 257 ;</i> πρός τινα, LUC. <i>Rh. præc. 22,</i> jalousie à l’égard de qqn ; φθόνῳ, HDT. <i>3, 30 ; 9, 71, etc. ;</i> κατὰ φθόνον, ESCHL. <i>Eum. 686, etc. ;</i> ξὺν φθόνῳ, EUR. <i>Andr. 780 ;</i> διὰ φθόνου, NT. <i>Phil. 1, 15,</i> par jalousie ; <i>avec le gén. de la pers. que l’on envie,</i> HDT. <i>8, 124 ;</i> ESCHL. <i>Pr. 859, etc. ; ou le gén. de la pers. qui envie,</i> EUR. <i>Alc. 1135 ;</i> PLAT. <i>Hipp. ma. 282</i> a ; <i>au plur</i>. sentiments <i>ou</i> marques de jalousie, PLAT. <i>Leg. 679</i> c, <i>801</i> e, <i>etc. ;</i> ISOCR. <i>Antid. § 174 ; particul</i>. jalousie des dieux à l’égard des hommes, PD. <i>I. 7, 55 ;</i> ESCHL. <i>Pers. 354, Ag. 921 ;</i> SOPH. <i>El. 1466, etc. ;</i><br><b>      3</b> action de priver de qqe ch. par malveillance <i>ou</i> par jalousie, <i>d’où</i> refus, empêchement : οὐδεὶς φθόνος, ESCHL. <i>Pr. 631 ;</i> PLAT. <i>Rsp. 802 ;</i> PLUT. <i>M. 618</i> c, <i>etc</i>. il n’y a aucune difficulté ; <i>avec un inf. :</i> φθόνος οὐδεὶς λέγειν, PLAT. <i>Phæd. 61</i> d, rien n’empêche de dire ; <i>cf</i>. PLAT. <i>Soph. 217</i> a, <i>Leg. 640</i> d, <i>etc</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *d<sup>h</sup>g<sup>wh</sup>en-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθονος - φθόνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5356":"<h1>phthora</h1>\n<p>Strong n° 5356 <i>Prononciation [fthor-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>corruption, destruction, action de périr, ruine, anéantissement\n<ol type=\"a\">\n<li>ce qui est sujet à la corruption, qui est périssable</li>\n<li>dans le sens Chrétien, la misère éternelle en enfer</li>\n</ol>\n</li>\n<li>dans le N.T., dans un sens moral : corruption c.à.d. décadence morale, dépravation</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φθορά, ᾶς (ἡ) :<br>      1</b> perdition, perte, ruine, HDT. <i>2, 161 ; 7, 18 ;</i> THC. <i>2, 47 ;</i> PLAT. <i>Leg. 677</i> a ; <i>au plur</i>. ESCHL. <i>Ag. 814 ; particul. t. de philos</i>. dissolution de la matière, PLAT. <i>Rsp. 546</i> a, <i>Phæd. 95</i> e, <i>etc. ;</i> ARSTT. <i>Phys. 5, 5, 6, etc. ; au plur</i>. PLAT. <i>Phæd. 96</i> b, <i>etc. ;</i><br><b>      2</b> action de corrompre, corruption, séduction, ESCHN. <i>2, 36 (loi</i>) ; PLUT. <i>M. 712</i> c ;<br><b>      3</b> <i>t. de peint</i>. dégradation des couleurs, affaiblissement de teinte, PLUT. <i>M. 346</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. φθορή, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. φθείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φθορα - φθορά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Pierre (4)</li>\n</ul>\n</td></tr>\n</table>","G5357":"<h1>phiale</h1>\n<p>Strong n° 5357 <i>Prononciation [fee-al'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une coupe large et peu profonde, une soucoupe creuse</li>\n<li>vase à libations</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιάλη, ης (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> vase, <i>particul. :</i><br><b>      1</b> pour faire bouillir un liquide, IL. <i>23, 270 ;</i><br><b>      2</b> sorte de coupe sans pied ni anse, PD. <i>I. 6, 40, etc. ;</i> HDT. <i>1, 50 ; 2, 151 ; 7, 54 ;</i> EUR. <i>Ion 1182 ;</i> CRAT. (<i>Com. fr. 2, 49</i>) ; XÉN. <i>Conv. 2, 23 ;</i> PLAT. <i>Conv. 223</i> c ;<br><b>      3</b> urne funéraire, IL. <i>23, 243, 253 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> bouclier, TIMOTH. (ATH. <i>433</i> d) ; ARSTT. <i>Rhet. 3, 11, 11 ;</i><br><b>      2</b> ornement sur les portes, DS. <i>3, 47 ;</i> AGATHARCH. <i>M. rubr. p. 65</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. φιάλα <span>[ᾰᾱ]</span> EPIGR. (PAUS. <i>5, 10, 4</i>).<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιαλη - φιάλη</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G5358":"<h1>philagathos</h1>\n<p>Strong n° 5358 <i>Prononciation [fil-ag'-ath-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amoureux de la bonté, qui aime le bien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλ·άγαθος, ος, ον</b> <span>[ῐᾰᾰ]</span> qui aime le bien <i>ou</i> les gens de bien, ARSTT. <i>M. mor. 2, 14, 3 ;</i> PLUT. <i>Thes. c. Rom. 2, M. 140</i> c.<br><span><b>Étym</b>. φίλος, ἀγαθός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλαγαθος - φιλάγαθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G5359":"<h1>Philadelpheia</h1>\n<p>Strong n° 5359 <i>Prononciation [fil-ad-el'-fee-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Philadelphie (Angl. Philadelphia) = « amour fraternel »\n<ol><li>ville de Lydie, en Asie Mineure, à environ 45 km au S.E de Sardes, proche du Mont Tmolus</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φιλαδέλφεια</b>, <i>ion</i>. <b>Φιλαδελφείη, ης (ἡ)</b> <span>[ῐᾰ]</span> Philadelphéia (<i>auj</i>. Alaşehir) <i>v. de Lydie,</i> A. PL. <i>34</i>.<br><span><b>Étym</b>. Φιλάδελφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλαδελφεια - Φιλαδέλφεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5360":"<h1>philadelphia</h1>\n<p>Strong n° 5360 <i>Prononciation [fil-ad-el-fee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amour des frères ou des sœurs, amour fraternel</li>\n<li>dans le N.T., l'amour que les chrétiens portent à chacun comme étant des frères</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλαδελφία, ας (ἡ)</b> amitié pour un frère <i>ou</i> une sœur, LUC. <i>D. deor. 26, 2 ;</i> BABR. <i>47, 15, etc</i>.<br><span><b>Étym</b>. φιλάδελφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλαδελφια - φιλαδελφία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5361":"<h1>philadelphos</h1>\n<p>Strong n° 5361 <i>Prononciation [fil-ad'-el-fos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amour pour un frère ou une sœur</li>\n<li>dans un sens plus large, aimer quelqu'un comme un frère, amour pour un compagnon du même pays\n<ol type=\"a\">\n<li>d'un Israélite</li>\n<li>d'un Chrétien aimant les autres Chrétiens</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλ·άδελφος, ος, ον</b> <span>[ῐᾰ]</span><br><b>      1</b> qui aime ses frères <i>ou</i> sœurs, XÉN. <i>Mem. 2, 3, 17 ;</i> PLUT. <i>Sol. 27, etc. ;</i> τὸ φιλάδελφον, DS. <i>17, 34,</i> amour fraternel ;<br><b>      2</b> qui marque l’affection pour un frère, SOPH. <i>Ant. 527</i>.<br><span>•<i> Sup</i>. -ότατος, PLUT. <i>Luc. 43</i>.<br><span><b>Étym</b>. φίλος, ἀδελφός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλαδελφος - φιλάδελφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5362":"<h1>philandros</h1>\n<p>Strong n° 5362 <i>Prononciation [fil'-an-dros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amour pour son mari</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φίλ·ανδρος, ος, ον</b> <span>[ῐ]</span><br><b>   I</b> qui aime son époux, NT. <i>Tit. 2, 4 ;</i> LUC. <i>Halc. 8, etc. ;</i><br><b>   II</b> qui aime les hommes, <i>càd. :</i><br><b>      1</b> qui aime les hommes, ses habitants, <i>en parl. d’un pays,</i> ESCHL. <i>Sept. 902 ;</i><br><b>      2</b> qui aime les hommes <i>ou</i> les habitudes viriles, SOPH. <i>fr. 356 ;</i><br><b>      3</b> qui aime les hommes, passionné pour les hommes, PLAT. <i>Conv. 191</i> e, <i>etc</i>.<br><span><b>Étym</b>. φ. ἀνήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλανδρος - φίλανδρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G5363":"<h1>philanthropia</h1>\n<p>Strong n° 5363 <i>Prononciation [fil-an-thro-pee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amour pour le genre humain, bienveillance, accueil hospitalier</li>\n<li>notre mot : philanthropie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλανθρωπία, ας (ἡ)</b> <span>[φῐ]</span><br><b>   I</b> <i>en gén. :</i><br><b>      1</b> sentiments d’humanité, de bonté, XÉN. <i>Cyr. 1, 4, 1, etc. ; joint à</i> εὔνοια, ISOCR. <i>105</i> d ; <i>à</i> πρᾳότης, ISOCR. <i>106</i> a ; <i>p. opp. à</i> φθόνος, DÉM. <i>507, 26 ; à</i> ὠμότης, DÉM. <i>490, 7, etc. ;</i> φ. λόγων, DÉM. <i>325, 9,</i> bienveillance de langage ; ὑπὸ φιλανθρωπίας, PLAT. <i>Euthyphr. 3</i> d ; φιλανθρωπίᾳ, XÉN. <i>Ages. 1, 22,</i> par bonté ; <i>au plur</i>. actes d’humanité, de bonté, DÉM. <i>107, 17 ; 796, 3, etc. ;</i><br><b>      2</b> <i>en parl. de Dieu,</i> amour pour les hommes, NT. <i>Tit. 3, 4, etc. ;</i><br><b>   II</b> <i>particul</i>. affabilité, PLUT. <i>Lyc. 16 ;</i> clémence, XÉN. <i>Cyr. 7, 5, 73,</i> libéralité, XÉN. <i>Œc. 15, 9 ; en parl. de choses,</i> caractère agréable de qqe ch. DÉM. <i>748, 28, etc. ; en parl. d’un pays,</i> civilisation, DS. <i>17, 50</i>.<br><span><b>Étym</b>. φιλάνθρωπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλανθρωπια - φιλανθρωπία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G5364":"<h1>philanthropos</h1>\n<p>Strong n° 5364 <i>Prononciation [fil-an-thro'-poce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>humainement, avec bonté, avec courtoisie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλανθρώπως</b> <span>[ῐ]</span> <i>adv</i>., avec humanité, avec bonté, DÉM. <i>411, 10, etc. ; joint à</i> δημοτικῶς, DÉM. <i>707, 24 ; à</i> θεοφιλῶς, ISOCR. <i>197</i> c.<br><span>•<i> Sup</i>. -ώτατα, DÉM. <i>760, 5</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλανθρωπως - φιλανθρώπως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5365":"<h1>philarguria</h1>\n<p>Strong n° 5365 <i>Prononciation [fil-ar-goo-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amour de l'argent, avarice</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλαργυρία, ας (ἡ)</b> <span>[ῐῠ]</span> amour de l’argent, ISOCR. <i>178</i> d ; DIN. <i>93, 2 ;</i> POL. <i>9, 25, 4</i>.<br><span><b>Étym</b>. φιλάργυρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλαργυρια - φιλαργυρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5366":"<h1>philarguros</h1>\n<p>Strong n° 5366 <i>Prononciation [fil-ar'-goo-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amour de l'argent, avarice</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλ·άργυρος, ος, ον</b> <span>[ῐῠ]</span> qui aime l’argent, avare, SOPH. <i>Ant. 1055 ;</i> τὸ φιλάργυρον, PLAT. <i>Rsp. 347</i> b, l’amour de l’argent.<br><span>•<i> Sup</i>. -ώτατος, XÉN. <i>Mem. 3, 1, 10 ; 3, 13, 4</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλαργυρος - φιλάργυρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5367":"<h1>philautos</h1>\n<p>Strong n° 5367 <i>Prononciation [fil'-ow-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amour de soi-même</li>\n<li>trop absorbé par son propre intérêt, égoïste</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φίλ·αυτος, ος, ον</b> <span>[ῐ]</span> amoureux de soi, égoïste, ARSTT. <i>Nic. 9, 8, 4, etc. ; M. mor. 2, 14, 3 ; Rhet. 1, 11, 26 ;</i> τὸ φ. PLUT. <i>M. 40</i> f, <i>etc. c</i>. φιλαυτία.<br><span><b>Étym</b>. φ. αὐτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλαυτος - φίλαυτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5368":"<h1>phileo</h1>\n<p>Strong n° 5368 <i>Prononciation [fil-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aimer\n<ol type=\"a\">\n<li>approuver</li>\n<li>ce qui plaît</li>\n<li>sanction</li>\n<li>traiter affectueusement ou avec bonté, accueillir, traiter en ami</li>\n</ol>\n</li>\n<li>montrer des signes d'amour\n<ol type=\"a\">\n<li>embrasser, donner un baiser</li>\n</ol>\n</li>\n<li>aimer faire\n<ol type=\"a\">\n<li>avoir l'habitude de faire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλέω</b> <span>(<i>f</i>. -ήσω, <i>ao</i>. ἐφίλησα, <i>pf</i>. πεφίληκα)</span> <span>[ῐ, <i>v. ci-dessous</i>]</span><br><b>   I</b> aimer d’amitié (<i>p. opp. à</i> ἐρᾶν, aimer d’amour) XÉN. <i>Conv. 8, 21 ; Hier. 11, 11 ;</i> PLAT. <i>Phædr. 231</i> c, <i>etc. :</i><br><b>      1</b> <i>en gén</i>. éprouver de l’amitié pour qqn, aimer, chérir, <i>acc</i>. HOM. ATT. : φ. ἐκ θυμοῦ, IL. <i>9, 343, 486 ;</i> φ. θυμῷ, <i>9, 146 ;</i> φ. κῆρι, IL. <i>9, 117 ;</i> περὶ κῆρι, OD. <i>14, 245 ;</i> φ. κηρόθι, OD. <i>15, 369,</i> aimer du fond du cœur ; <i>p. opp. à</i> ἀπεχθαίρειν, IL. <i>3, 415 ;</i> HÉS. <i>O. 300 ;</i> SOPH. <i>Aj. 680, etc. ; à</i> μισεῖν, PLAT. <i>Rsp. 479</i> e, <i>etc. ; joint à</i> στέργειν, PLUT. <i>M. 114</i> c ; <i>à</i> ἀσπάζεσθαι, PLAT. <i>Rsp. 607</i> a, <i>etc. ; avec l’acc</i>. HOM. ATT. ; <i>ou avec double acc</i>. φιλεῖν τινα φιλότητα, OD. <i>15, 245, 246,</i> aimer qqn ; <i>abs</i>. OD. <i>8, 208 ;</i> PLAT. <i>Leg. 859</i> a, <i>etc. ;</i> φ. ἐπί τινι, PLAT. <i>Rsp. 600</i> d, <i>ou</i> ἔν τινι, PLAT. <i>Lys. 210</i> c, aimer pour qqe ch. ; <i>au pass</i>. φιλεῖσθαι ὑπό τινος, ATT. ; παρά τινι, XÉN. <i>Cyr. 8, 2, 26 ;</i> ἔκ τινος, IL. <i>2, 668 ; ou</i> τινι, EUR. <i>Hec. 1000,</i> être aimé par qqn ;<br><b>      2</b> regarder comme un ami, traiter en ami, <i>d’où</i> prendre soin de, aider, assister : τινα, IL. <i>2, 197 ; 6, 14, 15, etc</i>. qqn ; <i>joint à</i> κήδεσθαι, IL. <i>7, 204 ; 9, 342 ; à</i> αἰδέεσθαι, OD. <i>14, 388 ; à</i> τρέφειν, OD. <i>7, 256 ; à</i> κομέειν, OD. <i>12, 450, etc. ; p. suite,</i> aimer, <i>p. opp. à</i> ἐχθαίρειν, <i>4, 692 ;</i> OD. <i>15, 70 ;</i><br><b>      3</b> donner un signe d’amitié, <i>d’où</i> baiser : τῷ στόματι, HDT. <i>1, 134, etc. ;</i> τοῖς στόμασι, XÉN. <i>Conv. 9, 5 ;</i> κατὰ τὸ στόμα, ANTH. <i>5, 285,</i> baiser sur la bouche ; <i>de même :</i> φ. τινα, ESCHL. <i>Ag. 1540,</i> baiser qqn ; φ. κάρα, SOPH. <i>O.C. 1131,</i> baiser la tête, <i>etc. ; avec double rég. :</i> φίλαμά (<i>dor</i>.) τινα φιλεῖν, MOSCH. <i>3, 69,</i> donner un baiser à qqn ;<br><b>   II</b> aimer d’amour, <i>c</i>. ἐρᾶν, OD. <i>18, 325 ;</i> HDT. <i>4, 176 ;</i> XÉN. <i>Ages. 5, 4, etc. ;</i><br><b>   III</b> <i>p. ext</i>. aimer, <i>càd. :</i><br><b>      1</b> voir volontiers, accueillir avec plaisir, approuver, agréer : σχέτλια ἔργα, OD. <i>14, 83,</i> des actions mauvaises ; αἰσχροκέρδειαν, SOPH. <i>Ant. 1056,</i> un gain honteux ;<br><b>      2</b> rechercher, poursuivre : τὸ κέρδος, PLAT. <i>Phædr. 226</i> e ; τὸ κερδαίνειν, SOPH. <i>Ant. 312,</i> le gain ;<br><b>      3</b> se plaire à, <i>avec l’acc. :</i> ἁσυχίαν φιλεῖ συμπόσιον, PD. <i>N. 9, 114,</i> un banquet aime le calme ; <i>avec un inf</i>. aimer à, se plaire à, <i>d’où</i> avoir coutume de : φιλέει ὁ θεὸς τὰ ὑπερέχοντα κολούειν, HDT. <i>7, 10,</i> la divinité se plaît à, <i>càd</i>. a coutume de rabaisser ce qui s’élève trop ; φιλεῖ τίκτειν ὕϐρις ὕϐριν, ESCHL. <i>Ag. 764,</i> la violence a coutume d’engendrer la violence ; <i>avec un n. de chose pour suj. :</i> αὔρη φιλέει πνέειν, HDT. <i>2, 27,</i> le vent a coutume de souffler ; <i>avec un part. :</i> φιλεῖς δὲ δρῶσ' αὐτό, AR. <i>Pl. 645,</i> tu aimes bien à faire cela ; οἶα φιλεῖ γίγνεσθαι, THC. <i>7, 79,</i> comme cela a coutume d’arriver ; <i>ou sans</i> γίγνεσθαι : οἶα φιλεῖ, PLAT. <i>Rsp. 467</i> b, <i>ou</i> ὁποῖα φιλεῖ, LUC. <i>Am. 9,</i> comme il a coutume d’arriver, selon l’habitude ; <i>impers. φιλέει avec l’inf</i>. HDT. <i>6, 27,</i> c’est l’habitude que, <i>etc. ;</i> ὡς φιλεῖ <i>avec l’inf</i>. PLUT. <i>Pomp. 73,</i> comme c’est l’habitude ;<br><b><i>Moy.</i></b> se baiser mutuellement, HDT. <i>1, 134</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act prés. ind. 3 pl</i>. φιλέοισι, PD. <i>P. 3, 18 ; dor</i>. φιλεῦντι, THCR. <i>Idyl. 5, 80 ; sbj. 3 sg. épq</i>. φιλέῃσι, OD. <i>15, 70 ; inf. épq</i>. φιλήμεναι, IL. <i>22, 265 ; part. dor. masc. acc. pl</i>. φιλεῦντας, OD. <i>3, 221 ; fém</i>. φιλέοισα, THCR. <i>Idyl. 16, 105, ou</i> φιλεῦσα, THCR. <i>Idyl. 27, 2. Impf. itér</i>. φιλέεσκον, IL. <i>3, 388 ; 9, 450 ;</i> ANTH. <i>5, 285. Fut. inf. épq</i>. φιλησέμεν, OD. <i>4, 171. Pass. ao. ind. 3 pl. épq</i>. ἐφίληθεν, IL. <i>2, 668. Conjug. dor. en</i> ᾱ : <i>fut</i>. φιλάσω <span>[ᾱ]</span> THCR. <i>Idyl. 23, 33. Ao</i>. ἐφίλασα <span>[λᾱ]</span> PD. <i>P. 2, 16 ; 9, 18 ;</i> THCR. <i>Idyl. 20, 31, 42 ; ou</i> φίλασα <span>[λᾱ]</span> PD. <i>N. 5, 44 ;</i> THCR. <i>Idyl. 20, 36, 38 ; impér</i>. φίλασον <span>[ᾱ]</span> THCR. <i>Idyl. 3, 19 ; sbj</i>. φιλάσω <span>[ᾱ]</span> THCR. <i>Idyl. 3, 19 ; inf</i>. φιλᾶσαι, THCR. <i>Idyl. 20, 1 ; part</i>. φιλάσας <span>[λᾱ]</span> PD. <i>N. 7, 88 ;</i> THCR. <i>Idyl. 23, 42 ; pass. ao. 3 pl</i>. ἐφίλαθεν <span>[ᾱ]</span> THCR. <i>Idyl. 7, 60 (var</i>. -ηθεν) ; <i>part. pf</i>. πεφιλαμένος <span>[ᾱ]</span> THCR. <i>Idyl. 3, 3 ; 11, 6. Moy. f. au sens pass</i>. φιλήσομαι, OD. <i>1, 123 ; 15, 281 ;</i> ANT. <i>1, 19. Formes moy. irrég. : ao</i>. ἐφιλάμην <span>[ῑᾰ]</span>, <i>d’où 2 sg</i>. ἐφίλαο, ANTH. <i>5, 289 ; 3 sg</i>. ἐφίλατο, IL. <i>5, 61 ; ou</i> φίλατο, IL. <i>20, 304 ; au sens pass</i>. A. RH. <i>3, 66 ; impér</i>. φῖλαι, IL. <i>5, 117 ; sbj</i>. φίλωμαι <span>[ῑ]</span> HH. <i>Cer. 117 ;</i> HÉS. <i>Th. 97 ; part</i>. φιλάμενος <span>[ῑ]</span> ANTH. <i>App. 317</i>.<br><span><b>Étym</b>. φίλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλεω - φιλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 21 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (13)</li>\n<li>1 Corinthiens (1)</li>\n<li>Tite (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5369":"<h1>philedonos</h1>\n<p>Strong n° 5369 <i>Prononciation [fil-ay'-don-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amour du plaisir, voluptueux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλ·ήδονος, ος, ον</b> <span>[ῐ]</span><br><b>      1</b> qui aime <i>ou</i> recherche le plaisir, voluptueux, POL. <i>40, 6, 11 ;</i> τὸ φ. PLUT. <i>M. 1094</i> a, <i>c</i>. φιληδονία ;<br><b>      2</b> qui procure du plaisir, ANTH. <i>10, 118</i>.<br><span><b>Étym</b>. φίλος, ἡδονή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιληδονος - φιλήδονος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5370":"<h1>philema</h1>\n<p>Strong n° 5370 <i>Prononciation [fil'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un baiser, l'action d'embrasser</li>\n<li>le baiser par lequel, en signe d'affection fraternelle, les chrétiens avaient coutume d'accueillir ou de congédier leurs compagnons dans la foi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φίλημα, ατος (τὸ)</b> <span>[ῐ]</span> baiser, ESCHL. <i>fr. 135 ;</i> SOPH. <i>fr. 482 ;</i> EUR. <i>Andr. 416, etc. ;</i> XÉN. <i>Mem. 1, 3, 8, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. φίλαμα <span>[λᾱ]</span> MOSCH. <i>3, 69</i>.<br><span><b>Étym</b>. φιλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλημα - φίλημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5371":"<h1>Philemon</h1>\n<p>Strong n° 5371 <i>Prononciation [fil-ay'-mone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Philémon (Angl. Philemon) = « attentionné, qui embrasse »\n<ol><li>résident de Colosses, converti au Christianisme par Paul, et destinataire de la lettre portant son nom</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φιλήμων, ονος (ὁ)</b> <span>[ῐ]</span> Philèmôn (Philémon) :<br><b>      1</b> <i>poète de la nouvelle comédie ;</i><br><b>      2</b> <i>autres,</i> THC. <i>2, 67 ;</i> AR. <i>Av. 763 ;</i> PLAT. <i>Theag. 129</i> b, <i>etc</i>.<br><span><b>Étym</b>. φιλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλημων - Φιλήμων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G5372":"<h1>Philetos</h1>\n<p>Strong n° 5372 <i>Prononciation [fil-ay-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Philète (Angl. Philetus) = « bien-aimé, digne d'amour »\n<ol><li>un hérétique et disciple d'Hyménée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φίλητος, ου (ὁ)</b> <span>[ῐ]</span> Philètos, <i>h</i>. ANTH. <i>App. 380</i>.<br><span><b>Étym</b>. <i>cf</i>. φιλητός.</span><br><br>\n<b>φιλητός, ή, όν</b> <span>[ῐ]</span> <i>vb. de</i> φιλέω, ARSTT. <i>Nic. 9, 7, 6, etc. ;</i> τὸ φ. ARSTT. <i>Nic. 8, 2, 2,</i> objet d’amour.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλητος - Φίλητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5373":"<h1>philia</h1>\n<p>Strong n° 5373 <i>Prononciation [fil-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amitié</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλία, ας (ἡ)</b> <span>[φῐ]</span><br><b>   I</b> amitié :<br><b>      1</b> <i>en gén</i>. THGN. <i>306, 600, 1102 ;</i> HDT. <i>7, 152 ;</i> ATT. ; <i>au plur</i>. HPC. <i>254 ;</i> HDT. <i>3, 82 ;</i> PLAT. <i>Conv. 182</i> c, <i>etc. ; p. opp. à</i> ἔχθρα, ISOCR. <i>9</i> b ; PLAT. <i>Soph. 242</i> e, <i>etc. ; à</i> μῖσος, ISOCR. <i>Antid. § 130 ; à</i> ὀργή, PLAT. <i>Epin. 976</i> b, <i>etc. ; joint à</i> εὔνοια, XÉN. <i>Cyr. 3, 1, 28 ; à</i> ὁμόνοια, PLAT. <i>Rsp. 351</i> d, <i>ou</i> ὁμοφροσύνη, PLUT. <i>M. 156</i> c ; <i>à</i> χάρις, PLUT. <i>Lyc. 4, etc. ; particul. en parl. de rapports entre les dieux et les hommes,</i> PLAT. <i>Conv. 188</i> c ; <i>des relations de famille,</i> XÉN. <i>Hier. 3, 7 ; de relations entre les États,</i> THC. <i>5, 5 ; 6, 34, 78, etc. ; de l’affection d’un grand pour le roi,</i> XÉN. <i>An. 1, 6, 3, etc. ; de même, en parl. de l’amitié des animaux entre eux,</i> PLAT. <i>Clit. 409</i> d ; <i>p. ext. en parl. de choses,</i> PLAT. <i>Epin. 976</i> b ; φιλίαν ποιεῖσθαι πρός τινα, XÉN. <i>Mem. 2, 6, 29,</i> contracter amitié avec qqn ; φ. λαϐεῖν παρά τινος, XÉN. <i>Cyr. 3, 1, 28,</i> recevoir un témoignage de bienveillance de qqn ; διὰ φιλίαν ἰέναι τινί, XÉN. <i>An. 3, 2, 8 ;</i> εἰς φιλίαν ἰέναι, PLAT. <i>Phædr. 237</i> c, <i>ou</i> ἔρχεσθαι, PLAT. <i>Lys. 214</i> d, entrer dans des relations d’amitié avec qqn ; φιλίαν διαλύεσθαι, ISOCR. <i>302</i> e, <i>ou</i> ἀποθέσθαι, PLUT. <i>M. 94</i> d, rompre des liens d’amitié ; τῆς φιλίας ἐξίστασθαί τινι, LYS. <i>114, 2,</i> se détacher de liens d’amitié avec qqn ; φιλίαν ποιεῖν τινι πρός τινα, PLUT. <i>Thes. 19,</i> former des relations d’amitié entre une personne et une autre ; <i>avec une prép. :</i> μετὰ φιλίας, XÉN. <i>Mem. 1, 2, 10,</i> avec amitié ; διὰ φιλίας, PLAT. <i>Pol. 404</i> e ; κατὰ φιλίαν, PLAT. <i>Leg. 823</i> b ; διὰ τὴν φιλίαν, THC. <i>1, 91,</i> par amitié ; φιλία πρός τινα, ISOCR. <i>88</i> d, <i>etc. ;</i> εἴς τινα, EUR. <i>Hipp. 254, etc. ;</i> τινός, THC. <i>1, 91 ; 6, 78 ;</i> XÉN. <i>An. 5, 6, 11 ;</i> τινί, PLAT. <i>Gorg. 513</i> b, <i>etc</i>. amitié pour qqn ; φιλίᾳ τῇ σῇ, XÉN. <i>An. 7, 7, 29,</i> par amitié pour toi ;<br><b>      2</b> amitié, <i>au sens de</i> vive affection, amour, <i>mais sans idée de sensualité,</i> XÉN. <i>Conv. 8, 15 ;</i> PLAT. <i>Conv. 179</i> c, <i>182</i> c ; <i>Phædr. 237</i> c, <i>etc. ;</i><br><b>      3</b> amour, <i>c</i>. ἔρως, SPT. <i>Prov. 5, 19 ;</i><br><b>      4</b> <i>fig</i>. amour (du gain, PLAT. <i>Rsp. 581</i> a ; du pouvoir, ARSTT. <i>Cæl. 3, 7, 10, etc</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. φιλίη, HDT. HPC. <i>ll. cc</i>.<br><span><b>Étym</b>. φίλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλια - φιλία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G5374":"<h1>Philippesios</h1>\n<p>Strong n° 5374 <i>Prononciation [fil-ip-pay'-see-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>habitants de la ville de Philippes, ou qui en sont originaires</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλιππησιος - Φιλιππήσιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5375":"<h1>Philippoi</h1>\n<p>Strong n° 5375 <i>Prononciation [fil'-ip-poy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Philippes (Angl. Philippi) = « appartenant à Philippe »\n<ol><li>ville de Macédoine située en Thrace, près de la côte nord de la mer Egée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φίλιπποι, ων (οἱ)</b> les plaines de Philippes, <i>en Macédoine,</i> PLUT. <i>Brut. 38</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλιπποι - Φίλιπποι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5376":"<h1>Philippos</h1>\n<p>Strong n° 5376 <i>Prononciation [fil'-ip-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Philippe (Angl. Philip) = « aimant les chevaux »\n<ol><li>un des deux fils d'Hérode le Grand et de Cléopatre de Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φίλ·ιππος, ου (ὁ)</b> Philippe :<br><b>      1</b> <i>roi de Macédoine,</i> DÉM. <i>Or. 1, 12, etc. Baiter-Sauppe ;</i><br><b>      2</b> <i>autres,</i> HDT. <i>8, 139 ;</i> THC. <i>1, 57, 59 ; 2, 95 ;</i> XÉN. <i>Conv. 1, 11 ;</i> PLAT. <i>Conv. 172</i> b, <i>etc</i>.<br><span><b>Étym</b>. <i>cf</i>. φίλιππος.</span><br><br>\n<b>φίλ·ιππος, ος, ον</b> <span>[φῐ]</span> qui aime les chevaux, PD. <i>N. 9, 74 ;</i> SOPH. <i>fr. 523, 738 ;</i> EUR. <i>Hec. 9</i>.<br><span>•<i> Sup</i>. φιλιππότατος, XÉN. <i>An. 1, 9, 5</i>.<br><span><b>Étym</b>. φίλος, ἵππος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλιππος - Φίλιππος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n37 fois dans 36 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Jean (12)</li>\n<li>Actes (17)</li>\n</ul>\n</td></tr>\n</table>","G5377":"<h1>philotheos</h1>\n<p>Strong n° 5377 <i>Prononciation [fil-oth'-eh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amour de Dieu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλό·θεος, ος, ον</b> <span>[ῐ]</span> qui aime Dieu, pieux, ARSTT. <i>Rhet. 2, 17, 6 ;</i> LUC. <i>Cal. 14, etc</i>.<br><span><b>Étym</b>. φ. θεός ; <i>cf</i>. θεόφιλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοθεος - φιλόθεος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5378":"<h1>Philologos</h1>\n<p>Strong n° 5378 <i>Prononciation [fil-ol'-og-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Philologue (Angl. Philologus) = « amateur de paroles, de savoir »\n<ol><li>un chrétien de Rome que Paul salue dans l'épître aux Romains</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φιλό·λογος, ου (ὁ)</b> <span>[ῐ]</span> Philologus, <i>affranchi de Q. Cicéron,</i> PLUT. <i>Cic. 48, 49</i>.<br><span><b>Étym</b>. <i>v</i>. φιλόλογος.</span><br><br>\n<b>φιλό·λογος, ος, ον</b> <span>[ῐ]</span><br><b>      1</b> qui aime à parler, <i>en parl. de Lysias,</i> PLAT. <i>Phædr. 236</i> e ; <i>p. suite,</i> qui parle volontiers <i>ou</i> beaucoup, <i>joint à</i> πολυλόγος, <i>p. opp. à</i> βραχυλόγος, PLAT. <i>Leg. 641</i> e ; <i>d’où</i> bavard, qui a la langue déliée (par l’effet du vin) ALEX. (ATH. <i>39</i> b) ;<br><b>      2</b> qui aime les lettres <i>ou</i> l’érudition, la discussion, la dialectique, PLAT. <i>Lach. 188</i> c, <i>Phædr. 236</i> e, <i>Theæt. 161</i> a ; <i>joint à</i> φιλόσοφος, PLAT. <i>Rsp. 582</i> e ;<br><b>      3</b> qui aime à disserter sur des sujets littéraires <i>ou</i> d’érudition, ARSTT. <i>Rhet. 2, 23, 11 ; joint à</i> φιλομαθής, PLUT. <i>M. 618</i> e ; <i>p. opp. à</i> ἀπαίδευτος, PÉRICT. (STOB. <i>428, 52</i>) ;<br><b>      4</b> <i>p. ext</i>. qui s’occupe de recherches approfondies sur des questions d’érudition, <i>particul</i>. sur les langues <i>ou</i> l’histoire des anciens peuples ; <i>les premiers écrivains qui se soient appelés φιλόλογοι en ce sens sont, en Grèce, Ératosthène,</i> SUÉT. <i>Gramm. 10 ; à Rome, Ateius Capiton ;</i><br><b>      5</b> qui s’occupe de recherches sur les mots, <i>p. opp. à</i> φιλόσοφος, SYN. <i>43</i> b.<br><span>•<i> Cp</i>. φιλολογώτερος, CIC. <i>Att. 13, 12 ;</i> <i>• Sup</i>. φιλολογώτατος, PLUT. <i>Cato ma. 22</i>.<br><span><b>Étym</b>. φ. λέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φιλολογος - Φιλόλογος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5379":"<h1>philoneikia</h1>\n<p>Strong n° 5379 <i>Prononciation [fil-on-i-kee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amour de la lutte, empressement à lutter</li>\n<li>dispute, lutte\n<ol type=\"a\">\n<li>dans un bon sens : émulation</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλονεικία, ας (ἡ)</b> <span>[φῐ]</span><br><b>      1</b> goût pour les querelles, amour des disputes, jalousie, THC. <i>1, 41 (corr</i>. φιλονικία) ; PLAT. <i>Leg. 796</i> a ; LYS. <i>100, 12 ; joint à</i> ἔρις, DÉM. <i>114, 8 ; à</i> πόλεμος, ISOCR. <i>266</i> a ; <i>au plur. joint à</i> στάσεις, ARSTT. <i>Pol. 5, 8, 9 ;</i> φιλονεικίαν ἐμϐάλλειν τινί, XÉN. <i>Cyr. 7, 1, 18,</i> faire naître chez qqn un désir de rivaliser avec d’autres (pour se montrer aussi brave que possible à l’égard de qqn) ;<br><b>      2</b> <i>en gén</i>. rivalité, émulation, XÉN. <i>An. 4, 8, 27 ; joint à</i> ἅμιλλα, PLAT. <i>Leg. 834</i> c ; <i>au plur. joint à</i> φιλοτιμίαι, PLAT. <i>Rsp. 548</i> c ; πρός τινα, XÉN. <i>Cyr. 8, 2, 26 ; Œc. 21, 10 ;</i> PLAT. <i>Menex. 243</i> b, avec qqn ; περί τινος, XÉN. <i>Cyr. 2, 1, 22 ;</i> πρός τι, XÉN. <i>Cyr. 8, 7, 12 ;</i> περί τι, ISOCR. <i>150</i> c, au sujet de qqe ch.<br><span><b>Étym</b>. φιλόνεικος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλονεικια - φιλονεικία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5380":"<h1>philoneikos</h1>\n<p>Strong n° 5380 <i>Prononciation [fil-on'-i-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aimant la lutte, querelleur\n<ol type=\"a\">\n<li>dans un bon sens : plein d'émulation</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλό·νεικος, ος, ον</b> <span>[ῐ]</span><br><b>      1</b> qui aime la dispute, querelleur, PLAT. <i>Prot. 336</i> e, <i>etc. ;</i> ISOCR. <i>8</i> d ; LYS. <i>192, 8 ;</i> τὸ φιλόνεικον, XÉN. <i>Cyr. 7, 5, 64, c</i>. φιλονεικία ;<br><b>      2</b> qui s’efforce à l’envi d’un autre, plein d’émulation, PLAT. <i>Rsp. 545</i> a, <i>551</i> b, <i>581</i> c.<br><span>•<i> Cp</i>. φιλονεικότερος (<i>v</i>. φιλονείκως) ; <i>sup</i>. φιλονεικότατος, PLUT. <i>Ages. 2</i>.<br><span><b>Étym</b>. φ. νεῖκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλόνεικος</font></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5381":"<h1>philoxenia</h1>\n<p>Strong n° 5381 <i>Prononciation [fil-on-ex-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amour pour les étrangers, hospitalité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλοξενία, ας (ἡ)</b> <span>[ῐ]</span> pratique de l’hospitalité, PLAT. <i>Leg. 955</i> a ; POL. <i>4, 20, 1 ;</i> PLUT. <i>Thes. 14 et 23, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. φιλοξενίη, THGN. <i>1358</i>.<br><span><b>Étym</b>. φιλόξενος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοξενια - φιλοξενία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5382":"<h1>philoxenos</h1>\n<p>Strong n° 5382 <i>Prononciation [fil-ox'-en-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>hospitalier, généreux pour ses invités</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλό·ξενος, ος, ον</b> <span>[ῐ]</span> qui aime les étrangers, qui pratique l’hospitalité, hospitalier, <i>en parl. de pers</i>. OD. <i>6, 121 ; 8, 576, etc. ;</i> PD. <i>O. 3, 1 ; N. 1, 30 ;</i> EUR. <i>Alc. 809, 833, 861 ; joint à</i> μεγαλοπρεπής, XÉN. <i>Hell. 6, 1, 3 ; en parl. de choses (parole</i>) ESCHL. <i>Suppl. 904 ; demeure,</i> ESCHL. <i>Ch. 646 ; table,</i> PLUT. <i>M. 991</i> d, <i>etc</i>.<br><span>•<i> Sup</i>. φιλοξενώτατος, ESCHL. <i>fr. 198 ;</i> CRAT. (PLUT. <i>Cim. 10</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. φιλόξεινος, OD. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοξενος - φιλόξενος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5383":"<h1>philoproteuo</h1>\n<p>Strong n° 5383 <i>Prononciation [fil-op-rote-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aspirer à la prééminence, désirer être le premier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλοπρωτεύω</b> <span>[ῐ]</span> aimer à primer, ambitionner la prééminence sur, <i>gén</i>. NT. <i>3 Joh. 9</i>.<br><span><b>Étym</b>. φιλόπρωτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοπρωτευω - φιλοπρωτεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5384":"<h1>philos</h1>\n<p>Strong n° 5384 <i>Prononciation [fee'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ami, être lié d'amitié avec quelqu'un, lui vouloir du bien\n<ol type=\"a\">\n<li>un ami</li>\n<li>un associé</li>\n<li>celui qui est associé familièrement avec quelqu'un, un compagnon</li>\n<li>un des amis du fiancé qui est chargé de demander la main de la fiancée et qui rend divers services pendant la cérémonie du mariage et la célébration des noces</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φίλος, η, ον</b>, <i>voc. (v. fin</i>) <span>[ῐ, <i>v. fin</i>]</span> ami, <i>càd. :</i><br><b>   I</b> <i>pass. :</i><br><b>      1</b> aimé, chéri, cher, <i>en parl. de pers. et de ch</i>. IL. <i>7, 279, etc. ; joint à</i> αἰδοῖος, IL. <i>8, 386 ;</i> OD. <i>5, 88 ; à</i> τίμιος, OD. <i>10, 38 ; à</i> κεδνότατος, IL. <i>9, 382 ; à</i> ἀγαπητός XÉN. <i>Mem. 2, 1, 33 ; à</i> οἰκεῖος, PLAT. <i>Tim. 20, etc. ; renforcé par</i> περὶ κῆρι, IL. <i>24, 423, etc. ; avec un dat</i>. φ. τινί, IL. <i>4, 41 ;</i> ESCHL. <i>Ag. 879, etc</i>. cher à qqn ; <i>avec un gén. :</i> φίλ' ἀνδρῶν, THCR. <i>Idyl. 15, 74 ; 24, 40</i> ami ! <i>litt</i>. toi qui m’es cher parmi les hommes ; <i>cf</i>. EUR. <i>Alc. 472 ; au voc</i>. φίλε <i>avec un subst. masc</i>. IL. <i>4, 155 ; 5, 359 ; ou avec un subst. neutre :</i> φίλε τέκνον, OD. <i>2, 363 ; 3, 484, etc.,</i> cher enfant ! <i>ou</i> φίλος <i>avec un subst. masc</i>. IL. <i>4, 189 ; 9, 601 ;</i> IL. <i>21, 106, etc. ; de même,</i> ESCHL. <i>Pr. 546 ;</i> EUR. <i>Suppl. 277 ;</i> PLUT. <i>M. 1066</i> d, <i>etc. ; subst. :</i> ὁ φ. l’ami, <i>abs</i>. ATT. ; <i>au plur</i>. φίλοι, IL. <i>14, 256 ;</i> OD. <i>2, 333, etc. ;</i> ATT., les amis ; <i>joint à</i> ἑταῖρος, PLUT. <i>M. 94</i> f, <i>etc. ; à</i> ξένος, LYS. <i>19, 19 Baiter-Sauppe, etc. ; p. opp. à</i> ἐχθρός ; ESCHL. <i>Ag. 1347, etc. ; avec un gén. :</i> ὁ Διὸς φίλος, ESCHL. <i>Pr. 304,</i> l’ami de Zeus ; τοὺς ἐμαυτοῦ φίλους, ESCHN. <i>7, 27,</i> mes amis ; <i>avec un adj. :</i> φίλος ἐμός, SOPH. <i>Ph. 421,</i> mon ami ; τοὺς σφετέρους φίλους, XÉN. <i>Hell. 4, 8, 25,</i> leurs amis ; <span><i>prov</i>. ἔστιν ὁ φ. ἄλλος αὐτός</span>, ARSTT. <i>Nic. 9, 4, 5,</i> l’ami est un autre soi-même ; κοινὰ τὰ τῶν φίλων, PLAT. <i>Phæd. fin ; ou</i> κοινὰ τὰ φίλων, PLUT. <i>M. 65</i> a, tout est commun entre amis, <i>etc. ;</i> φίλον ποιεῖν τινα, LYS. <i>11, etc. ; ou</i> ποιεῖσθαι, LUC. <i>Pisc. 38,</i> faire de qqn son ami ; τοὺς φίλους κτᾶσθαι, THC. <i>2, 40,</i> se concilier des amis ; φίλῳ χρῆσθαί τινι, ANT. <i>136, 41 ;</i> φίλον ἔχειν τινά, AND. <i>6, 26,</i> avoir qqn pour ami ; — <i>ou</i> allié, <i>p. opp. à</i> πολέμιος, XÉN. <i>Hell. 6, 5, 48 ; joint à</i> σύμμαχοι, DÉM. <i>113, 21 ; — ou</i> ami d’une femme, XÉN. <i>Mem. 3, 11, 4, etc. ; dans la conversat. en s’adressant à un inconnu :</i> mon ami ! mon bon ami ! NT. <i>Luc. 14, 10, etc. ;</i> ἡ φίλη, amie, OD. <i>4, 722 ;</i> SOPH. <i>Ant. 543 ;</i> XÉN. <i>Mem. 2, 1, 23, etc. ;</i> femme, épouse, IL. <i>9, 146, 288 ;</i> mère, ESCHL. <i>Pers. 832, etc. ;</i> τὸ φίλον, objet d’affection, être chéri, chose aimée, acceptée, admise, SOPH. <i>O.C. 187 ;</i> AR. <i>Eccl. 952, etc. ;</i> τὰ φίλτατα, ESCHL. <i>Pers. 851, etc. ;</i> SOPH. <i>O.R. 366, etc. ;</i> EUR. <i>Med. 16 ;</i> XÉN. <i>Cyr. 4, 3, 2 ;</i> PLAT. <i>Prot. 313</i> e, <i>etc</i>. les objets <i>ou</i> les êtres les plus chers ;<br><b>      2</b> agréable, qui plaît, OD. <i>8, 248 ; joint à</i> ἡδύς, IL. <i>7, 387 ; p. opp. à</i> πικρός, SOPH. <i>O.C. 615 ;</i> φ. τινί, IL. <i>5, 891 ;</i> OD. <i>13, 295,</i> agréable à qqn ; φίλον ἐστί, IL. <i>21, 101 ;</i> OD. <i>9, 211, etc</i>. cela est agréable ; φίλον ἐστί, <i>avec l’inf</i>. IL. <i>24, 334 ;</i> OD. <i>14, 378 ; 15, 361 ;</i> HDT. <i>1, 108,</i> ATT. il plaît de, <i>etc. ;</i> εἴ πού τοι φίλον ἐστί, OD. <i>7, 320,</i> si cela t’est agréable ; εἰ ὑμῖν φίλον, PLAT. <i>Prot. 353</i> b, <i>etc</i>. si cela vous est agréable ; <i>avec un part. :</i> εἰ τόδ' αὐτῷ φίλον κεκλημένῳ, ESCHL. <i>Ag. 161,</i> s’il lui plaît d’être appelé ainsi ; τοὶ φίλον ἔπλετο θυμῷ, OD. <i>13, 145 ; cf</i>. OD. <i>13, 335, etc</i>. il te plaît d’agir ; <i>au plur. :</i> φίλα ἐστί, <i>etc. avec l’inf</i>. il est agréable de, il plaît de, <i>etc</i>. IL. <i>1, 108 ; 4, 345, etc. ;</i><br><b>      3</b> <i>en poésie, particul. chez Hom. φίλος s’emploie comme équival. de l’adj. poss</i>. mon, ton, son, <i>etc., mais touj. appliqué à des êtres ou à des obj. réputés chers :</i> φίλον ἦτορ, IL. <i>3, 31, etc</i>. mon (ton, son) cœur ; μητρὶ φίλῃ Ἀλθαίῃ χωόμενος κῆρ, IL. <i>9, 555,</i> irrité dans son cœur contre sa mère Althæè ; φίλας περὶ χεῖρε βαλόντε, OD. <i>11, 211,</i> nous serrant tous les deux dans nos bras ; <i>cf</i>. IL. <i>1, 569 ; 5, 155 ; 7, 271 ; 19, 209 ; 20, 479, etc. ;</i> OD. <i>8, 233, etc. ;</i><br><b>   II</b> <i>act. :</i><br><b>      1</b> qui aime, <i>gén. :</i> μουσικῆς, EUR. <i>fr. 584,</i> la musique ; ἀληθείας, PLAT. <i>Gorg. 487</i> a, la vérité ; <i>cf</i>. PLAT. <i>Soph. 248</i> a, <i>etc. ;</i><br><b>      2</b> <i>rare et surt. en poésie,</i> aimant, bienveillant, OD. <i>1, 313 ; joint à</i> ἤπιος, IL. <i>24, 775 ; à</i> εὔνους, PLUT. <i>M. 178</i> d ; φ. τινί, XÉN. <i>Cyr. 1, 5, 4 ; ou</i> τινός, PD. <i>P. 3, 9 ; N. 5, 10,</i> bienveillant pour qqn ; <i>en parl. de choses</i> (présent, <i>etc</i>.) IL. <i>17, 325 ;</i> OD. <i>6, 208 ; 8, 545, etc. ;</i> φίλα φρονέειν τινί, IL. <i>4, 219 ; ou</i> φίλα εἰδέναι τινί, OD. <i>8, 277,</i> avoir de la bienveillance pour qqn ; φίλα ἐργάζεσθαί τινι, OD. <i>24, 210,</i> faire des travaux agréables à qqn ; φίλα ποιεῖσθαί τινι, HDT. <i>2, 152,</i> témoigner de l’amitié à qqn, faire bon accueil à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. φίλος, PD. <i>O. 2, 170 ; voc. masc</i>. φίλε <span>[ῐ]</span> <i>au premier temps fort du vers,</i> IL. <i>4, 155 ; 5, 359 ; sur le voc</i>. φίλος, <i>ou le voc. φίλε dans la locut</i>. φίλε τέκνον, <i>v. ci-dessus</i>.<br><span>•<i> Cp. et sup. de 3 thèmes :</i><br><b>      1</b> <i>th</i>. φιλο- <span>[ῐ]</span> φιλώτερος, XÉN. <i>Mem. 3, 11, 18 ;</i> CALL. <i>fr. 146 ;</i><br><b>      2</b> <i>th</i>. φιλαι- <span>[ῐ]</span> φιλαίτερος, XÉN. <i>An. 1, 9, 29 ;</i> CALL. <i>Del. 58 ;</i> φιλαίτατος, PHILÉT. <i>11 ;</i> THCR. <i>Idyl. 7, 98 ;</i><br><b>      3</b> <i>th</i>. φιλ- : φίλτερος, IL. <i>11, 162 ;</i> OD. <i>11, 360 ;</i> HÉS. <i>O. 307 ;</i> ESCHL. <i>Pers. 851, etc. ;</i> φίλτατος, AR. <i>Eccl. 970 ;</i> PLUT. <i>M. 90</i> a, <i>etc. ; du même th. :</i> φιλίων, OD. <i>19, 351 ; 24, 268 ;</i> φίλιστος, SOPH. <i>Aj. 829 dout. ; on dit encore au cp</i>. μᾶλλον φίλος, ESCHL. <i>Ch. 219 ;</i> SOPH. <i>Ph. 886 ; au</i> <i>• Sup</i>. μάλιστα φίλος, XÉN. <i>Cyr. 8, 1, 16 ; ou</i> μέγιστος φίλος, SOPH. <i>Aj. 1331 ; de même</i> οἱ ἐγγυτάτω φίλοι, LYS. <i>95, 30 ;</i> οἱ ἔγγιστα φίλοι, POL. <i>9, 24, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. φίλος, PD. <i>O. 2, 170</i>.<br><span><b>Étym</b>. <i>inconnue ; le sens primit. est</i> « propre, qui accompagne ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλος - φίλος</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 27 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (15)</li>\n<li>Jean (6)</li>\n<li>Actes (3)</li>\n<li>Jacques (2)</li>\n<li>3 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G5385":"<h1>philosophia</h1>\n<p>Strong n° 5385 <i>Prononciation [fil-os-of-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amour de la sagesse\n<ol type=\"a\">\n<li>utilisé pour le zèle ou l'habileté dans tout art ou science, toute branche de la connaissance. Utilisé seulement une fois dans le N.T. pour théologie, ou mieux théosophie, de certains ascètes chrétiens, qui s'occupaient par des questions subtiles et raffinées, telles la nature, la hiérarchie, le sexe des anges, dans le rituel de la loi Mosaïque et les contraintes de la tradition Juive concernant la vie pratique.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλοσοφία, ας (ἡ)</b> <span>[φῐλ]</span><br><b>      1</b> amour de la science, <i>d’où</i> recherche, étude <i>ou</i> pratique d’un art <i>ou</i> d’une science, PLAT. <i>Phæd. 61</i> a, <i>Gorg. 484</i> c, <i>etc. ; joint à</i> παιδεία, ISOCR. <i>276</i> d ; <i>à</i> κτῆσις ἐπιστήμης, PLAT. <i>Euthyd. 288</i> d ; <i>à</i> μουσική, T. LOCR. <i>104</i> a, <i>etc. ; d’où</i> la science, la culture intellectuelle elle-même, <i>joint à</i> ἱστορία, ISOCR. <i>284 ; au plur. joint à</i> τέχναι, ISOCR. <i>209</i> b ; <i>à</i> λόγος, PLUT. <i>Dio. 13, M. 82</i> f ;<br><b>      2</b> <i>particul</i>. culture méthodique d’un art : <i>de l’éloquence,</i> ISOCR. <i>42</i> e ; <i>joint à</i> ῥητορική, DH. <i>Thuc. 50, 3 ; à</i> λόγοι, LUC. <i>Dem. enc. 14 ; ou de la dialectique :</i> ἡ περὶ τὰς ἔριδας φ. ISOCR. <i>209</i> b, étude scientifique de l’argumentation ;<br><b>      3</b> <i>abs</i>. recherche de l’essence des choses, étude des choses de la nature, recherche de la vérité, <i>d’où</i> philosophie, PLAT. <i>Def. 411</i> b ; <i>qqf. avec l’article :</i> ἡ φ. PLAT. <i>Gorg. 482</i> a ; ISOCR. <i>24</i> e, <i>99</i> a, <i>148</i> e, <i>etc. ; d’ord. sans article,</i> PLAT. <i>Phæd. 68</i> c, <i>etc. ;</i> ARSTT. <i>Pol. 8, 7, 2, etc. ; avec l’art. lorsque le mot est accompagné d’un adj. ou d’un déterminat. :</i> ἡ θεία φ. PLAT. <i>Phædr. 239</i> b, la divine philosophie ; ἡ περὶ τὰ ἀνθρώπινα φ. ARSTT. <i>Nic. 10, 9, 22,</i> la philosophie qui concerne les choses humaines ; ἡ δογματική, Ἀκαδημαϊκή, SEXT. <i>P. 1, 4, etc</i>. la philosophie dogmatique, de l’Académie, <i>etc. ; au plur</i>. les systèmes de philosophie, PLAT. <i>Theæt. 172</i> c, <i>etc</i>.<br><span><b>Étym</b>. φιλόσοφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοσοφια - φιλοσοφία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5386":"<h1>philosophos</h1>\n<p>Strong n° 5386 <i>Prononciation [fil-os'-of-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un philosophe, quelqu'un qui s'adonne à la poursuite de la sagesse ou du savoir</li>\n<li>dans un sens plus étroit, quelqu'un qui s'interroge et discute la raison et la cause des choses, et sur le plus grand bien</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλό·σοφος, ος, ον</b> <span>[ῐ]</span><br><b>A <i>adj. :</i><br>   I. 1</b> qui aime, recherche <i>ou</i> pratique un art <i>ou</i> une science : φ. ἀνήρ, XÉN. <i>Œc. 16, 9 ;</i> PLAT. <i>Phæd. 64</i> d, <i>etc. ;</i> PLUT. <i>Per. 26, etc</i>. homme qui a le goût des choses de l’esprit ; φ. γένος, PLAT. <i>Rsp. 501</i> e, race qui a le goût des choses de l’esprit ; <i>en parl. de choses abstraites : φιλόσοφος φύσις,</i> PLAT. <i>Rsp. 376</i> b, nature portée aux choses de l’esprit ; διάνοια, PLAT. <i>Rsp. 527</i> b ; φροντίς, PLUT. <i>M. 136</i> d, intelligence qui s’applique aux choses de l’esprit ;<br><b>      2</b> <i>particul</i>. qui a un caractère scientifique <i>ou</i> philosophique, <i>en parl. de discours,</i> PLAT. <i>Phædr. 257</i> b ; ISOCR. <i>289</i> e ; ARSTT. <i>Poet. 9, 3 ;</i> τὸ φιλόσοφον, <i>c</i>. φιλοσοφία, PLAT. <i>Rsp. 411</i> e, <i>etc. ;</i><br><b>B</b> <i>subst. :</i><br><b>   I</b> ὁ φιλόσοφος, philosophe :<br><b>      1</b> homme d’éducation libérale, qui a le goût des choses de l’esprit, homme instruit, <i>en gén. joint à</i> φιλομαθής, PLAT. <i>Rsp. 376</i> b ; <i>à</i> πεπαιδευμένος, LUC. <i>M. cond. 36 ; à</i> φιλόλογος, PLAT. <i>Rsp. 582</i> e ; <i>à</i> φιλόκαλος, PLUT. <i>M. 80</i> e ; PLAT. <i>Rsp. 475</i> b ; <i>joint à</i> σοφιστής, XÉN. <i>Vect. 5, 4 ; mais distinct de</i> σοφιστής, XÉN. <i>Cyn. 13, 6, 9 ; tenant le milieu entre</i> σοφός <i>et</i> ἀμαθής, PLAT. <i>Conv. 204</i> a ; <i>d’où particul</i>. maître de rhétorique, PLAT. <i>Conv. 182</i> e ; ISOCR. <i>Panath. 1 ; joint à</i> διδάσκαλος, PLUT. <i>M. 145</i> c ;<br><b>      2</b> <i>particul</i>. philosophe, <i>càd</i>. qui s’occupe des choses de la nature, de la recherche de la vérité, <i>différent de</i> σοφός, comme étant celui qui tend par ses efforts à la σοφία, ISOCR. <i>227</i> a ; DL. <i>Proœm. 12 ;</i> CIC. <i>Tusc. 5, 3 et 4 ;</i> φιλόσοφοι τὴν φύσιν, PLAT. <i>Rsp. 376</i> b ; PLUT. <i>M. 122</i> d ; φιλόσοφος φύσει, PLAT. <i>Rsp. 376</i> c, philosophes, philosophe de nature ; φ. τῇ ψυχῇ, ISOCR. <i>11</i> a, philosophe par les sentiments, <i>p. opp. à</i> τῷ σώματι φιλόπονος ; <i>abs</i>. ὁ φιλόσοφος, <i>en parl. d’Aristote,</i> PLUT. <i>Alex. 7 ;</i><br><b>      3</b> <i>p. ext</i>. toute personne menant une vie austère, <i>en parl. de Caton,</i> PLUT. <i>Pomp. 39 ; même de femmes, en parl. de Porcia,</i> PLUT. <i>Brut. 13 ; p. anal. en parl. de la divinité,</i> PLAT. <i>Tim. 24</i> d ; <i>postér. en parl. des chrétiens,</i> CLÉM. <i>642 ; etc. ;</i><br><b>   II</b> τὸ φιλόσοφον :<br><b>      1</b> les connaissances philosophiques, la philosophie, <i>p. opp. à la rhétorique et aux mathématiques,</i> PLUT. <i>M. 744</i> d ;<br><b>      2</b> manière de vivre d’un philosophe, PLAT. <i>Rsp. 411</i> e ; PLUT. <i>Sol. 3, M. 715</i> c.<br><span>•<i> Cp</i>. φιλοσοφώτερος, ISOCR. <i>289</i> e ; ARSTT. <i>Poet. 9, 3 ;</i> <i>• Sup</i>. φιλοσοφώτατος, PLAT. <i>Rsp. 498</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Dans φιλόσοφος la pénult. allongée à cause du</i> φ, AR. <i>Eccl. 571</i>.<br><span><b>Étym</b>. φ. σοφός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοσοφος - φιλόσοφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5387":"<h1>philostorgos</h1>\n<p>Strong n° 5387 <i>Prononciation [fil-os'-tor-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'amour mutuel des parents et enfants, des maris et épouses</li>\n<li>amour affectueux, promptitude à aimer, aimer tendrement\n<ol type=\"a\">\n<li>se dit surtout de la tendresse réciproque des parents et enfants</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλό·στοργος, ος, ον</b> <span>[ῐ]</span> qui aime tendrement les siens, plein de tendresse pour les siens, XÉN. <i>Cyr. 1, 3, 2 ;</i> THCR. <i>Idyl. 18, 13, etc. ; avec πρός et l’acc</i>. PLUT. <i>M. 608</i> c ; EL. <i>N.A. 2, 40 ; avec εἰς et l’acc</i>. NT. <i>Rom. 12, 10 ; avec περί et l’acc</i>. PLUT. <i>Cleom. 1 ;</i> τὸ φιλόστοργον, XÉN. <i>Ages. 8, 1 ;</i> PLUT. <i>M. 144</i> f, <i>Sol. 7,</i> la tendresse pour les siens.<br><span>•<i> Cp</i>. -ότερος, CIC. <i>Att. 13, 9</i>.<br><span><b>Étym</b>. φ. στέργω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοστοργος - φιλόστοργος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5388":"<h1>philoteknos</h1>\n<p>Strong n° 5388 <i>Prononciation [fil-ot'-ek-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aimer sa descendance, ses enfants</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλό·τεκνος, ος, ον :<br>      1</b> qui aime ses enfants, EUR. <i>H.f. 636 ;</i> AR. <i>Th. 752 ;</i> ARSTT. <i>Nic. 9, 7, 7 ;</i> PLUT. <i>Æmil. 6 ;</i> τὸ φ. PLUT. <i>M. 93</i> f, <i>c</i>. φιλοτεκνία ;<br><b>      2</b> qui aime ses petits, HDT. <i>2, 66 ;</i> ARSTT. <i>H.A. 6, 11, 2 ;</i> CALL. <i>Cer. 84</i>.<br><span>•<i> Cp</i>. -ότερος, ARSTT. <i>Nic. 9, 7, 7 ;</i> SPT. <i>4Macc. 15, 5 ;</i> <i>• Sup</i>. -ότατος, PLUT. <i>M. 213</i> e, <i>Æmil. 6 ;</i> NAZ. <i>1, 904</i> b ; HORAP. <i>1, 53</i>.<br><span><b>Étym</b>. φ. τέκνον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοτεκνος - φιλότεκνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G5389":"<h1>philotimeomai</h1>\n<p>Strong n° 5389 <i>Prononciation [fil-ot-im-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être fondé sur l'honneur\n<ol type=\"a\">\n<li>être animé l'amour de l'honneur</li>\n<li>amour de l'honneur qui fait lutter pour qu'une chose se fasse</li>\n</ol>\n</li>\n<li>être ambitieux\n<ol type=\"a\">\n<li>s'efforcer sérieusement, viser son but</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλοτιμέομαι-οῦμαι</b> <span>[ῐῑ]</span> <span>(<i>f</i>. -ήσομαι <i>et au sens moy</i>. -ηθήσομαι, <i>ao</i>. ἐφιλοτιμησάμην <i>et au sens moy</i>. ἐφιλοτιμήθην, <i>pf</i>. πεφιλοτίμημαι)</span><br><b>   I</b> <i>litt</i>. aimer l’honneur, <i>d’où :</i><br><b>      1</b> aimer et chercher de l’honneur, avoir de l’ambition, <i>abs</i>. PLAT. <i>2 Alc. 146</i> a ; PLUT. <i>Marc. 14, etc. ; d’où au part</i>. φιλοτιμούμενος, qui agit par ambition <i>ou</i> rivalité, LYS. <i>163 ;</i> PLUT. <i>Per. 13 ;</i> φ. ἐπί τινι, XÉN. <i>Mem. 2, 6, 11 ;</i> PLAT. <i>Rsp. 553</i> d, <i>etc. ;</i> ἔν τινι, PLAT. <i>Lach. 182</i> b, mettre son honneur dans qqe ch. ; φ. ὑπέρ τινος, ISOCR. <i>178</i> a, se soucier d’obtenir la considération ; περί τινος, PLUT. <i>M. 376</i> a, se faire honneur de qqe ch. ;<br><b>      2</b> regarder <i>ou</i> désirer comme un honneur, <i>d’où</i> rechercher, ambitionner : τι, XÉN. <i>Œc. 4, 24,</i> qqe ch. ;<br><b>      3</b> <i>p. suite,</i> travailler, s’efforcer, faire tous ses efforts ; περί τι, DS. <i>3, 18 ;</i> PLUT. <i>M. 822</i> d, <i>etc. ;</i> εἴς τι, DS. <i>1, 50 ; 4, 53, etc. ;</i> πρός τι, POL. <i>1, 4, 2 ;</i> PLUT. <i>Demetr. 28,</i> en vue de qqe ch. ; πρός τινα, PLAT. <i>Conv. 178</i> e ; PLUT. <i>Alex. 56 ;</i> LUC. <i>Gall. 6, etc</i>. rivaliser d’amour-propre avec qqn ; <i>avec un inf</i>. XÉN. <i>Mem. 2, 9, 3 ;</i> HIPP. <i>1, 21 ;</i> PLUT. <i>Thes. 25 et 36, Sol. 32, M. 1055</i> b, <i>etc. ; avec une prop. inf</i>. XÉN. <i>Hipp. 1, 25 ;</i> PLUT. <i>Them. 5 ; avec</i> ὅτι, être jaloux <i>ou</i> éprouver du dépit de ce que, <i>etc</i>. XÉN. <i>An. 1, 4, 7, etc. ; avec</i> μή, PLAT. <i>Ep. 338</i> e ; <i>avec un part</i>. XÉN. <i>Hipp. 9, 6 ;</i> PLAT. <i>Rsp. 336</i> c, <i>etc. ;</i><br><b>      4</b> faire le glorieux, le fier, LYS. <i>143, 30 ; en b. part,</i> se piquer de générosité, se montrer généreux, libéral : εἴς τινα, ATT. ; πρός τινα, ATT. à l’égard de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. au sens pass</i>. ARSTD. <i>34, 446</i>.<br><span><b>Étym</b>. φιλότιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοτιμεομαι - φιλοτιμέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5390":"<h1>philophronos</h1>\n<p>Strong n° 5390 <i>Prononciation [fil-of-ron'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec bonté, d'une manière amicale, courtoisement, amicalement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιλοφρόνως</b> <span>[ῐ]</span> <i>adv</i>., avec des sentiments d’amitié <i>ou</i> de bienveillance, HDT. <i>2, 121 ; 3, 13, 51 ;</i> XÉN. <i>Cyr. 3, 3, 10 ;</i> PLAT. <i>Criti. 120</i> e.<br><span>•<i> Cp</i>. -ώτερον, HPC. <i>ou</i> -εστέρως, XÉN. <i>Conv. 1, 10</i>.<br><span><b>Étym</b>. φιλόφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοφρονως - φιλοφρόνως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5391":"<h1>philophron</h1>\n<p>Strong n° 5391 <i>Prononciation [fil-of'-rone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amical, aimable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ταπεινό·φρων</b>, <i>gén</i>. <b>ονος (ὁ, ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> qui a des sentiments peu élevés, pusillanime, PLUT. <i>M. 336</i> e ;<br><b>      2</b> <i>en b. part,</i> humble, SPT. <i>Prov. 29, 23</i>.<br><span><b>Étym</b>. ταπεινός, φρήν.</span><br><br>\n<b>φιλό·φρων, ων, ον</b>, <i>gén</i>. <b>ονος</b> <span>[ῐ]</span> qui a des sentiments d’amitié <i>ou</i> de bienveillance, bienveillant, bon, PD. <i>P. 1, 184 ; 8, 1 ;</i> ESCHL. <i>Pers. 97 ;</i> XÉN. <i>Mem. 3, 1, 6, etc. ;</i> τὸ φιλόφρον, PLUT. <i>M. 1102</i> d, la bienveillance, la bonté.<br><span><b><span class=\"arrow\"></span></b> <i>• Sup</i>. φιλοφρονέστατος, XÉN. <i>Mem. 3, 5, 3</i>.<br><span><b>Étym</b>. φ. φρήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιλοφρων - ταπεινόφρων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5392":"<h1>phimoo</h1>\n<p>Strong n° 5392 <i>Prononciation [fee-mo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fermer la bouche par une muselière, museler</li>\n<li>métaph.\n<ol type=\"a\">\n<li>fermer la bouche, rendre sans voix, réduire au silence</li>\n<li>devenir silencieux</li>\n</ol>\n</li>\n<li>être gardé sous contrôle</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φιμόω-ῶ</b> <span>[ῑ]</span> lier fortement la tête, <i>particul. :</i><br><b>      1</b> museler, <i>acc</i>. SPT. <i>Deut. 25, 4 ; fig</i>. réduire au silence, NT. <i>Matth. 22, 34 ; au pass</i>. NT. <i>Marc. 1, 24 ; 4, 39 ; fig</i>. LUC. <i>Per. 15 ;</i> φιμώθητι, NT. <i>Luc. 4, 35 ; Marc. 1, 25 ;</i> πεφίμωσο, NT. <i>Marc. 4, 39,</i> sois muselé ! <i>càd</i>. paix ! silence ! φιμοῦσθαι πρός τι, JOS. <i>B.J. proœm. 5 ;</i> SEXT. <i>M. 8, 275,</i> être muet pour qqe ch. ;<br><b>      2</b> enserrer <i>ou</i> étreindre le cou, <i>particul</i>. attacher au pilori, AR. <i>Nub. 592</i>.<br><span><b>Étym</b>. φιμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φιμοω - φιμόω</font>\n<br><br>vient de phimos (une muselière)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5393":"<h1>Phlegon</h1>\n<p>Strong n° 5393 <i>Prononciation [fleg'-one]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Phlégon (Angl. Phlegon) = « brûlant, mordant »\n<ol><li>un résident de Rome salué par Paul dans l'épître aux Romains</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Φλέγων (ὁ)</b> Phlégôn, <i>n. de chien,</i> XÉN. <i>Cyn. 7, 5</i>.<br><span><b>Étym</b>. φλέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Φλεγων - Φλέγων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5394":"<h1>phlogizo</h1>\n<p>Strong n° 5394 <i>Prononciation [flog-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>allumer, mettre en feu</li>\n<li>brûler, enflammer</li>\n<li>fig. agir d'une manière destructrice, avoir le pouvoir le plus pernicieux\n<ol type=\"a\">\n<li>de ce dans quoi les influences destructrices sont allumées</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φλογίζω</b> <span>(<i>f</i>. -ιῶ, <i>ao</i>. ἐφλόγισα, <i>pass. ao</i>. ἐφλογίσθην)</span><br><b>   I <i>tr. :</i><br>      1</b> enflammer, <i>au pass</i>. être enflammé, SOPH. <i>Tr. 95 ;</i><br><b>      2</b> consumer par la flamme, SOPH. <i>Ph. 1199 ;</i> SPT. <i>Ps. 96, 3 ; au pass</i>. être consumé, ARSTT. <i>Mund. 5, 11 ; fig. en parl. de la langue,</i> NT. <i>Jac. 3, 6 ;</i><br><b>   II <i>intr.</i></b> brûler, SPT. <i>Ex. 9, 23</i>.<br><span><b>Étym</b>. φλόξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φλογιζω - φλογίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G5395":"<h1>phlox</h1>\n<p>Strong n° 5395 <i>Prononciation [flox]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une flamme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φλόξ, φλογός (ἡ) :<br>   I</b> flamme, <i>particul. :</i><br><b>      1</b> flamme du feu, <i>avec un gén. :</i> φλ. Ἡφαίστοιο, IL. <i>23, 33 ;</i> OD. <i>24, 71, etc. ; ou</i> φλ. πυρός, PD. <i>P. 4, 400 ;</i> EUR. <i>Bacch. 8, etc., m. sign. ; joint à</i> πῦρ, IL. <i>9, 212 ; particul</i>. flamme d’un bûcher, IL. <i>23, 228, etc. ;</i> feu d’un sacrifice, ESCHL. <i>Ag. 583 ;</i> SOPH. <i>Ant. 1020, etc. ;</i> EUR. <i>Tr. 1063, etc. ;</i> φλόγα ἀναιθύσσειν, EUR. <i>Tr. 344,</i> faire jaillir la flamme ; ἐγείρειν, XÉN. <i>Conv. 2, 24,</i> exciter la flamme ; παρακαλεῖν, XÉN. <i>Cyr. 7, 5, 23,</i> provoquer, <i>càd</i>. exciter la flamme ; μεγάλην ποιεῖν, LUC. <i>Tim. 6,</i> faire une grande flamme ; φλόγα λάμπειν, PLUT. <i>Fab. 2,</i> faire briller une flamme ; φλόγα ἐμϐάλλειν τινί, EUR. <i>Rhes. 120, Alc. 4,</i> mettre le feu à qqe ch. ; σϐέσαι, THC. <i>2, 77,</i> éteindre la flamme ; φλὸξ ἀπέσσυτο, HÉS. <i>Th. 859,</i> la flamme s’élançait ; φλ. ἀπορρεῖ, PLAT. <i>Tim. 83</i> b, la flamme se répand ; φλ. ἀποσϐεσθεῖσα, PLAT. <i>Tim. 67</i> c, flamme éteinte ; <i>dans les comparaisons :</i> φλογὶ ἴσος, IL. <i>13, 39, etc</i>. semblable à une flamme, <i>en parl. d’un guerrier ardent ; cf</i>. IL. <i>13, 330, 688, etc. ; au plur</i>. ORPH. <i>Lith. 173, 183 ;</i> ARSTT. <i>Meteor. 1, 4 ;</i> NIC. (ATH. <i>684</i> a), <i>etc. ;</i><br><b>      2</b> flamme, <i>en gén. en parl. de la flamme des torches,</i> EUR. <i>Bacch. 146 ; d’une lampe,</i> XÉN. <i>Conv. 7, 4, etc. ; en parl. d’un volcan,</i> PD. <i>P. 1, 45 ; d’un éclair,</i> ESCHL. <i>Pr. 359, 922, 1017 ;</i> EUR. <i>Med. 144 ; des rayons du soleil,</i> ESCHL. <i>Pr. 22, etc. ;</i> SOPH. <i>Tr. 696, O.R. 1425, etc. ; p. anal. en parl. de la lueur divine qui se répand de la tête d’Achille à côté d’Athènè,</i> IL. <i>18, 206 ; d’une épée nue, d’où</i> l’épée elle-même, SPT. <i>Judith 3, 22 ; 1 Sam. 17, 7, etc. ; de pierres précieuses,</i> PD. <i>fr. 88 ;</i> éclat des yeux, NT. <i>Apoc. 1, 14 ;</i><br><b>      3</b> <i>fig</i>. ardeur, feu du vin, EUR. <i>Alc. 758 ;</i> XÉN. <i>Conv. 2, 24 ; en parl. d’un fléau,</i> SOPH. <i>O.R. 166 ; de l’ardeur belliqueuse,</i> EUR. (LYC. <i>161</i>) ;<br><b>   II</b> phlox, <i>sorte de plante,</i> TH. <i>H.P. 2, 6, 2 ;</i> PLUT. <i>M. 993</i> f.<br><span><b>Étym</b>. φλέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φλοξ - φλόξ</font>\n<br><br>vient du mot primaire 'phlego' (« éclairer » ou « flamboyer »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G5396":"<h1>phluareo</h1>\n<p>Strong n° 5396 <i>Prononciation [floo-ar-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prononcer une absurdité, dire des paroles en l'air, jaser, dire des sornettes</li>\n<li>rapporter des accusations vaines, vides de sens, tenir de mauvais propos contre</li>\n<li>accuser quelqu'un faussement par des mots méchants</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φλυαρέω-ῶ</b> <span>[ᾱ]</span><br><b>      1</b> dire des sornettes, bavarder à tort et à travers, HDT. <i>2, 131 ; 7, 103, 104 ;</i> AR. <i>Eq. 543 ; Vesp. 85 ; Pl. 360, 575 ;</i> XÉN. <i>Hell. 3, 1, 18 ;</i> πολλὴν φλυαρίαν φλυαρεῖν, PLAT. <i>Ap. 19</i> c, débiter une foule de niaiseries ;<br><b>      2</b> amuser par des sornettes, <i>acc</i>. NT. <i>Joh. 3, 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. φλυηρέω, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. φλύαρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φλυαρεω - φλυαρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5397":"<h1>phluaros</h1>\n<p>Strong n° 5397 <i>Prononciation [floo'-ar-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de personnes prononçant ou faisant des choses sottes, bavardes, occupées à des babillages, badin, plaisantin, babillard</li>\n<li>de choses insensées, insignifiantes, vaines</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φλύαρος, ος, ον</b> <span>[ᾱ]</span><br><b>      1</b> bavard, qui parle à tort et à travers, PLAT. <i>Ax. 369</i> d ; SPT. <i>4Macc. 5, 10 ;</i> NT. <i>1Tim. 5, 13, etc. ;</i><br><b>      2</b> bavardage, niaiserie, sornette, AR. <i>Nub. 364 ;</i> PLAT. <i>Ax. 365</i> e ; PLUT. <i>Cic. 2, etc</i>.<br><span>•<i> Cp</i>. φλυαρότερος, ARR. <i>Epict. 2, 19, 10</i>.<br><span><b>Étym</b>. φλύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φλυαρος - φλύαρος</font>\n<br><br>vient de phluo (babiller)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5398":"<h1>phoberos</h1>\n<p>Strong n° 5398 <i>Prononciation [fob-er-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>inspirant la crainte, terrible, effrayant, formidable</li>\n<li>affecté par la crainte, timide</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φοϐερός, ά, όν :<br>   I</b> <i>act. :</i> qui cause de l’effroi, effrayant, terrible, <i>en parl. de pers. et de choses, joint à</i> ἐς δεῖμα βαλόντα, HDT. <i>7, 139 ; à</i> μέγας, ESCHL. <i>Sept. 78 ;</i> PLUT. <i>M. 98</i> e ; <i>à</i> ἰσχυρός, PLAT. <i>Phil. 49</i> b, <i>etc. ; à</i> δεινός, PLAT. <i>Ion 535</i> c, <i>etc. ; à</i> εὐπρεπέστερος, PLUT. <i>M. 189</i> e, <i>etc. ; à</i> ἄγριος, PLUT. <i>M. 148</i> c ; <i>avec le dat. de la pers. à qui qqe ch. est redoutable,</i> XÉN. <i>Hipp. 4, 11, etc. ; acc. avec un déterminat. :</i> φ. τὴν πρόσοψιν, LUC. <i>Philops. 6,</i> d’aspect effrayant ; <i>avec le dat. de manière,</i> ISOCR. <i>198 ; avec un inf. :</i> φοϐεροὶ ἰδεῖν, ESCHL. <i>Pers. 27 ;</i> φοϐερὰν ὄψιν προσιδέσθαι, ESCHL. <i>Pers. 48,</i> effrayant <i>ou</i> terrible à voir ; <i>cf</i>. EUR. <i>Ph. 128 ;</i> XÉN. <i>An. 3, 4, 5 ;</i> LUC. <i>D. mort. 15, 2, etc. ;</i> τῶν φοϐερῶν ὄντων τῇ πόλει γενέσθαι ἡγεμών, XÉN. <i>Hell. 1, 4, 17,</i> auteur des maux dont on devait craindre qu’ils n’atteignissent l’État ; <i>avec</i> μή : ἵππος φοϐερὸς μὴ ἀνήκεστόν τι ποιήσῃ, XÉN. <i>Hier. 6, 15,</i> cheval dont on peut craindre qu’il ne fasse qqe malheur irrémédiable ; <i>cf</i>. XÉN. <i>Cyr. 7, 5, 22 ; An. 5, 7, 2, etc. ;</i> φοϐερόν (<i>s.-e</i>. ἐστι) μή, XÉN. <i>Hier. 1, 11,</i> il est à craindre que, <i>etc. ; abs. au neutre :</i> φοϐερὸν ἡ τριήρης, XÉN. <i>Œc. 8, 8,</i> la trirème est chose effrayante ; φοϐερὸν ὁ πόλεμος, XÉN. <i>Hier. 6, 9,</i> la guerre est chose terrible ; <i>cf</i>. XÉN. <i>Cyr. 5, 4, 49 ;</i> PLUT. <i>M. 169</i> a, <i>etc. ; en b. part,</i> étonnant, admirable, <i>en parl. des œuvres de Dieu,</i> D. CHR. <i>1, 492, etc. ; en parl. de pers</i>. imposant, grave, AND. <i>31, 27 ;</i> PLUT. <i>Pyrrh. 3, etc. ; en parl. de choses,</i> imposant, DH. <i>Pomp. 3 ;</i> D. PHAL. §§ <i>130, 131 ;</i><br><b>   II</b> <i>pass</i>. : qui éprouve de la crainte, craintif, inquiet, SOPH. <i>O.R. 153 ; p. opp. à</i> ἄφοϐος, PLAT. <i>Leg. 647</i> b ; <i>à</i> θαρράλεος, THC. <i>2, 3 ;</i> XÉN. <i>Cyr. 3, 3, 19 ;</i> φοϐερόν τινα ποιεῖν, PLAT. <i>Leg. 647</i> c, rendre qqn craintif ; φ. εἴς τι, PLAT. <i>Leg. 669</i> d, craintif pour qqe ch. ; <i>subst</i>. τὸ φοϐερόν, THC. <i>6, 55 ;</i> PLAT. <i>Ax. 369</i> c, la crainte.<br><span>•<i> Cp</i>. -ώτερος, THC. <i>2, 3 ;</i> XÉN. <i>Cyr. 3, 3, 28 ;</i> AND. <i>31, 27 ;</i> <i>• Sup</i>. -ώτατος, THC. <i>2, 98 ;</i> XÉN. <i>An. 2, 5, 9 ; 3, 4, 5 ; Vect. 4, 39 ;</i> PLAT. <i>Gorg. 525</i> c, <i>etc</i>.<br><span><b>Étym</b>. φοϐέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φοβερος - φοβερός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – toujours utilisé dans un sens mauvais\n<br><br> – généralement utilisé dans un bon sens\n<br><br> – utilisé dans un bon ou mauvais sens</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G5399":"<h1>phobeo</h1>\n<p>Strong n° 5399 <i>Prononciation [fob-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire fuir en terrifiant (effrayer)\n<ol type=\"a\">\n<li>pousser à la fuite, s'enfuir</li>\n<li>craindre, avoir peur\n<ol>\n<li>être frappé de crainte, saisi par l'angoisse\n<ol type=\"a\">\n<li>de ceux effrayés par d'étranges visions ou événements</li>\n<li>de ceux qui sont frappés de stupeur</li>\n</ol>\n</li>\n<li>craindre, avoir peur de quelqu'un</li>\n<li>craindre (hésiter) à faire quelque chose (par crainte de mal faire)</li>\n</ol>\n</li>\n<li>révérer, vénérer, traiter avec déférence ou une obéissance révérencieuse</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>φοϐέω-ῶ</b> <span>(<i>f</i>. -ήσω, <i>ao</i>. ἐφόϐησα, <i>pf. inus. ; pass. f</i>. φοϐήσομαι, <i>ao</i>. ἐφοϐήθην, <i>pf</i>. πεφόϐημαι)</span><br><b>   I <i>Act. :</i><br>      1</b> mettre en fuite ; ἴρηξ ἐφόϐησε κολοιούς, IL. <i>16, 583,</i> l’épervier effraye et met en fuite les geais ; αἱ κάμηλοι ἐφόϐουν τοὺς ἵππους, XÉN. <i>Cyr. 7, 1, 48,</i> les chamelles faisaient fuir les chevaux ; <i>au pass</i>. être mis en fuite : ὑπό τινος, IL. <i>8, 149 ; ou</i> ὑπό τινι, IL. <i>15, 637,</i> par qqn, fuir devant qqn ; φ. τινα, IL. <i>22, 250,</i> fuir qqn ;<br><b>      2</b> effrayer : φ. τινα, IL. <i>16, 689, etc. ;</i> BATR. <i>297 ;</i> HDT. <i>7, 235 ;</i> PLAT. <i>Leg. 933</i> c, qqn ; στίχας ἀνδρῶν, IL. <i>17, 505,</i> les rangs des guerriers ; <i>en parl. d’états, d’actions :</i> σὸς δόλος ἐφόϐησε λαούς, IL. <i>15, 15,</i> ta ruse a effrayé et fait fuir les troupes ; <i>cf</i>. SOPH. <i>O.R. 296 ;</i> EUR. <i>Hipp. 573 ;</i> PLAT. <i>Tim. 71</i> b, <i>etc. ; abs</i>. ὁ μὴ φοϐῶν πόνος, SOPH. <i>Ph. 864,</i> entreprise sans danger (non effrayante) ; <i>avec dat. du moyen par lequel on effraye qqn :</i> φ. δουρί, IL. <i>20, 187 ;</i> λόγοις, ESCHL. <i>Pers. 211,</i> effrayer avec la lance, par des paroles, <i>etc. ; cf</i>. PLAT. <i>Theag. 121</i> c ; φ. ἐκ τούτου, PLUT. <i>Cam. 3,</i> effrayer par ce moyen ; <i>avec un part. :</i> λέγοντες φοϐῶσι τοὺς ἱππέας, XÉN. <i>Hipp. 1, 8,</i> ils effraient les cavaliers par leurs discours ; <i>avec</i> μή, XÉN. <i>An. 4, 5, 17 ; avec</i> ὡς : πάντες οἱ λέγοντες φοϐοῖεν ὡς ἥξει βασιλεύς, DÉM. <i>185,</i> (si) tous les orateurs répandaient la nouvelle terrible, que le roi vient ;<br><b><i>   II <i>au pass</i>. φοϐέομαι :<br>      1</i></b><i> <i>chez Hom</i>. être chassé par la crainte, être mis en fuite, fuir, IL. <i>5, 140 ; 11, 172 ; 12, 470 ; 16, 304 ; 21, 554 ; 22, 137 ;</i> OD. <i>19, 163 ;</i> PLAT. <i>Ap. 29</i> b ; <i>particul. au part. pf. pass</i>. πεφοϐημένος, mis en fuite, IL. <i>10, 510 ; 15, 4 ; 21, 606 ;</i> HDT. <i>9, 70 ;</i><br><b>      2</b> <i>postér</i>. être effrayé, ESCHL. <i>Sept. 1052 ;</i> PLAT. <i>Euthyphr. 12</i> b ; XÉN. <i>Hell. 4, 4, 12 ; Cyr. 5, 5, 11, etc. ; p. opp. à</i> θαρρεῖν, DÉM. <i>342, etc. ; particul. au part. pf. pass</i>. πάνυ ἐοικότας πεφοϐημένοις ἀνθρώποις, XÉN. <i>Cyr. 6, 2, 14,</i> tout à fait semblables à des hommes épouvantés ; <i>cf</i>. SOPH. <i>Aj. 139, 253 ;</i> THC. <i>7, 67 ; avec un rég. :</i> φ. τινι, IL. <i>16, 294, etc. ;</i> ὑπό τινος, IL. <i>8, 149 ;</i> ὑπό τινι, IL. <i>15, 637 ;</i> πρός τινος, <i>en prose réc</i>. SPT. <i>Ps. 21, 25 ; Jer. 17, 8,</i> par qqn <i>ou</i> qqe ch. ; ἀπό τινος, NT. <i>Matth. 10, 28 ;</i> περί τινος, XÉN. <i>Cyr. 3, 1, 25 ; 5, 2, 35, etc. ; ou</i> περί τινι, THC. <i>2, 90 ;</i> PLAT. <i>Euthyd. 275</i> d, pour l’amour de qqn <i>ou</i> de qqe ch. ; ἀμφί τινι, HDT. <i>6, 62,</i> au sujet de qqn ; περί τι, PLAT. <i>Crat. 404</i> e ; ὑπέρ τινος, XÉN. <i>Hier. 6, 10, etc. ;</i> πρός τι, SOPH. <i>Tr. 1213 ; en prose,</i> LUC. <i>Prom. 4 ;</i> ἐπί τινι, LUC. <i>D. mort. 14, 4 ;</i> εἴς τι, SOPH. <i>O.R. 980 ;</i> ἔκ τινος, SOPH. <i>Tr. 673,</i> au sujet de qqe ch. ; <i>avec l’acc</i>. IL. <i>22, 250 ;</i> ESCHL. <i>Suppl. 870 ;</i> XÉN. <i>Cyn. 5, 16 ;</i> PLAT. <i>Leg. 927</i> a, <i>etc. ; avec un acc. de même sign. :</i> φόϐους <i>et</i> φόϐον φ. PLAT. <i>Prot. 360</i> b, <i>etc</i>. éprouver des craintes, de la crainte ; <i>avec l’inf. précédé de l’article,</i> PLAT. <i>Gorg. 522</i> e, <i>etc. ; ou sans article, chez les Att</i>. SOPH. <i>Aj. 253 ;</i> THC. <i>5, 105 ;</i> XÉN. <i>Cyr. 8, 7, 15, etc</i>. craindre de, <i>etc. ; avec</i> μή, XÉN. <i>An. 1, 3, 17 ;</i> PLAT. <i>Gorg. 457</i> e, <i>etc</i>. craindre que, <i>etc. ; avec</i> ὅτι <i>pour exprimer l’idée d’un motif de crainte réel,</i> XÉN. <i>Hell. 3, 5, 10 ;</i> ISOCR. <i>388 ; rar. avec</i> ὡς, XÉN. <i>Cyr. 5, 2, 11 ; avec</i> πῶς, XÉN. <i>Cyr. 4, 5, 19 ; avec</i> ὅπως μή, XÉN. <i>Mem. 2, 9, 2 ; avec</i> εἰ <i>précédé de l’acc</i>. XÉN. <i>Cyr. 6, 1, 17, etc. ; avec un suj. de chose,</i> IL. <i>6, 135 ; 22, 137 ;</i> ARSTT. <i>Rhet. 2, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impér. 3 pl</i>. φοϐεόντων, HDT. <i>7, 235 ; impf. itér</i>. φοϐέεσκον, HÉS. <i>Sc. 162. Pass. prés. ind. poét</i>. φοϐεῦμαι, BION <i>3, 14 ; 2 sg. ion</i>. φόϐεαι, HDT. <i>1, 39 ; impér. 2 sg. ion</i>. φόϐεο, HDT. <i>7, 52, et</i> φοϐεῦ, HDT. <i>1, 9 ; part. ion</i>. φοϐεόμενος, HDT. <i>7, 235 ;</i> φοϐεύμενος, IL. <i>8, 149. Ao. ind. 3 pl. épq</i>. ἐφόϐηθεν, IL. <i>15, 326, 637, et</i> φόϐηθεν, IL. <i>5, 498, etc. ; sbj. 2 sg. dor</i>. φοϐαθῇς <span>[ᾱ]</span> THCR. <i>Idyl. 23, 41. Pl. q. p. 3 pl. poét</i>. πεφοϐήατο, IL. <i>21, 206</i>.<br><span><b>Étym</b>. φόϐος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">φοβεω - φοβέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – « être étonné », (frappé par le tonnerre...), être saisi de terreur, d'une soudaine et effrayante angoisse ; mais, comme notre mot « étonner », souvent utilisé pour des circonstances beaucoup plus simples dans le langage populaire\n<br><br> – « terrifier », remplir de crainte\n<br><br> – « trembler », terme à prédominance physique\n<br><br> – « craindre », terme général, souvent utilisé pour un état prolongé</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n96 fois dans 90 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (13)</li>\n<li>Luc (23)</li>\n<li>Jean (5)</li>\n<li>Actes (13)</li>\n<li>Romains (3)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (3)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>"};
